window.EB_SB_ADD({"strength-of-thousands-bestiary/book-3-hurricanes-howl/abendego-brute":{"lang":["Common"],"gear":["Fighter's Fork","Scale Mail","Religious Symbol of Norgorber (Wooden)"],"abilities":[{"n":"No Escape","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature within the brute's reach moves away from the brute</p>\n<hr>\n<p><strong>Effect</strong> The brute Strides up to their Speed, following the foe and keeping it in reach throughout this movement.</p>"},{"n":"Brute Strength","a":null,"c":"offensive","t":[],"f":"","d":"<p>Abendego brutes deal an extra 2d8 damage with tridents, and a trident gains the shove trait while the brute is using it in melee (both the extra damage dice and the shove trait are included in the <em>fighter's fork</em> Strikes above).</p>"},{"n":"Push","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Push in its damage entry</p><hr><p><strong>Effect</strong> The monster attempts to Shove the creature. This attempt neither applies nor counts toward the monster's multiple attack penalty. If Push lists a distance, change the distance the creature is pushed on a success to that distance.</p></p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/abendego-jailer":{"lang":["Common"],"gear":["Mancatcher","Dagger","Scale Mail","Manacles (Average)","Religious Symbol of Norgorber (Wooden)"],"abilities":[{"n":"Attack of Opportunity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Restrain","a":null,"c":"offensive","t":[],"f":"","d":"<p>When the jailer makes a successful mancatcher Strike, their target must succeed at a DC 27 Reflex save or become Grabbed until the end of the jailer's next turn.</p>\n<p>Each time the target fails an attempt to Escape the jailer, it takes 2d6 piercing damage.</p>"},{"n":"Subduing Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>Abendego jailers deal an additional 3d6 precision damage to creatures that are Frightened or within reach of at least one of their allies.</p>\n<p>The jailer can make an attack with this additional damage as a nonlethal attack, if they choose.</p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/abendego-priest":{"lang":["Common"],"gear":["Dagger","Shortsword","Studded Leather Armor","Religious Symbol of Norgorber (Wooden)","Shadow Essence (2)"],"focus":"2","abilities":[{"n":"Sodden Defense","a":"r","c":"defensive","t":["divine","water"],"f":"","d":"<p><strong>Trigger</strong> An attacker misses or critically misses the Abendego priest with a melee Strike</p>\n<hr>\n<p><strong>Effect</strong> The priest calls upon the endless storm to punish the attacker. Seawater appears in the target's lungs and the target is Sickened 1 (Sickened 3 if the triggering attack was a critical miss).</p>"},{"n":"Sneak Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>The Abendego priest deals an additional 2d6 precision damage precision damage to Off-Guard creatures.</p>"},{"n":"Steady Spellcasting","a":null,"c":"offensive","t":[],"f":"","d":"<p>If a reaction would disrupt the priest's spellcasting action, they attempt a DC 15 Flat. On a success, the action isn't disrupted.</p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/agitated-carnivorous-plants":{"description":"<p>Many carnivorous plants that were once kept satiated now hunger for any meat they can get, even lashing out onto the path to get it.</p>","disable":"<p>DC 25 Survival (trained) to distract or trick the plants or DC 22 Nature (expert) to calm the plants</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Trapping Vines","a":"r","c":"offensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature moves within reach of the carnivorous plants' vines</p>\n<hr>\n<p><strong>Effect</strong> The vines wrap around the triggering creature. The creature must succeed at a DC 22 Reflex save or be Grabbed until it Escapes. Whether or not the creature is grabbed, the plants make a gnawing plants Strike against the creature.</p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/ajbal-kimon":{"lang":["Common"],"gear":["Dagger","Trident","Scale Mail"],"abilities":[{"n":"Deny Advantage","a":null,"c":"defensive","t":[],"f":"","d":"<p>Ajbal isn't Off-Guard to creatures of 13th level or lower that are Hidden, undetected, flanking, or using surprise attack.</p>"},{"n":"Evasion","a":null,"c":"defensive","t":[],"f":"","d":"<p>When Ajbal rolls a success on a Reflex save, he gets a critical success instead.</p>"},{"n":"Nimble Dodge","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> Ajbal is targeted with a melee or ranged attack by an attacker he can see</p>\n<hr>\n<p><strong>Effect</strong> Ajbal gains a +2 circumstance bonus to AC against the triggering attack.</p>"},{"n":"Hunt Prey","a":"1","c":"offensive","t":["concentrate"],"f":"","d":"<p>Ajbal designates a single creature he can see and hear, or one he's Tracking, as his prey. Ajbal gains a +2 circumstance bonus to Perception checks to Seek his prey and Survival checks to Track his prey.</p>\n<p>The first time Ajbal hits his designated prey in a round, he deals an additional 2d8 precision damage. Ajbal also ignores the penalty for making ranged attacks within the second range increment when attacking his prey.</p>\n<p>These effects last until Ajbal uses Hunt Prey again.</p>"},{"n":"Sneak Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>Ajbal deals an additional 1d6 precision damage to Off-Guard creatures.</p>"},{"n":"Tear the Wound","a":"1","c":"offensive","t":[],"f":"","d":"<p><strong>Requirements</strong> Ajbal's last action was a melee Strike that dealt sneak attack damage to an Off-Guard target</p>\n<hr>\n<p><strong>Effect</strong> Ajbal deals 6 bleed damage to the target creature, and the target is Enfeebled 1 for as long as it's bleeding.</p>"},{"n":"Trident Bully","a":null,"c":"offensive","t":[],"f":"","d":"<p>A trident Ajbal is using gains the shove trait, and any creature Ajbal critically hits with a trident is Off-Guard until the start of Ajbal's next turn.</p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/alapolo":{"lang":["Common","Fey"],"lore":[["Shadow Lore",30]],"flavor":"<p>Short-lived, strange creatures called alapolos cling to the shadows in eerie moonlight, inviting others to dance. Although these \"shadow dancers\" aren't actively malevolent, they become petulant when others won't dance with them.</p>","abilities":[{"n":"Cloying Pull","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature within the alapolo's reach attempts to move away from the alapolo</p><hr>\n<p><strong>Effect</strong> The triggering creature must succeed at a DC 36 Reflex save or its movement ends before it leaves the alopolo's reach.</p>"},{"n":"One with Shadows","a":null,"c":"defensive","t":[],"f":"","d":"<p>The alapolo isn't affected by darkness, light, or shadow effects</p>"},{"n":"Enticing Invitation","a":"2","c":"offensive","t":["incapacitation","mental","primal"],"f":"","d":"<p>The alapolo whispers an invitation to a creature within 30 feet. The creature must attempt a DC 38 Will save.</p>\n<hr>\n<p><strong>Critical Success</strong> The target is unaffected and temporarily immune to all Enticing Invitations for 24 hours.</p>\n<p><strong>Success</strong> The target must spend 1 action on its next turn dancing in place.</p>\n<p><strong>Failure</strong> The target becomes Drained 1. It is also Fascinated by the alapolo for 1 minute and can't attack the alapolo as long as it's fascinated. While fascinated, the target must spend 2 actions on each of its turns dancing in place.</p>\n<p><strong>Critical Failure</strong> As failure, except the target is Drained 3 and must spend 3 actions on each of its turns dancing in place.</p>"},{"n":"Shifting Shadows","a":null,"c":"offensive","t":[],"f":"","d":"<p>An alapolo's movement doesn't trigger reactions.</p>"},{"n":"Weighty Shadow","a":"2","c":"offensive","t":["primal"],"f":"","d":"<p><strong>Requirements</strong> The alapolo is adjacent to a target creature, or the GM determines the alapolo is adjacent to that creature's shadow</p><hr>\n<p><strong>Effect</strong> The alapolo petulantly stomps on a target's shadow, making it incredibly heavy to drag around. The creature takes a –20-foot penalty to its Speeds for 1 minute. As normal, this penalty can't reduce a creature's Speed below 5 feet. Any creatures Fascinated by the alapolo due to its Enticing Invitation are freed from their fascination when the alapolo uses this ability, jarred by the graceless stomping.</p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/alate-ant":{"lang":["Common"],"abilities":[{"n":"Darting Flight","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Requirements</strong> The alate ant is flying</p>\n<p><strong>Trigger</strong> The ant is targeted with an attack by an attacker it can see</p>\n<hr>\n<p><strong>Effect</strong> The ant gains a +2 circumstance bonus to AC against the triggering attack.</p>"},{"n":"Frenzy","a":"1","c":"offensive","t":[],"f":"once per day","d":"<p><strong>Frequency</strong> Once per day</p>\n<hr>\n<p><strong>Effect</strong> The alate ant enters a state of jittery agitation. It becomes Quickened for 3 rounds and can use the extra action only to Fly or Strike.</p>"},{"n":"Pack Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>The alate ant deals an additional 3d6 precision damage to any creature within reach of at least two of the ant's allies.</p>"},{"n":"Pheromone Spray","a":"2","c":"offensive","t":["emotion","mental"],"f":"","d":"<p>The alate ant sprays a cloud of pheromones in a 15-foot cone. Non-ant creatures in the cone must succeed at a DC 37 Will save or become Confused for 1d4 rounds (1 minute on a critical failure). It can't use Pheromone Spray again for 1d4 rounds.</p>"},{"n":"Red Ant Venom","a":null,"c":"offensive","t":["poison"],"f":"","d":"<p>While a creature is enfeebled from this poison, it is Confused (this confusion is an emotion, enchantment, and mental effect).</p>\n<p><strong>Saving Throw</strong> DC 37 Fortitude</p>\n<p><strong>Maximum Duration</strong> 4 rounds</p>\n<p><strong>Stage 1</strong> 3d6 poison damage and Enfeebled 1 (1 round)</p>\n<p><strong>Stage 2</strong> 4d6 poison damage and Enfeebled 2 (1 round)</p>\n<p><strong>Stage 3</strong> 6d6 poison damage and Enfeebled 3 (1 round)</p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/anadi-fateweaver":{"lang":["Anadi","Common"],"gear":["Composite Shortbow","Shortsword","Hide Armor","Arrows (20)"],"flavor":"<p>The anadis manipulate the threads of fate as easily as they spin silk.</p>\n<hr>\n<p>Anadis have three distinct forms-human, spider, and a beautiful but unnerving hybrid shape that is their true form. Despite their unsettling arachnid features, anadis are peaceful and form tight-knit communities.</p>","abilities":[{"n":"Spin Silk","a":null,"c":"interaction","t":["concentrate","exploration","manipulate"],"f":"","d":"<p>By spending several minutes, an anadi can produce silk to craft items made of cloth. An anadi can produce enough silk in a day to craft a single garment.</p>"},{"n":"Fate's Threads","a":"r","c":"defensive","t":["fortune"],"f":"3 times per day","d":"<p><strong>Frequency</strong> three times per day</p>\n<p><strong>Trigger</strong> An ally within 30 feet of the anadi fateweaver that they can see makes a skill check or a saving throw</p>\n<hr>\n<p><strong>Effect</strong> The creature rerolls the triggering check and takes the new result.</p>"},{"n":"Anadi Venom","a":null,"c":"offensive","t":["poison"],"f":"","d":"<p><strong>Saving Throw</strong> DC 20 Fortitude</p>\n<p><strong>Maximum Duration</strong> 4 rounds</p>\n<p><strong>Stage 1</strong> 1d6 poison damage and Off-Guard (1 round)</p>\n<p><strong>Stage 2</strong> 1d6 poison damage, off-guard, and Clumsy 1 (1 round)</p>"},{"n":"Change Shape","a":"1","c":"offensive","t":["arcane","concentrate","polymorph"],"f":"","d":"<p>The anadi changes into their hybrid, spider, or human form. The above statistics assume the anadi is in hybrid form. While in human form, the anadi seeker loses their climb Speed and can't use their fangs attack. When in spider form, they can't use weapons.</p>\n<hr>\n<p><p>The monster changes its shape indefinitely. It can use this action again to return to its natural shape or adopt a new shape. Unless otherwise noted, a monster cannot use Change Shape to appear as a specific individual. Using Change Shape counts as creating a disguise for the Impersonate use of Deception. The monster's transformation automatically defeats Perception DCs to determine whether the creature is a member of the ancestry or creature type into which it transformed, and it gains a +4 status bonus to its Deception DC to prevent others from seeing through its disguise. Change Shape abilities specify what shapes the monster can adopt. The monster doesn't gain any special abilities of the new shape, only its physical form. For example, in each shape, it replaces its normal Speeds and Strikes, and might potentially change its senses or size. Any changes are listed in its stat block.</p></p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/anadi-lurker":{"lang":["Anadi","Common"],"gear":["Kukri","Leather Armor"],"flavor":"<p>These anadis lurkers combine their innate magical talents and wilderness lore to snare prey.</p>\n<hr>\n<p>Anadis have three distinct forms-human, spider, and a beautiful but unnerving hybrid shape that is their true form. Despite their unsettling arachnid features, anadis are peaceful and form tight-knit communities.</p>","abilities":[{"n":"Spin Silk","a":null,"c":"interaction","t":["concentrate","exploration","manipulate"],"f":"","d":"<p>By spending several minutes, an anadi can produce silk to craft items made of cloth. An anadi can produce enough silk in a day to craft a single garment.</p>"},{"n":"Anadi Venom","a":null,"c":"offensive","t":["poison"],"f":"","d":"<p><strong>Saving Throw</strong> DC 18 Fortitude</p>\n<p><strong>Maximum Duration</strong> 4 rounds</p>\n<p><strong>Stage 1</strong> 1d6 poison damage and Off-Guard (1 round)</p>\n<p><strong>Stage 2</strong> 1d6 poison damage, off-guard, and Clumsy 1 (1 round)</p>"},{"n":"Change Shape","a":"1","c":"offensive","t":["arcane","concentrate","polymorph"],"f":"","d":"<p>The anadi changes into their hybrid, spider, or human form. The above statistics assume the anadi is in hybrid form. While in human form, the anadi seeker loses their climb Speed and can't use their fangs attack. When in spider form, they can't use weapons.</p>\n<hr>\n<p><p>The monster changes its shape indefinitely. It can use this action again to return to its natural shape or adopt a new shape. Unless otherwise noted, a monster cannot use Change Shape to appear as a specific individual. Using Change Shape counts as creating a disguise for the Impersonate use of Deception. The monster's transformation automatically defeats Perception DCs to determine whether the creature is a member of the ancestry or creature type into which it transformed, and it gains a +4 status bonus to its Deception DC to prevent others from seeing through its disguise. Change Shape abilities specify what shapes the monster can adopt. The monster doesn't gain any special abilities of the new shape, only its physical form. For example, in each shape, it replaces its normal Speeds and Strikes, and might potentially change its senses or size. Any changes are listed in its stat block.</p></p>"},{"n":"Sneak Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>The anadi lurker deals an additional 1d6 precision damage to Off-Guard creatures.</p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/anadi-seeker":{"lang":["Anadi","Common"],"gear":["Sling","Sling Bullets (20)"],"flavor":"<p>Anadi seekers are knowledge seekers who often brave the outside world.</p>\n<hr>\n<p>Anadis have three distinct forms-human, spider, and a beautiful but unnerving hybrid shape that is their true form. Despite their unsettling arachnid features, anadis are peaceful and form tight-knit communities.</p>","abilities":[{"n":"Spin Silk","a":null,"c":"interaction","t":["concentrate","exploration","manipulate"],"f":"","d":"<p>By spending several minutes, an anadi can produce silk to craft items made of cloth. An anadi can produce enough silk in a day to craft a single garment.</p>"},{"n":"Anadi Venom","a":null,"c":"offensive","t":["poison"],"f":"","d":"<p><strong>Saving Throw</strong> DC 15 Fortitude</p>\n<p><strong>Maximum Duration</strong> 4 rounds</p>\n<p><strong>Stage 1</strong> 1d6 poison damage and Off-Guard (1 round)</p>\n<p><strong>Stage 2</strong> 1d6 poison damage, off-guard, and Clumsy 1 (1 round)</p>"},{"n":"Change Shape","a":"1","c":"offensive","t":["arcane","concentrate","polymorph"],"f":"","d":"<p>The anadi changes into their hybrid, spider, or human form. The above statistics assume the anadi is in hybrid form. While in human form, the anadi seeker loses their climb Speed and can't use their fangs attack. When in spider form, they can't use weapons.</p>\n<hr>\n<p><p>The monster changes its shape indefinitely. It can use this action again to return to its natural shape or adopt a new shape. Unless otherwise noted, a monster cannot use Change Shape to appear as a specific individual. Using Change Shape counts as creating a disguise for the Impersonate use of Deception. The monster's transformation automatically defeats Perception DCs to determine whether the creature is a member of the ancestry or creature type into which it transformed, and it gains a +4 status bonus to its Deception DC to prevent others from seeing through its disguise. Change Shape abilities specify what shapes the monster can adopt. The monster doesn't gain any special abilities of the new shape, only its physical form. For example, in each shape, it replaces its normal Speeds and Strikes, and might potentially change its senses or size. Any changes are listed in its stat block.</p></p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/ancient-rivener":{"lang":["Ikeshti","can speak and understand only simple words"],"flavor":"<p>Ikeshtis who eschew their society are exiled and quickly devolve into violent creatures known as riveners.</p>\n<hr>\n<p>Ikeshtis are reptilian humanoids native to Akiton's wastelands. Smaller than Golarion's iruxi, ikeshtis organize around distinct societal roles.</p>","abilities":[{"n":"Violent Instincts","a":null,"c":"interaction","t":[],"f":"","d":"<p>An ancient rivener attacks the nearest creature when Confused instead of any other effect, and ignores magical commands compelling them to do anything other than attack.</p>"},{"n":"Ferocity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> The monster is reduced to 0 HP.</p>\n<hr>\n<p><strong>Effect</strong> The monster avoids being knocked out and remains at 1 HP, but its Wounded value increases by 1. When it is Wounded 3, it can no longer use this ability</p></p>"},{"n":"Slaughter Tackle","a":"2","c":"offensive","t":[],"f":"","d":"<p>The ancient rivener Leaps at a target within 30 feet, and then makes one jaws Strike and one claw Strike in any order.</p>"},{"n":"Squirt Blood","a":"1","c":"offensive","t":[],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p>\n<hr>\n<p><strong>Effect</strong> The ancient rivener squirts blood from one of their eyes at a target within 30 feet. The target must attempt a DC 18 Fortitude save or become Sickened 1 (Sickened 2 on a critical failure).</p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/apocalypse-ant-swarm":{"abilities":[{"n":"Cling","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature leaves the swarm's space</p>\n<hr>\n<p><strong>Effect</strong> The swarm loses 2d8 untyped HP as ants cling to the creature and continue biting, dealing 7d8 persistent piercing damage. High winds or immersion in water reduces the DC of the flat check to end this persistent damage to 5. Any area damage dealt to the creature destroys these clinging ants.</p>"},{"n":"Inexorable","a":null,"c":"defensive","t":[],"f":"","d":"<p>The apocalypse ant swarm recovers from the slowed and stunned conditions at the end of its turn. It's immune to penalties to its Speeds and ignores difficult terrain and greater difficult terrain.</p>"},{"n":"Swarming Bites","a":"1","c":"offensive","t":[],"f":"","d":"<p>Each enemy in the swarm's space takes 7d8 piercing damage (DC 39 basic Fortitude). A creature that fails its save against Swarming Bites becomes Clumsy 1 for 1 round (1 minute on a critical failure). If the creature attempts a concentrate or manipulate action while affected, it must succeed at a DC 5 Flat or the action is lost; roll the check after spending the action, but before any effects are applied.</p>\n<p>Effect: Swarming Bites</p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/aspect-of-hunger":{"notes":{"hp":"fire healing"},"flavor":"<p>Among the most dangerous cave worms are the fiery crimson worms. In addition to being even larger than azure or purple worms, the crimson worm has a penchant for burrowing through volcanic regions that, over the generations, have infused it with a supernatural link to the Elemental Plane of Fire. The molten heart of an active volcano is an attractive lair for a crimson worm, as are the sprawling fields of bubbling magma found in the deepest reaches of the Darklands. Legends from ancient peoples, precursor dwarven societies, and colonists of the Elemental Planes populated moats of lava with crimson worms likely have some basis in truth, although the methods such ancients used to keep these \"moat worms\" contained and prevented them from chewing their way through fortress foundations must have been significant.</p>\n<p>Crimson worms sometimes frequent areas on the surface where volcanism creates hot springs or other geothermal features, but even then they prefer to spend most of their time burrowing through the ground in their never-ending search for sustenance. Surface lands claimed by crimson worms are notable for the mound-shaped burrows these creatures leave behind as they dig.</p>\n<hr>\n<p>Cave worms are gigantic scavengers that bore through the depths of the world, eating whatever material they find. Named for their distinctive colorations, these worms are ravenous and display overwhelming destructive capabilities. Cave worms of different colors and abilities lurk in the more remote corners of the world-tales speak of white worms that dwell within immense glaciers or icebergs and gray worms that burrow through the boneyards of long-forgotten ruins, to name a few.</p>","abilities":[{"n":"Tremorsense (Imprecise) 100 feet","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>Tremorsense allows a monster to feel the vibrations through a solid surface caused by movement. It is an imprecise sense with a limited range (listed in the ability). Tremorsense functions only if the monster is on the same surface as the subject, and only if the subject is moving along (or burrowing through) the surface.</p></p>"},{"n":"Inexorable","a":null,"c":"defensive","t":[],"f":"","d":"<p>The Aspect of Hunger recovers from the Paralyzed, Slowed, and Stunned conditions at the end of its turn. It's also immune to penalties to its Speeds and the Immobilized condition, and it ignores difficult terrain and greater difficult terrain.</p>"},{"n":"Key Weakness","a":null,"c":"defensive","t":[],"f":"","d":"<p>The Aspect of Hunger is foiled by the bounty of natural magic. It has a weakness to divine spells and primal spells.</p>"},{"n":"Shake It Off","a":"r","c":"defensive","t":[],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p>\n<p><strong>Trigger</strong> The Aspect of Hunger would be affected by a condition or adverse effect (such as Cursed Metamorphosis)</p>\n<hr>\n<p><strong>Effect</strong> The Aspect of Hunger negates the triggering condition or effect. Effects from artifacts, deities, or a similarly powerful source can't be avoided in this way.</p>"},{"n":"Aspect of Hunger Venom","a":null,"c":"offensive","t":["poison"],"f":"","d":"<p><strong>Saving Throw</strong> DC 41 Fortitude</p>\n<hr>\n<p><strong>Maximum Duration</strong> 6 rounds</p>\n<p><strong>Stage 1</strong> 1d6 poison damage and Drained 1 (1 round)</p>\n<p><strong>Stage 2</strong> 2d6 poison damage and drained 1 (1 round)</p>\n<p><strong>Stage 3</strong> 2d6 poison damage and Drained 2 (1 round).</p>"},{"n":"Breath Weapon","a":"2","c":"offensive","t":["mental","primal"],"f":"","d":"<p>The Aspect of Hunger breathes a blast of hunger in a 60-foot cone that deals 18d6 mental damage to all creatures in the area (DC 41 basic Reflex save).</p>\n<p>It can't use Breath Weapon again for 1d4 rounds.</p>"},{"n":"Essence of Hunger","a":null,"c":"offensive","t":[],"f":"","d":"<p>The Aspect of Hunger doesn't have the fire trait, immunity to fire, weakness to cold, or fire healing. It instead has immunity to mental effects, and its attacks deal mental damage instead of fire damage.</p>"},{"n":"Fast Swallow","a":"r","c":"offensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The Aspect of Hunger Grabs a creature</p>\n<hr>\n<p><strong>Effect</strong> The Aspect of Hunger uses Swallow Whole.</p>"},{"n":"Rock Tunneler","a":null,"c":"offensive","t":[],"f":"","d":"<p>The Aspect of Hunger can burrow through solid stone at a Speed of 20 feet. It can leave a tunnel if it desires, and it usually does.</p>"},{"n":"Swallow Whole","a":"1","c":"offensive","t":["attack"],"f":"","d":"<p>Huge, 3d10+10 bludgeoning damage plus 2d6 mental damage, Rupture 36</p>\n<hr>\n<p><p>The monster attempts to swallow a creature of the listed size or smaller that it has grabbed or restrained in its jaws or mouth. If a swallowed creature is of the maximum size listed, the monster can't use Swallow Whole again. If the creature is smaller than the maximum, the monster can usually swallow more creatures; the GM determines the maximum. The monster attempts an Athletics vs. Reflex DC check opposed by the grabbed creature's Reflex DC. If it succeeds, it swallows the creature. The monster's mouth or jaws no longer grab a creature it has swallowed, so the monster is free to use them to Strike or Grab once again. The monster can't attack creatures it has swallowed.</p>\n<p>A swallowed creature is Grabbed, is Slowed 1, and has to hold its breath or start suffocating. The swallowed creature takes the listed amount of damage when first swallowed and at the end of each of its turns while it's swallowed. If the victim Escapes this ability's grabbed condition, it exits through the monster's mouth. This frees any other creature grabbed in the monster's mouth or jaws. A swallowed creature can attack the monster that has swallowed it, but only with unarmed attacks or with weapons of light Bulk or less. The swallowing creature is Off-Guard against the attack. If the monster takes piercing or slashing damage equaling or exceeding the listed Rupture value from a single attack or spell, the swallowed creature cuts itself free. A creature that gets free by either Escaping or cutting itself free can immediately breathe and exits the swallowing monster's space.</p>\n<p>Effect: Engulf and Swallow Whole</p>\n<p>If the monster dies, a swallowed creature can be freed by creatures adjacent to the corpse if they spend a combined total of 3 actions cutting the monster open with a weapon or unarmed attack that deals piercing or slashing damage.</p></p>"},{"n":"Thrash","a":"2","c":"offensive","t":[],"f":"","d":"<p>The Aspect of Hunger makes a Strike once against each creature in its reach. It can Strike up to once with its jaws, up to once with its stinger, and any number of times with its body. Each attack counts toward the Aspect of Hunger's multiple attack penalty, but the multiple attack penalty doesn't increase until after it makes all the attacks.</p>"},{"n":"Improved Grab","a":"f","c":"offensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> The monster's last action was a successful Strike that lists Improved Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with as a free action. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Improved Grab as an action and choose one creature it's grabbing or restraining with an appendage that has Improved Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/aspect-of-immortality":{"lang":["Common","Necril"],"gear":["Scythe"],"notes":{"hp":"void healing","saves":"+1 status to all saves vs. magic"},"focus":1,"flavor":"<p>The Grim Reaper is the unflinching personification of death. Silent as the grave and as inevitable as time itself, this legendary being hunts down and finishes creatures that have evaded death for far too long. Sometimes the Grim Reaper comes without warning, while at others it comes to finish the work that other creatures could not. The Grim Reaper serves no god, fiend, or aeon. It is both despised and feared by psychopomps and celestials, but few-if any-dare to stand in its way. Like some eternal plague, it kills those who try to cure the multiverse of its presence. It stands alone and holds only its own council, and the pleading and reasoning of mortals and immortals alike fall on deaf ears once the Grim Reaper closes on its quarry. Its own reasoning is silent to mortal ears and inscrutable to the mortal mind, but no matter the reason, the result is unyielding and final.</p>\n<p>While some legends hold that the Grim Reaper appears before everyone as they die, the truth is quite a bit more disturbing. Such vigils in fact lie within the providence of the psychopomps, a race of immortals charged with the protection and guidance of mortal souls through the afterlife. The Grim Reaper has little interest in protecting souls or guiding them. It is instead compelled by sinister agendas arising within the nighted realm of Abaddon, where the Horsemen of the Apocalypse rule. Indeed there are many similarities in shape and form between the Grim Reaper and Charon, the Horseman of Death, but no recorded instance exists of these two powerful entities working together. Instead, the Grim Reaper serves as something of a manifestation of Abaddon itself, and in this regard is believed by some to be an incarnation of the mysterious First Horseman. When the Grim Reaper comes to a world, it does so not as an angel of mercy, but as a relentless harvester of life. Those who fall to the Grim Reaper were not destined to die as much as they were selected, hunted, and murdered.</p>\n<p>Perhaps the most frightening legends surrounding the Grim Reaper concern its nature as a singular entity, for some believe that more than one grim reaper exists in the Great Beyond. These whispers tell of a cabal of at least nine of these creatures that stalk reality, culling the living as inexplicable servants of true entropy. According to the teaching of some death cults, the final goal of the Grim Reaper is to end the entire cycle of life and death and serve as a silent lord of an empty universe.</p>","abilities":[{"n":"Death's Grace","a":null,"c":"interaction","t":[],"f":"","d":"<p>The Aspect of Immortality can choose whether or not it counts as undead for effects that affect undead differently. Even if it does not count as undead, the Aspect of Immortality still never counts as a living creature.</p>"},{"n":"Status Sight","a":null,"c":"interaction","t":[],"f":"","d":"<p>The Aspect of Immortality automatically knows the Hit Points, conditions, afflictions, and emotions of all creatures it can see.</p>"},{"n":"Constant Spells","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>A constant spell affects the monster without the monster needing to cast it, and its duration is unlimited. If a constant spell gets counteracted, the monster can reactivate it by spending the normal spellcasting actions the spell requires.</p></p>"},{"n":"+1 Status to All Saves vs. Magic","a":null,"c":"defensive","t":[],"f":"","d":""},{"n":"Aura of Misfortune","a":null,"c":"defensive","t":["aura","divine","misfortune"],"f":"","d":"<p>20 feet. Living creatures in the aura must roll twice on all d20 rolls and use the lower result.</p>\n<p>Effect: Aura of Misfortune</p>"},{"n":"Key Weakness","a":null,"c":"defensive","t":[],"f":"","d":"<p>Jatembe's history of vanquishing the King of Biting Ants survives in the halcyon legacy of the Magaambya. The Aspect of Immortality has a key weakness to both arcane spells and primal spells.</p>"},{"n":"Lurking Death","a":"r","c":"defensive","t":["teleportation"],"f":"","d":"<p><strong>Trigger</strong> A creature within 100 feet makes a ranged attack or uses an action that has the concentrate, manipulate, or move trait.</p>\n<hr>\n<p><strong>Effect</strong> The Aspect of Immortality teleports to a square adjacent to the triggering creature and makes a melee Strike against it. If the Strike hits, the Aspect of Immortality disrupts the triggering action.</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p>The Aspect of Immortality can choose whether or not it takes vitality damage.</p>\n<hr>\n<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Death Strike","a":null,"c":"offensive","t":["death"],"f":"","d":"<p>A creature critically hit by any of the Aspect of Immortality's attacks or that critically fails against any of its spells must succeed at a DC 47 Fortitude save or die.</p>"},{"n":"Energy Drain","a":null,"c":"offensive","t":[],"f":"","d":"<p>When the Aspect of Immortality hits and deals damage with its scythe, it regains 20 healing Hit Points, and the target must succeed at a DC 43 Fortitude save or become Doomed 1. If the target is already doomed, the doomed value increases by 1 (to a maximum of doomed 3).</p>"},{"n":"Final Death","a":null,"c":"offensive","t":[],"f":"","d":"<p>A creature killed by the Aspect of Immortality can't be brought back to life by any means short of divine intervention.</p>"},{"n":"Infuse Weapon","a":null,"c":"offensive","t":["divine"],"f":"","d":"<p>Any scythe gains the agile trait, can't be disarmed, and becomes a <em>+3 Major Striking Keen scythe</em> while the Aspect of Immortality wields it. If the Aspect of Immortality Strikes a creature with a weakness to any specific type of damage, the scythe's damage counts as that type of damage, in addition to slashing.</p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/aspect-of-insects":{"notes":{"ac":"all-around vision"},"flavor":"<p>Fearsome centipede-like creatures, mukradis are three-headed predators with a devastating array of breath weapons. A Darklands version of the mukradi is rumored to exist. It's said these variant mukradis have black scales, and all of their heads spew a black, acidic goo that animates before being reabsorbed by the mukradis.</p>","abilities":[{"n":"Tremorsense (Imprecise) 60 feet","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>Tremorsense allows a monster to feel the vibrations through a solid surface caused by movement. It is an imprecise sense with a limited range (listed in the ability). Tremorsense functions only if the monster is on the same surface as the subject, and only if the subject is moving along (or burrowing through) the surface.</p></p>"},{"n":"All-Around Vision","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>This monster can see in all directions simultaneously and therefore can't be flanked.</p></p>"},{"n":"Key Weakness","a":null,"c":"defensive","t":[],"f":"","d":"<p>The King of Biting Ants has long used his force of will to keep his insectile form under control. It has a weakness to arcane spells and occult spells.</p>"},{"n":"Partitioned Anatomy","a":"f","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The Aspect of Insects would be Confused, Paralyzed, Slowed, or Stunned.</p>\n<hr>\n<p><strong>Effect</strong> The Aspect of Insects confines the debilitating effect to a certain portion of its nervous system, ignoring the effect but causing a maw of its choice to go dormant for the effect's duration. That maw can't be used for a Strike or Breath Weapon during that time. This ability can't be used if all the Aspect of Insects' heads are dormant.</p>"},{"n":"Spitting Rage","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature scores a critical hit on the Aspect of Insects.</p>\n<hr>\n<p><strong>Effect</strong> The Aspect of Insects' Breath Weapon recharges. It can use its Breath Weapon immediately as part of this reaction. It can't use this reaction again until it recharges its Breath Weapon naturally.</p>"},{"n":"Breath Weapon","a":"2","c":"offensive","t":["primal"],"f":"","d":"<p>The Aspect of Insects breathes a blast of energy from one of its three heads; each creature in the area must attempt a basic Reflex save.</p>\n<p>The Aspect of Insects can't use Breath Weapon again for 1d4 rounds.</p>\n<ul>\n<li><strong>Acid Maw</strong> (acid) 10-Foot-Wide, 60-Foot Line of acid dealing 16d8 acid damage (DC 42 basic Reflex save).</li>\n<li><strong>Flame Maw</strong> (fire) 60-foot cone of fire dealing 16d8 fire damage (DC 42 basic Reflex save).</li>\n<li><strong>Shock Maw</strong> (electricity) 120-foot line of electricity dealing 16d8 electricity damage (DC 42 basic Reflex save).</li>\n</ul>"},{"n":"Pull Apart","a":"2","c":"offensive","t":[],"f":"","d":"<p>The Aspect of Insects makes two Strikes with different maws against the same target. If both hit, the target takes an extra 2d12+13 slashing damage, with a DC 42 basic Fortitude save. On a critical failure, the creature is torn to pieces and dies. The Aspect of Insects' multiple attack penalty increases only after all the attacks are made.</p>"},{"n":"Thrash","a":"2","c":"offensive","t":[],"f":"","d":"<p>The Aspect of Insects Strikes once against each creature in its reach. It can Strike up to once with each maw, once with its tail lash, and any number of times with its legs. Each attack takes a -2 circumstance penalty and counts toward the Aspect of Insects' multiple attack penalty, but the multiple attack penalty doesn't increase until after all the attacks are made.</p>"},{"n":"Trample","a":"3","c":"offensive","t":[],"f":"","d":"<p>Huge or smaller, leg, DC 42 basic Reflex save</p>\n<hr>\n<p><p>The monster Strides up to double its Speed and can move through the spaces of creatures of the listed size, Trampling each creature whose space it enters. The monster can attempt to Trample the same creature only once in a single use of Trample. The monster deals the damage of the listed Strike, but trampled creatures can attempt a basic Reflex save at the listed DC (no damage on a critical success, half damage on a success, double damage on a critical failure).</p></p>"},{"n":"Knockdown","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Knockdown in its damage entry</p><hr><p><strong>Effect</strong> The monster attempts to Trip the creature. This attempt neither applies nor counts toward the monster's multiple attack penalty.</p></p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/auto-turret":{"description":"<p>A mounted gun equipped with a magical targeting system and integrated ammo supply.</p>","disable":"<p>DC 35 Thievery (master) to disconnect the turret from its ammo supply system, or DC 35 Arcana (master) to neutralize the magical targeting system.</p>\n<p>Tan‑Takneh can also deactivate one or both auto‑turrets remotely with a special command word.</p>","routine":"<p>(3 actions) With each action, the auto‑turret makes a longrifle Strike against a creature within 60 feet of Tan‑Takneh's campsite (other than Tan-Takneh). If there are no such creatures, the auto‑turret instead uses its action to sprout mechanical legs, totter 20 feet in the direction of its last target, and then plant itself into the ground again. Programmed to spread its fire around, the auto‑turret doesn't attack any creature it's already attacked in the round.</p>\n<p>After making 15 Strikes, the auto‑turret depletes its ammunition and automatically deactivates.</p>","stealthNote":"<p>(expert); darkvision</p>","abilities":[{"n":"Bullet Spray","a":"r","c":"offensive","t":["attack"],"f":"","d":"<p><strong>Trigger</strong> A creature comes within 60 feet of Tan-Takneh's campsite</p>\n<hr>\n<p><strong>Effect</strong> The turret attacks the triggering creature with a longrifle Strike.</p>"}],"strikeNotes":{"Longrifle":"<p>No multiple attack penalty</p>"}},"strength-of-thousands-bestiary/book-4-secrets-of-the-temple-city/avatar-of-walkena":{"lang":["Common"],"lore":[["Walkena Lore",33]],"gear":["Spear"],"notes":{"per":"smoke vision"},"abilities":[{"n":"Greater Darkvision","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>A creature with greater darkvision can see perfectly well in areas of darkness and dim light, though such vision is in black and white only. A creature with greater darkvision can see through even forms of magical darkness.</p></p>"},{"n":"Constant Spells","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>A constant spell affects the monster without the monster needing to cast it, and its duration is unlimited. If a constant spell gets counteracted, the monster can reactivate it by spending the normal spellcasting actions the spell requires.</p></p>"},{"n":"Attack of Opportunity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Avatar's Resistance","a":"r","c":"defensive","t":["divine","fortune"],"f":"once per minute","d":"<p><strong>Trigger</strong> The avatar fails or critically fails a saving throw</p>\n<p><strong>Frequency</strong> once per minute</p><hr><p><strong>Effect</strong> Walkena's will attempts to undo his avatar's fate. The avatar rerolls the saving throw and takes the better result.</p>"},{"n":"Frightful Presence","a":null,"c":"defensive","t":["aura","emotion","fear","mental"],"f":"","d":"<p>60 feet. DC 38 Will</p>\n<hr>\n<p><p>A creature that first enters the area must attempt a Will save.</p>\n<p>Regardless of the result of the saving throw, the creature is temporarily immune to this monster's Frightful Presence for 1 minute.</p>\n<hr>\n<p><strong>Critical Success</strong> The creature is unaffected by the presence.</p>\n<p><strong>Success</strong> The creature is Frightened 1.</p>\n<p><strong>Failure</strong> The creature is Frightened 2.</p>\n<p><strong>Critical Failure</strong> The creature is Frightened 4.</p></p>"},{"n":"Smoke Vision","a":null,"c":"defensive","t":[],"f":"","d":"<p>The avatar ignores the Concealed condition from smoke.</p>"},{"n":"Sun's Touch","a":null,"c":"defensive","t":["aura","divine","fire","light"],"f":"","d":"<p>10 feet. The avatar of Walkena radiates with an intense light. Creatures that enter or begin their turn in the emanation are Dazzled and take 3d8 fire damage (DC 35 basic Fortitude save). Creatures remain dazzled until they leave the emanation.</p>"},{"n":"Constrict","a":"1","c":"offensive","t":[],"f":"","d":"<p>2d4+11 bludgeoning plus 2d8 fire, DC 38 basic Fortitude</p>\n<hr>\n<p><p>The monster deals the listed amount of damage to any number of creatures Grabbed or Restrained by it. Each of those creatures can attempt a basic Fortitude save with the listed DC.</p></p>"},{"n":"Pull Down the Sun","a":"3","c":"offensive","t":["divine","fire","light"],"f":"","d":"<p>The avatar of Walkena plucks a small drop of sunlight from the sky and rains down sunfire on the battlefield. The avatar selects a 20-foot burst within 90 feet. Sunfire rains down in the area, dealing 12d8 fire damage (DC 38 basic Reflex save) to all creatures that enter or begin their turn in the area. The power of the sun restores the avatar; it instead recovers an equal number of Hit Points while in the area. The sunfire continues to rain until the end of the avatar's next turn. The avatar can't use Pull Down the Sun again for 1d4 rounds.</p>"},{"n":"Radiate Glory","a":"2","c":"offensive","t":["divine","light"],"f":"","d":"<p>The avatar intensifies its light. All creatures within 30 feet must attempt a DC 38 Fortitude save. The avatar can't use Radiate Glory again for 1d4 rounds. During this time, the avatar's Sun Touch no longer dazzles creatures.</p>\n<hr>\n<p><strong>Critical Success</strong> The creature is unaffected and becomes temporarily immune for 24 hours.</p>\n<p><strong>Success</strong> The creature is Dazzled for 1 round.</p>\n<p><strong>Failure</strong> The creature is Blinded for 1 round.</p>\n<p><strong>Critical Failure</strong> The creature is blinded for 1 minute.</p>"},{"n":"Improved Grab","a":"f","c":"offensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> The monster's last action was a successful Strike that lists Improved Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with as a free action. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Improved Grab as an action and choose one creature it's grabbing or restraining with an appendage that has Improved Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-4-secrets-of-the-temple-city/baaupa-mdoudu":{"notes":{"per":"skeleton sense 60 feet"},"abilities":[{"n":"Tremorsense (imprecise) 30 feet","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>Tremorsense allows a monster to feel the vibrations through a solid surface caused by movement. It is an imprecise sense with a limited range (listed in the ability). Tremorsense functions only if the monster is on the same surface as the subject, and only if the subject is moving along (or burrowing through) the surface.</p></p>"},{"n":"Reactive","a":null,"c":"defensive","t":[],"f":"","d":"<p>A ba'aupa mdoudu gains an additional reaction at the start of its turn but can use this reaction only to Slime Squirt.</p>"},{"n":"Skeleton Sense 60 feet","a":null,"c":"defensive","t":[],"f":"","d":"<p>Aba'aupa mdoudu can sense the presence of bones and skeletons within 60 feet; this is a precise sense when detecting dead bones but an imprecise one when detecting living bones.</p>"},{"n":"Slime Squirt","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature inflicts slashing or piercing damage on the ba'aupa mdoudu with a melee Strike</p><hr><p><strong>Effect</strong> The attacking creature takes 2d10 acid damage.</p>"},{"n":"Caustic Acid","a":null,"c":"offensive","t":[],"f":"","d":"<p>Whenever a creature takes acid damage from any of a ba'aupa mdoudu's abilities or Strikes, it must succeed at a DC 30 Fortitude save or become Drained 1 (Drained 2 on a critical failure). On each subsequent failure, the drained condition value increases by 1 (or by 2 on a critical failure), to a maximum of drained 4.</p>"},{"n":"Caustic Rain","a":"2","c":"offensive","t":["primal"],"f":"","d":"<p>The ba'aupa mdoudu spews copious amounts of acid into the air, creating a cascading rain to fall in a 10-foot emanation around itself. All creatures in the area take 14d6 acid damage (DC 33 basic Reflex save) plus Caustic Acid. The ba'aupa mdoudu can't use Caustic Rain again for 1d4 rounds.</p>"},{"n":"Stone Tunneler","a":null,"c":"offensive","t":[],"f":"","d":"<p>A ba'aupa mdoudu can leave a tunnel when it burrows through earth or stone, and it usually does.</p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/bharlen-sajor":{"lang":["Common","Necril"],"gear":["Heavy Crossbow","Trident","Breastplate","Bolts (20)","Storm Bolts (2)"],"notes":{"hp":"void healing, rejuvenation"},"abilities":[{"n":"No Escape","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature within Bharlen's reach moves away from her</p>\n<hr>\n<p><strong>Effect</strong> Bharlen Strides up to her Speed, following the foe and keeping it in reach throughout this movement.</p>"},{"n":"Rejuvenation","a":null,"c":"defensive","t":["divine"],"f":"","d":"<p>When Bharlen is destroyed, her armor rebuilds its body over the course of 1d10 days-or more quickly if the armor is worn by a living host. If the body is destroyed before then, the process restarts.</p>\n<p>Bharlen can only be permanently destroyed by obliterating her armor (such as with Disintegrate), transporting it to the Forge of Creation, or throwing it into the heart of a volcano.</p>"},{"n":"Sacrilegious Aura","a":null,"c":"defensive","t":["aura","divine","evil"],"f":"","d":"<p>30 feet. When a creature in the aura uses a vitality spell or ability, Bharlen automatically attempts to counteract it, with a +18 counteract modifier.</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Brute Strength","a":null,"c":"offensive","t":[],"f":"","d":"<p>Bharlen deals an extra 1d8 damage with tridents, and a trident gains the shove trait while she is using it in melee (both the extra damage die and the shove trait have been included in Bharlen's trident Strikes above).</p>"},{"n":"Devastating Blast","a":"2","c":"offensive","t":["arcane","electricity"],"f":"","d":"<p>Bharlen unleashes crackling lightning in a 30-foot cone. Creatures in the area take 6d12 electricity damage (DC 30 basic Reflex save).</p>\n<p>Bharlen can use this ability once every 1d4 rounds.</p>"},{"n":"Graveknight's Curse","a":null,"c":"offensive","t":[],"f":"","d":"<p>This curse affects anyone who wears a graveknight's armor for at least 1 hour.</p>\n<p><strong>Saving Throw</strong> DC 40 Will save</p>\n<p><strong>Onset</strong> 1 hour</p>\n<p><strong>Stage 1</strong> Doomed 1 and cannot remove the armor (1 day)</p>\n<p><strong>Stage 2</strong> Doomed 2, all speeds reduced by 10, and cannot remove the armor (1 day)</p>\n<p><strong>Stage 3</strong> dies and transforms into the armor's graveknight.</p>"},{"n":"Ruinous Weapons","a":null,"c":"offensive","t":[],"f":"","d":"<p>Any weapons Bharlen wields gain the effects of the <em>+1 Striking</em> and <em>Shock</em> runes.</p>"},{"n":"Sodden Strike","a":"2","c":"offensive","t":["divine","water"],"f":"","d":"<p>Bharlen calls to the endless storm to lend murderous power to her blows. She makes a Strike; on a hit, seawater appears in the target's lungs and the target is Sickened 1 (Sickened 3 on a critical hit).</p>"},{"n":"Weapon Master","a":null,"c":"offensive","t":[],"f":"","d":"<p>Bharlen has access to the critical specialization effects of any weapon she wields.</p>"},{"n":"Push","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Push in its damage entry</p><hr><p><strong>Effect</strong> The monster attempts to Shove the creature. This attempt neither applies nor counts toward the monster's multiple attack penalty. If Push lists a distance, change the distance the creature is pushed on a success to that distance.</p></p>"}]},"strength-of-thousands-bestiary/book-4-secrets-of-the-temple-city/biloko-reaver":{"lang":["Common","Fey"],"gear":["Spear","Maul","Leather Armor"],"abilities":[{"n":"Attack of Opportunity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Inspired Feast","a":null,"c":"offensive","t":["emotion","mental"],"f":"","d":"<p>If a biloko feasts on a human corpse for 1 minute or more, they gain a +1 status bonus to attack rolls and a +2 status bonus to damage rolls for 1 hour.</p>"},{"n":"Terrifying Roar","a":"1","c":"offensive","t":["auditory","emotion","fear","mental"],"f":"","d":"<p>The biloko reaver unleashes a frightful roar. Any non-biloko within 30 feet must succeed at a DC 29 Will save or become Frightened 1 (Frightened 3 on a critical failure). Those who critically succeed are temporarily immune for 1 minute.</p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/binji":{"lang":["Common","Sakvroth"],"gear":["Rock (5)","Satchel for Holding Rocks"],"flavor":"<p>Gremlins arose long ago in the First World, living embodiments of nature's ability to wear away, erode, and decompose. On the Material Plane, their encounters with mortal civilizations twisted them into creatures devoted to chaos, sabotage, and traps, each variety specializing in a particular brand of mayhem.</p>\n<hr>\n<p>Even more than most gremlins, grimples resent the trappings of civilization: inn common rooms with their rowdy singalongs, livery yards with their whinnying horses, church steeples with their clanging bells. Grimples live to spoil these conventions, dropping tavern signs on patrons, urinating in rain barrels, and opening stable doors. When all else fails, they literally vomit their disdain on passersby.</p>\n<p>Grimples resemble humanoid, mange-ridden opossums, with boar-like tusks that aid them in rooting through garbage heaps for food. They are agile climbers who glide from eave to eave on the loose flaps of skin between their limbs. Savvy gremlin-hunters know to look for the skin flakes and fur grimples shed from their parasite-infested hides.</p>","abilities":[{"n":"So Many Lice","a":null,"c":"defensive","t":[],"f":"","d":"<p>Whenever a living creature touches or is touched by a Binji (including via a successful unarmed melee Strike), it must succeed at a DC 15 Reflex save or become infested by gremlin lice.</p>\n<p>While infested, the targeted creature is distracted by the itching sensation and is Stupefied 1, though it can use an Interact action to scratch at the itching lice to suppress the stupefied condition from the lice for 1d4 rounds.</p>\n<p>The infestation ends after 24 hours or until the creature is submerged in water or exposed to a severe cold environment, whichever comes first.</p>"},{"n":"Putrid Vomit","a":"1","c":"offensive","t":[],"f":"","d":"<p>The binji spews a 30-foot line of vomit. Each creature in the line must succeed at a DC 16 Fortitude save or become Sickened 1 (Sickened 2 on a critical failure).</p>\n<p>The binji can't use Putrid Vomit again for 1d4 rounds.</p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/bog-mummy-amalgamation":{"lang":["Common","Necril"],"notes":{"hp":"void healing"},"abilities":[{"n":"Tremorsense (Imprecise) 30 feet","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>Tremorsense allows a monster to feel the vibrations through a solid surface caused by movement. It is an imprecise sense with a limited range (listed in the ability). Tremorsense functions only if the monster is on the same surface as the subject, and only if the subject is moving along (or burrowing through) the surface.</p></p>"},{"n":"Breath of Silt","a":null,"c":"defensive","t":["aura","divine","mental"],"f":"","d":"<p>30 feet. A creature that begins its turn within the area feels as if its lungs are filling with silt and must succeed at a DC 25 Fortitude save or be unable to speak or breathe. The creature can still hold its breath and can attempt a new saving throw at the end of its turn.</p>\n<p>A creature that succeeds is temporarily immune to breath of silt for 24 hours.</p>"},{"n":"Rise Up","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature walks on top of the bog mummy amalgamation lying buried in the silt below</p>\n<p><strong>Requirements</strong> Initiative has not yet been rolled</p>\n<hr>\n<p><strong>Effect</strong> The bog mummy amalgamation notices the creature automatically and Burrows before rolling initiative.</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Bog Rot","a":null,"c":"offensive","t":["curse","disease","divine","void"],"f":"","d":"<p>This affliction can't be reduced below stage 1, nor can the damage from it be healed, until it's successfully treated with Cleanse Affliction or a similar effect; the affliction can then be removed as normal for a disease.</p>\n<p>A creature killed by bog rot melts into a noxious sludge and can't be resurrected except by a 7th-rank Resurrect ritual or similar magic</p>\n<p><strong>Saving Throw</strong> DC 21 Fortitude</p>\n<p><strong>Stage 1</strong> carrier with no ill effect (1 minute)</p>\n<p><strong>Stage 2</strong> 3d6 void damage and Clumsy 1 (1 day).</p>"},{"n":"Fist Flurry","a":"2","c":"offensive","t":[],"f":"","d":"<p>The amalgamation makes two fist Strikes against two different targets within its reach. Its multiple attack penalty doesn't increase until after both attacks.</p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/boggard-hunter":{"lang":["Boggard"],"gear":["Greatclub","Javelin (5)","Studded Leather Armor"],"notes":{"speed":"swamp stride"},"abilities":[{"n":"Sneak Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>A boggard hunter deals an additional 2d6 precision damage precision damage to Off-Guard creatures.</p>"},{"n":"Swamp Stride","a":null,"c":"offensive","t":[],"f":"","d":"<p>A boggard hunter ignores difficult terrain caused by swamp terrain features.</p>"},{"n":"Terrifying Croak","a":"1","c":"offensive","t":["auditory","emotion","fear","mental"],"f":"","d":"<p>The boggard unleashes a terrifying croak. Any non-boggard within 30 feet becomes Frightened 1 unless they succeed at a DC 25 Will save; those who critically succeed are temporarily immune for 1 minute.</p>"},{"n":"Tongue Grab","a":null,"c":"offensive","t":[],"f":"","d":"<p>If a boggard hunter hits a creature with her tongue, that creature becomes Grabbed. Unlike with a normal grab, the creature isn't Immobilized, but it can't move beyond the reach of the boggard hunter's tongue.</p>\n<p>A creature can sever the tongue by hitting AC 22 and dealing at least 7 slashing damage. Though this doesn't deal any damage to the boggard, it prevents it from using their tongue Strike until they regrows their tongue, which takes a week.</p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/boulder-deadfall-trap":{"description":"<p>A weight-sensitive plate buried underneath sand pulls a boulder over a cliff ledge, causing it to fall on targets within the entrance.</p>","disable":"<p>DC 27 Crafting (expert) or DC 25 Thievery (expert) to find and disconnect the plate from the tipping mechanism</p>","reset":"<p>Resetting the boulders in the trap is a labor-intensive project that takes 2 hours.</p>","stealthNote":"<p>(trained); DC 0 to spot the balanced boulders</p>","abilities":[{"n":"Deadfall","a":"r","c":"offensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature enters the area without taking care to avoid the hidden trigger plate</p>\n<hr>\n<p><strong>Effect</strong> Creatures within 10 feet of the cave entrance take 4d10+18 bludgeoning damage (DC 25 basic Reflex save).</p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/bramble-champion-construct":{"gear":["Wooden Maul"],"abilities":[{"n":"Critical Vulnerability","a":null,"c":"defensive","t":[],"f":"","d":"<p>A critical hit damages the construct's controls, making it Clumsy 1 until repaired. Additional critical hits increase this value, up to Clumsy 4.</p>"},{"n":"Ridden Construct","a":null,"c":"defensive","t":[],"f":"","d":"<p>The construct is piloted by a Leaf Leshy who can be targeted separately but has greater cover. The leshy can't take actions of their own while inside the construct, other than to leave it, which takes 1 minute.</p>"},{"n":"Hammer Block","a":"r","c":"offensive","t":[],"f":"","d":"<p><strong>Trigger</strong> An ally within the bramble champion's reach is targeted by an attack, and the bramble champion can see the attacker</p>\n<hr>\n<p><strong>Effect</strong> The bramble champion interposes with its hammer, giving the ally a +2 circumstance bonus to AC against the triggering attack.</p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/cataclysm-beetle":{"lang":["Common"],"abilities":[{"n":"Bombardier's Spray","a":"2","c":"offensive","t":["acid","primal"],"f":"","d":"<p>The cataclysm beetle sprays a 60-foot cone of acid from its abdomen that deals 12d10 acid damage (DC 40 basic Reflex). It can't use Bombardier's Spray or Burning Pool for 1d4 rounds.</p>"},{"n":"Burning Pool","a":"2","c":"offensive","t":["acid","primal"],"f":"","d":"<p>The cataclysm beetle spills acid directly from its abdomen, creating a wave of acid that deals 10d12 acid damage to all creatures in a 30-foot emanation (DC 40 basic Fortitude). Creatures that fail this save are pushed back 10 feet from the cataclysm beetle (30 feet on a critical failure). It can't use Bombardier's Spray or Burning Pool for 1d4 rounds.</p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/centipede-carcasses-trap":{"description":"<p>Three giant centipede carcasses have wire springs that pull out and fling their sharpened legs around the room.</p>","disable":"<p>DC 23 Nature (trained) to bend the centipede carapace so the wire can't pull out any more legs, or DC 21 Thievery (expert) to cut the springy wires. After all three carcasses are disabled (regardless of the check used), the trap is deactivated. The trap automatically deactivates after 10 rounds.</p>","routine":"<p>(1 action) Each creature within 30 feet of a centipede carcass that hasn't been disabled takes 6d4 piercing damage (DC 22 basic Reflex save).</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Volley of Legs","a":"r","c":"offensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A carcass is touched or jostled</p>\n<hr>\n<p><strong>Effect</strong> Each creature within 30 feet of any centipede carcass takes 4d4 piercing damage (DC 22 basic Reflex save), and the area becomes difficult terrain due to the many sharpened legs on the ground. Each creature that Strides more than 10 feet through the area must succeed at a DC 20 Acrobatics check or take 1d4 piercing damage.</p>\n<p>The trap then rolls initiative.</p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/chromatic-ooze":{"flavor":"<p>Chromatic oozes result from the worst kind of alchemical mishaps: attempts to combine as many types of elemental damage as possible into a single alchemical substance. Although the source of these alchemical concatenations are as varied as the alchemists who attempt to distill them, one of the most common methods for creating them involves combining the essences of multiple types of chromatic dragons together using eldritch alchemical processes. When this type of experimentation goes dangerously wrong-as it often does-the result is a combination of terrible elemental power with the mindless destructive power of an ooze. A chromatic ooze is a rippling, seething substance that shifts through several different colors, but chemical reactions within the ooze can lock its energy and its color into a specific phase for a short time. Whether a chromatic ooze's destructive urges derive from the frustrated ingenuity of an alchemist creator or from the hunger of the chromatic dragons that so often constitute these oozes' forms, the best way to deal with a chromatic ooze is to stay out of its way.</p>","abilities":[{"n":"Caustic Aura","a":null,"c":"defensive","t":["alchemical","aura","olfactory"],"f":"","d":"<p>90 feet. The chromatic ooze emanates noxious chemicals into the environment. A creature that enters the aura or starts its turn within it is Sickened 1 unless it succeeds at a DC 37 Fortitude save. Creatures with the scent ability or a particularly heightened sense of smell are Sickened 2, or sickened 1 on a successful Fortitude save. Creatures in the aura can't recover from the sickened condition.</p>"},{"n":"Chromatic Shift","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The chromatic ooze takes acid, cold, electricity, fire, or poison damage</p>\n<hr>\n<p><strong>Effect</strong> The chromatic ooze changes its color based on the triggering damage (to dark green, pale blue, dark blue, red, or light green, respectively) and gains resistance 20 to the triggering damage. If it already had resistance to another damage type from this ability, it loses the resistance to that damage type and gains weakness 20 to it. If it already had weakness to another damage type from this ability, it loses that weakness. After 1 minute, the chromatic ooze returns to its usual rippling, multicolored hue and loses the resistance and weakness from this ability.</p>"},{"n":"Motion Sense","a":null,"c":"defensive","t":[],"f":"","d":"<p>A chromatic ooze can sense nearby motion through vibration and air movement.</p>"},{"n":"Chromatic Slam","a":null,"c":"offensive","t":[],"f":"","d":"<p>The ooze's pseudopod Strikes deal an additional 2d10 damage of the same type it resists from its Chromatic Shift ability, if any.</p>"},{"n":"Greater Constrict","a":"1","c":"offensive","t":[],"f":"","d":"<p>3d10+13 bludgeoning, DC 40 basic Fortitude</p>\n<p><p>The monster deals the listed amount of damage to any number of creatures Grabbed or Restrained by it. Each of those creatures can attempt a basic Fortitude save with the listed DC. A creature that fails this save falls Unconscious, and a creature that succeeds is then temporarily immune to falling unconscious from Greater Constrict for 1 minute.</p></p>"},{"n":"Pseudopod Eruption","a":"2","c":"offensive","t":[],"f":"","d":"<p>The chromatic ooze concentrates its mass into several pseudopods, increasing its reach to 30 feet until the end of its turn. It then Strikes at up to four different creatures within its reach. This counts as two attacks for the ooze's multiple attack penalty, but the penalty doesn't increase until after it makes all the attacks.</p>"},{"n":"Improved Grab","a":"f","c":"offensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> The monster's last action was a successful Strike that lists Improved Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with as a free action. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Improved Grab as an action and choose one creature it's grabbing or restraining with an appendage that has Improved Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/clockwork-clock-tower":{"flavor":"<p>Clockworks are machines built by engineers and augmented with magic. A clock tower reconfigured as an animated clockwork can rotate slices of time.</p>","abilities":[{"n":"Wind-Up","a":null,"c":"interaction","t":[],"f":"","d":"<p>1 week DC 40 Thievery</p>\n<p>For a clockwork to act, it must be wound with a unique key by another creature. This takes 1 minute. Once wound, it remains operational for the listed amount of time, usually 24 hours, after which time it becomes unaware of its surroundings and can't act until it's wound again. Some clockworks' abilities require them to spend some of their remaining operational time. They can't spend more than they have and shut down immediately once they have 0 time remaining. If it's unclear when a clockwork was last wound, most clockwork keepers wind all their clockworks at a set time, typically 8 a.m.</p>\n<p>A clockwork that lists standby in its wind-up entry can enter standby mode as a 3-action activity. Its operational time doesn't decrease in standby, but it can sense its surroundings (with a -2 penalty to Perception). It can't act, with one exception: when it perceives a creature, it can exit standby as a reaction (rolling initiative if appropriate).</p>\n<p>A creature can attempt to Disable a Device to wind a clockwork down (with a DC listed in the wind-up entry). For each success, the clockwork loses 1 hour of operational time. This can be done even if the clockwork is in standby mode.</p>"},{"n":"Doleful Tolling","a":"f","c":"defensive","t":["arcane","auditory","incapacitation"],"f":"","d":"<p><strong>Trigger</strong> The clockwork clock tower rolls initiative</p>\n<hr>\n<p><strong>Effect</strong> The clock tower chimes, and all non-clockwork creatures within 300 feet who can hear it must succeed at a DC 42 Will save or be Slowed 1 for 1 round (Slowed 2 on a critical failure).</p>"},{"n":"Durable Exterior","a":null,"c":"defensive","t":[],"f":"","d":"<p>When a clockwork clock tower is reduced to fewer than 200 HP or is damaged by a critical hit, its exterior shatters to reveal internal mechanisms, reducing its AC to 44 until it recovers enough HP to reach 200 HP or more.</p>"},{"n":"Overclock","a":"1","c":"offensive","t":[],"f":"","d":"<p>The clockwork clock tower loses 1 day from its winding time and becomes Quickened for 3 rounds. It can use this extra action to Step, Stride, or Strike. This quickened condition ends immediately if the clock tower is damaged by orichalcum.</p>"},{"n":"Stutter Time","a":null,"c":"offensive","t":["arcane","incapacitation"],"f":"","d":"<p>A creature struck by a clockwork clock tower's fist must make a DC 40 Will save as time flows unevenly around it.</p>\n<hr>\n<p><strong>Critical Success</strong> The creature is Quickened for 1 round and can use this extra action to Step, Stride, or Strike.</p>\n<p><strong>Success</strong> The creature is unaffected.</p>\n<p><strong>Failure</strong> The creature is Stunned 3.</p>\n<p><strong>Critical Failure</strong> The creature is knocked out of time, which ceases to flow around the creature for 1 round. It is invulnerable to all damage, it can't be targeted or affected by anything, and no rounds elapse for any timed durations, conditions, afflictions, and other effects it has. The target can't act and remains fixed in place, defying gravity if applicable. After time begins to flow again for it, the creature is stunned 3.</p>"},{"n":"Trample","a":"3","c":"offensive","t":[],"f":"","d":"<p>Huge or smaller, foot, DC 42 basic Reflex save</p>\n<p><p>The monster Strides up to double its Speed and can move through the spaces of creatures of the listed size, Trampling each creature whose space it enters. The monster can attempt to Trample the same creature only once in a single use of Trample. The monster deals the damage of the listed Strike, but trampled creatures can attempt a basic Reflex save at the listed DC (no damage on a critical success, half damage on a success, double damage on a critical failure).</p></p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/contemplative":{"lang":["Akitonian","telepathy 30"],"flavor":"<p>Even the average contemplative demonstrates an intellect that far surpasses those of most other beings.</p>\n<hr>\n<p>The ancestors of the Contemplatives of Ashok were humanoids of vast intellect who unlocked occult powers. They deliberately evolved their mental faculties at the expense of their physical forms, and their atrophied bodies dangle beneath giant brains.</p>","abilities":[{"n":"Telepathy 30 feet","a":null,"c":"interaction","t":["aura","magical"],"f":"","d":"<p><p>A monster with telepathy can communicate mentally with any creatures within the listed radius, as long as they share a language. This doesn't give any special access to their thoughts, and communicates no more information than normal speech would.</p></p>"},{"n":"Thoughtsense (Imprecise) 30 feet","a":null,"c":"interaction","t":["mental","occult"],"f":"","d":"<p>The contemplative senses all non-mindless creatures at the listed range.</p>"},{"n":"Atrophied","a":null,"c":"defensive","t":[],"f":"","d":"<p>A contemplative's limbs are withered and incapable of significant physical exertion. A contemplative can't properly wield a two-handed weapon or object without dedicating its telekinetic powers to supporting the weapon, and even then, it takes a -2 penalty to Strikes with such a weapon. It also can't use its spells or fly as long as it wields a two-handed weapon or object.</p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/contemplative-meditant":{"lang":["Akitonian","telepathy 60 feet; tongues"],"lore":[["Dimension of Time Lore",31]],"flavor":"<p>Contemplative meditants focus their meditations and research on the vexing topic of time itself.</p>\n<hr>\n<p>The ancestors of the Contemplatives of Ashok were humanoids of vast intellect who unlocked occult powers. They deliberately evolved their mental faculties at the expense of their physical forms, and their atrophied bodies dangle beneath giant brains.</p>","abilities":[{"n":"Telepathy 60 feet","a":null,"c":"interaction","t":["aura","magical"],"f":"","d":"<p><p>A monster with telepathy can communicate mentally with any creatures within the listed radius, as long as they share a language. This doesn't give any special access to their thoughts, and communicates no more information than normal speech would.</p></p>"},{"n":"Temporal Sense","a":null,"c":"interaction","t":[],"f":"","d":"<p>A contemplative meditant can always roll Dimension of Time Lore for initiative. When it does, it gains a +2 circumstance bonus to the roll as it acts on flashes of insight harvested from potential futures.</p>"},{"n":"Thoughtsense 60 feet","a":null,"c":"interaction","t":["mental","occult"],"f":"","d":"<p>The contemplative senses all non-mindless creatures at the listed range.</p>"},{"n":"Constant Spells","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>A constant spell affects the monster without the monster needing to cast it, and its duration is unlimited. If a constant spell gets counteracted, the monster can reactivate it by spending the normal spellcasting actions the spell requires.</p></p>"},{"n":"Atrophied","a":null,"c":"defensive","t":[],"f":"","d":"<p>A contemplative's limbs are withered and incapable of significant physical exertion. A contemplative can't properly wield a two-handed weapon or object without dedicating its telekinetic powers to supporting the weapon, and even then, it takes a -2 penalty to Strikes with such a weapon. It also can't use its spells or fly as long as it wields a two-handed weapon or object.</p>"},{"n":"Temporal Suppression","a":"1","c":"offensive","t":["mental","occult"],"f":"once per round","d":"<p><strong>Frequency</strong> once per round</p>\n<hr>\n<p><strong>Effect</strong> The contemplative attempts to hinder a target creature's personal flow of time. The target must be within 60 feet, and once targeted must attempt a DC 36 Will save, becoming Slowed 1 on a failure or Slowed 2 on a critical failure.</p>\n<p>Each time an affected creature ends its turn, its slowed value decreases by 1. A creature that critically succeeds on their save against Temporal Suppression is temporarily immune to it for 24 hours.</p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/contemplative-mentor":{"lang":["Akitonian","telepathy 100 feet; tongues"],"lore":[["Dimension of Time Lore",35]],"flavor":"<p>As they near the next phase of their journey through existence, contemplative mentors split their time between unlocking the highest secrets of time and space, and guiding their students and less-talented peers.</p>\n<hr>\n<p>The ancestors of the Contemplatives of Ashok were humanoids of vast intellect who unlocked occult powers. They deliberately evolved their mental faculties at the expense of their physical forms, and their atrophied bodies dangle beneath giant brains.</p>","abilities":[{"n":"Telepathy 100 feet","a":null,"c":"interaction","t":["aura","magical"],"f":"","d":"<p><p>A monster with telepathy can communicate mentally with any creatures within the listed radius, as long as they share a language. This doesn't give any special access to their thoughts, and communicates no more information than normal speech would.</p></p>"},{"n":"Temporal Sense","a":null,"c":"interaction","t":[],"f":"","d":"<p>A contemplative meditant can always roll Dimension of Time Lore for initiative. When it does, it gains a +2 circumstance bonus to the roll as it acts on flashes of insight harvested from potential futures.</p>"},{"n":"Thoughtsense 100 feet","a":null,"c":"interaction","t":["mental","occult"],"f":"","d":"<p>The contemplative senses all non-mindless creatures at the listed range.</p>"},{"n":"Constant Spells","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>A constant spell affects the monster without the monster needing to cast it, and its duration is unlimited. If a constant spell gets counteracted, the monster can reactivate it by spending the normal spellcasting actions the spell requires.</p></p>"},{"n":"Atrophied","a":null,"c":"defensive","t":[],"f":"","d":"<p>A contemplative's limbs are withered and incapable of significant physical exertion. A contemplative can't properly wield a two-handed weapon or object without dedicating its telekinetic powers to supporting the weapon, and even then, it takes a -2 penalty to Strikes with such a weapon. It also can't use its spells or fly as long as it wields a two-handed weapon or object.</p>"},{"n":"Project Calm","a":"3","c":"offensive","t":["emotion","mental","occult"],"f":"","d":"<p>The contemplative mentor projects a field of perfect calm in a 60-foot emanation. All creatures within the area of effect must succeed at a DC 40 Will save or be unable to take hostile actions for 1 round.</p>\n<p>After using this ability, the contemplative is Drained 1, or increases its drained value by 1 if it was already drained. A contemplative mentor can't use this ability if its drained value is 3 or more.</p>"},{"n":"Temporal Suppression","a":"1","c":"offensive","t":["mental","occult"],"f":"once per round","d":"<p><strong>Frequency</strong> once per round</p>\n<hr>\n<p><strong>Effect</strong> The contemplative attempts to hinder a target creature's personal flow of time. The target must be within 60 feet, and once targeted must attempt a DC 40 Will save, becoming Slowed 1 on a failure or Slowed 2 on a critical failure.</p>\n<p>Each time an affected creature ends its turn, its slowed value decreases by 1. A creature that critically succeeds on their save against Temporal Suppression is temporarily immune to it for 24 hours.</p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/cookie":{"lang":["Akitonian","Shobhad"],"gear":["Greatsword","+2 Striking Handwraps of Mighty Blows","Chain Mail"],"flavor":"<p>In rough Akitonian cities like Seldo, shobhad bruisers and fist-fighters act as protection for businesses and enforcers for crime bosses. Shobhad enforcers are more rare and far more dangerous. In the wilds of Akiton, shobhad enforcers protect wealthy caravans using combat techniques honed and proven over multiple generations to devastate any creature that might mistake the caravan as an attractive target for a raid. \"Enforcer\" is a loose translation of a word in the Shobhad language that is only granted to a warrior who has proven themselves in combat against one of the deadly threats of the Akitonian desert, such as gluttonworms or ikeshti riveners. Every enforcer is a battle-tested veteran with the scars to prove their prowess.</p>\n<hr>\n<p>These four-armed humanoids often live as nomads on Akiton. Self-sufficient and able to construct the equipment they need to survive from natural materials, shobhads traditionally avoid large cities and the smaller people of the planet, except to engage in trade. Some shobhads eschew these traditions, finding life in urban centers to be more appealing. Rifts between these shobhads and those who continue to lead nomadic lives in the Akitonian wilderness sometimes lead to clashes when members of the two societies meet.</p>\n<p>Shobhads are highly sought after for their martial expertise, unparalleled knowledge of Akiton's wilds, and unbreakable codes of honor. These warriors may operate independently, in their traditional clans, or in modern mercenary companies that blend ancestral traditions with the needs of modern military freelancers.</p>","abilities":[{"n":"Four-Armed","a":null,"c":"interaction","t":[],"f":"","d":"<p>Shobhad enforcers have four powerful arms. They can Interact with and manipulate objects or perform combat maneuvers that require a free hand such as grabbing or tripping, even while wielding a two-handed weapon or carrying an object in two hands.</p>"},{"n":"Attack of Opportunity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Ferocity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> The monster is reduced to 0 HP.</p>\n<hr>\n<p><strong>Effect</strong> The monster avoids being knocked out and remains at 1 HP, but its Wounded value increases by 1. When it is Wounded 3, it can no longer use this ability</p></p>"},{"n":"Brutal Blows","a":"2","c":"offensive","t":[],"f":"","d":"<p><strong>Requirements</strong> The shobhad enforcer has at least two free hands</p>\n<hr>\n<p><strong>Effect</strong> The shobhad enforcer makes a fist Strike against an adjacent creature. If the Strike hits, the enforcer automatically Grapples its target and makes a second fist Strike with the following success conditions.</p>\n<p>The second Strike applies the enforcer's multiple attack penalty normally.</p>\n<hr>\n<p><strong>Critical Success</strong> The target is Stunned 1, and Stupefied 2 for 1 round.</p>\n<p><strong>Success</strong> The target is Stupefied 1 for 1 round.</p>"},{"n":"Thasteron Blast","a":"2","c":"offensive","t":["magical"],"f":"","d":"<p><strong>Requirements</strong> Cookie is within 10 feet of his stove</p>\n<hr>\n<p><strong>Effect</strong> Cookie adjusts dials, levers, and vents on his stove, causing a gout of searing blue fire to lance out at a single creature in area <strong>C2</strong>. The targeted creature takes 17d6 fire damage (DC 37 basic Reflex save).</p>\n<p>Cookie can't use Thasteron Blast for 1d4 rounds as the stove must rebuild its heat and pressure.</p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/crawling-slurry":{"flavor":"<p>Acid damage can scar stone and reduce flesh to pitted chunks, but some organic compounds are resistant to acid and respond by combining into a mass of roiling, living slurry. These scarred clumps hunger to consume anything they can sense. They move with quick, darting contractions that surprise those used to facing slow-moving oozes.</p>","abilities":[{"n":"Motion Sense","a":null,"c":"defensive","t":[],"f":"","d":"<p>A crawling slurry can sense nearby motion through vibration and air movement.</p>"},{"n":"Splatter","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The crawling slurry takes bludgeoning damage from a creature it can sense within 10 feet</p>\n<hr>\n<p><strong>Effect</strong> The crawling slurry ejects a splash of acid onto the creature, dealing acid damage equal to the bludgeoning damage dealt to the crawling slurry (DC 37 basic Reflex).</p>"},{"n":"Constrict","a":"1","c":"offensive","t":[],"f":"","d":"<p>2d10+3 bludgeoning damage plus 2d8 acid, DC 37 basic Fortitude</p>\n<hr>\n<p><p>The monster deals the listed amount of damage to any number of creatures Grabbed or Restrained by it. Each of those creatures can attempt a basic Fortitude save with the listed DC.</p></p>"},{"n":"Crawling Slurry Acid","a":null,"c":"offensive","t":[],"f":"","d":"<p>A crawling slurry's acid damages metals and organic materials but not stone.</p>"},{"n":"Engulf","a":"2","c":"offensive","t":[],"f":"","d":"<p>DC 37 Reflex save, 5d10 acid damage, Escape, Rupture 20. A crawling slurry regains 30 healing Hit Points if a living creature it is engulfing dies.</p>\n<p><p>The monster Strides up to double its Speed and can move through the spaces of any creatures in its path. Any creature of the monster's size or smaller whose space the monster moves through can attempt a Reflex save with the listed DC to avoid being engulfed. A creature unable to act automatically critically fails this save. If a creature succeeds at its save, it can choose to be either pushed aside (out of the monster's path) or pushed in front of the monster to the end of the monster's movement. The monster can attempt to Engulf the same creature only once in a single use of Engulf. The monster can contain as many creatures as can fit in its space.</p>\n<p>A creature that fails its save is pulled into the monster's body. It is Grabbed, is Slowed 1, and has to hold its breath or start suffocating. The creature takes the listed amount of damage when first engulfed and at the end of each of its turns while it's engulfed. An engulfed creature can get free by Escaping against the listed escape DC. An engulfed creature can attack the monster engulfing it, but only with unarmed attacks or with weapons of light Bulk or less. The engulfing creature is Off-Guard against the attack. If the monster takes piercing or slashing damage equaling or exceeding the listed Rupture value from a single attack or spell, the engulfed creature cuts itself free.\n<p>Effect: Engulf and Swallow Whole</p>\n<p>A creature that gets free by either method can immediately breathe and exits the swallowing monster's space.</p>\n<p>If the monster dies, all creatures it has engulfed are automatically released as the monster's form loses cohesion.</p></p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/crimson-acolyte":{"lang":["Akitonian","Aklo","Common"],"gear":["Dueling Pistol","+2 Striking Handwraps of Mighty Blows","Thasteron Rounds (Dueling Pistol) (10)"],"notes":{"saves":"evasion"},"abilities":[{"n":"Ageless","a":null,"c":"defensive","t":[],"f":"","d":"<p>The crimson acolyte doesn't age and doesn't need food or drink to survive.</p>"},{"n":"Evasion","a":null,"c":"defensive","t":[],"f":"","d":"<p>When the acolyte rolls a success on a Reflex save, they get a critical success instead.</p>"},{"n":"Guarded Movement","a":null,"c":"defensive","t":[],"f":"","d":"<p>The acolyte gains a +4 circumstance bonus to AC against reactions triggered by their movement.</p>"},{"n":"Flurry of Blows","a":"1","c":"offensive","t":["flourish"],"f":"once per turn","d":"<p><strong>Frequency</strong> once per turn</p>\n<hr>\n<p><strong>Effect</strong> The acolyte makes two unarmed Strikes, or one unarmed Strike and a dueling pistol Strike. If both hit the same creature, combine their damages for the purposes of resistances and weaknesses.</p>\n<p>The acolyte's multiple attack penalty applies normally to these Strikes.</p>"},{"n":"Sneak Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>The acolyte deals an extra 2d6 precision damage to Off-Guard creatures.</p>"},{"n":"Thousand Ants Stance","a":"1","c":"offensive","t":["stance"],"f":"","d":"<p>The acolyte takes the stance of thousand ants, a style mimicking the distracting strikes of a swarm of tiny, vicious creatures. The acolyte can make thousand wounds unarmed attacks.</p>\n<p>These deal 1d12 piercing damage; are in the brawling group; and have the backstabber, forceful, and unarmed traits. While in this stance, if the acolyte successfully Trips a target, the target is Off-Guard until the start of the target's next turn.</p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/cyclops-bully":{"lang":["Common","Cyclops","Jotun"],"gear":["Greatclub","Hide Armor"],"abilities":[{"n":"Brutal Recovery","a":"f","c":"defensive","t":["fortune","occult"],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p>\n<p><strong>Trigger</strong> The cyclops bully fails (but does not critically fail) an attack roll or an Intimidation check</p>\n<hr>\n<p><strong>Effect</strong> The cyclops bully forces its will on an array of possible futures. It gets a success on the roll instead of a failure.</p>"},{"n":"Ferocity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> The monster is reduced to 0 HP.</p>\n<hr>\n<p><strong>Effect</strong> The monster avoids being knocked out and remains at 1 HP, but its Wounded value increases by 1. When it is Wounded 3, it can no longer use this ability</p></p>"},{"n":"Terrorizing Swing","a":"2","c":"offensive","t":[],"f":"","d":"<p>The cyclops bully attempts to Demoralize a foe within its melee reach, then makes a melee Strike against that foe.</p>\n<p>If the creature is Frightened and takes damage, it takes an additional 2d10 damage and is knocked Prone.</p>\n<p>This counts as two attacks toward the cyclops's multiple attack penalty.</p>"}]},"strength-of-thousands-bestiary/book-4-secrets-of-the-temple-city/dajermube":{"lang":["Common","telepathy 100 feet"],"lore":[["Dwelling Lore",25]],"notes":{"hp":"void healing, rejuvenation"},"flavor":"<p>This undead guardian stands amid a whirling swarm of shackled spirits that rage against their fate. Bound by a profane necromantic ritual, a nemhaith and its servitors maintain watch over an object or place so important they embraced undeath to guard it. This ritual binds connected beings-friends, family, fellow worshippers, or even sacrificed innocents-to form a single nemhaith.</p>\n<p>Most nemhaiths were, in life, priests or protectors who sought immortality to protect the temple they served or guard an important landmark. Others follow an endless and even impossible quest beyond the bounds of life and death. A nemhaith is not always evil at first, but the inherent evil and violence of a nemhaith's existence inevitably darkens even the brightest light.</p>","abilities":[{"n":"Telepathy 100 feet","a":null,"c":"interaction","t":["aura","magical"],"f":"","d":"<p><p>A monster with telepathy can communicate mentally with any creatures within the listed radius, as long as they share a language. This doesn't give any special access to their thoughts, and communicates no more information than normal speech would.</p></p>"},{"n":"Bound Spirits","a":null,"c":"defensive","t":["aura","divine","void"],"f":"","d":"<p>10 feet. 4d6 void damage, DC 36 basic Fortitude</p>"},{"n":"Rejuvenation","a":null,"c":"defensive","t":["divine"],"f":"","d":"<p>Destroying the ritual object or place used in the nemhaith's creation destroys the nemhaith, freeing its bound spirits to move on to the afterlife.</p>"},{"n":"Site Bound","a":null,"c":"defensive","t":[],"f":"","d":"<p>The nemhaith is bound to a place or large stationary object and can't venture more than 500 feet from this focus.</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Drain Life","a":null,"c":"offensive","t":["divine"],"f":"","d":"<p>When the nemhaith damages a living creature with its spirit tendril Strike, the creature must succeed at a DC 36 Fortitude save or become Drained 2.</p>\n<p>Further damage dealt by the nemhaith increases the condition value by 1 on a failed save, to a maximum of drained 4.</p>"},{"n":"Rage of Spirits","a":"2","c":"offensive","t":[],"f":"","d":"<p>The nemhaith's bound spirits rage and smash everything in a 30-foot emanation. Creatures in this area take 4d6 sonic damage and 4d6 void damage (DC 36 basic Fortitude save).</p>"},{"n":"Throw Spirits","a":"1","c":"offensive","t":[],"f":"","d":"<p>The nemhaith directs its bound spirits as a group to move up to 1 mile away (they have a fly Speed of 60 feet). The nemhaith can see and hear through the thrown spirits, but it loses its aura and can't use its spirit dart ranged Strike or Rage of Spirits. The nemhaith regains these abilities when the spirits return to the nemhaith's space.</p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/damibwa":{"flavor":"<p>Damibwas are domesticated hounds capable of detecting prey or predators via echolocation thanks to their exceptionally large ears and keen hearing. Adept swimmers, damibwas have sleek bodies, short limbs, webbed feet, and long muscular tails that enable them to maneuver underwater with grace and speed.</p>\n<p>Trained as specialized hunting hounds, damibwas primarily catch fish, although they're also adept at diving for lobsters, crabs, and clams. While hunting, damibwas wait near the water's edge, typically on a boat or along the shore, listening for choice prey. When they detect prey in range, they dive down below the water, catch the animal in their jaws, and drag it back up to the surface. When large or dangerous aquatic predators approach, damibwas retreat to land and howl a warning, making them desirable guard dogs in coastal or riverside communities. Damibwas rarely attack terrestrial creatures unless they're threatened and unable to make an escape.</p>\n<p>Damibwas are popular pets along rivers, lakes, and swamps throughout Golarion, particularly in the River Kingdoms, Wanshou, and the canals of Nantambu in the Mwangi Expanse. Some Erutaki in Avistan's far north hunt seals alongside a particular hardy breed covered in thick fur and a layer of blubber. They are only universally called damibwas in the Mwangi Expanse, and are often called \"diving dogs\" in other regions.</p>","abilities":[{"n":"Deep Breath","a":null,"c":"defensive","t":[],"f":"","d":"<p>A damibwa can hold its breath for 5 minutes.</p>"},{"n":"Echolocation 60 feet","a":null,"c":"defensive","t":[],"f":"","d":"<p>A damibwa's hearing is a precise sense at the listed range.</p>"},{"n":"Fetch","a":"1","c":"offensive","t":["attack","move"],"f":"","d":"<p><strong>Requirements</strong> The damibwa has a Small or smaller creature grabbed in water</p>\n<hr>\n<p><strong>Effect</strong> The damibwa attempts an Athletics vs. Fortitude DC check against the creature's Fortitude DC.</p>\n<hr>\n<p><strong>Critical Success</strong> The damibwa moves up to its swim Speed, dragging the Grabbed creature along with it.</p>\n<p><strong>Success</strong> The damibwa moves up to half its swim Speed, dragging the grabbed creature along with it.</p>\n<p><strong>Failure</strong> The damibwa doesn't move and the creature isn't dragged.</p>\n<p><strong>Critical Failure</strong> The damibwa no longer has the creature grabbed.</p>"},{"n":"Predatory Dive","a":"2","c":"offensive","t":["move"],"f":"","d":"<p><strong>Requirements</strong> The damibwa is in or adjacent to water</p>\n<hr>\n<p><strong>Effect</strong> The damibwa moves up to double its swim Speed, descending at least 10 feet, and then makes a jaws Strike. If it was Undetected at the start of predatory dive, it remains undetected until after the attack.</p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/deathly-dream":{"description":"<p>Sinister runes adorn the doorway, opening a portal to a realm of nightmares if anyone other than Dwandek opens the door.</p>","disable":"<p>DC 40 Thievery (master) to seal the rift using materials strongly grounded to the Material Plane, or Dispel Magic (7th‑level, counteract DC 33) to counteract the portal.</p>","reset":"<p>The deathly dream trap resets automatically as long as it hasn't been disabled or destroyed. Each time it resets, the tiny pocket plane of nightmare it sends its victim into resets as well, so no two victims will ever share the same deathly dream.</p>","stealthNote":"<p>(master)</p>","abilities":[{"n":"Drawn to Nightmare","a":"r","c":"offensive","t":["arcane","teleportation"],"f":"","d":"<p><strong>Trigger</strong> A creature other than Dwandek opens the door</p>\n<hr>\n<p><strong>Effect</strong> The triggering creature is drawn into a pocket plane of pure nightmare (DC 38 Will save to resist). Each round at the start of their turn, the creature takes 4d8 mental damage as they are assaulted by otherworldly visions, and must succeed at a new Will save against the original DC to be ejected from the pocket plane and deposited in the center of area <strong>A5</strong>.</p>"}]},"strength-of-thousands-bestiary/book-4-secrets-of-the-temple-city/dimari-diji":{"lang":["Aklo","Arboreal","Common","Draconic","Empyrean","Fey","Requian","Sphinx","speak with animals, speak with plants, telepathy 300 feet"],"lore":[["Mwangi Expanse Lore",50]],"notes":{"hp":"regeneration 30 (deactivated by fire)"},"abilities":[{"n":"Tremorsense (imprecise) 120 feet","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>Tremorsense allows a monster to feel the vibrations through a solid surface caused by movement. It is an imprecise sense with a limited range (listed in the ability). Tremorsense functions only if the monster is on the same surface as the subject, and only if the subject is moving along (or burrowing through) the surface.</p></p>"},{"n":"Telepathy 300 feet","a":null,"c":"interaction","t":["aura","magical"],"f":"","d":"<p><p>A monster with telepathy can communicate mentally with any creatures within the listed radius, as long as they share a language. This doesn't give any special access to their thoughts, and communicates no more information than normal speech would.</p></p>"},{"n":"Constant Spells","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>A constant spell affects the monster without the monster needing to cast it, and its duration is unlimited. If a constant spell gets counteracted, the monster can reactivate it by spending the normal spellcasting actions the spell requires.</p></p>"},{"n":"Regeneration 30 (Deactivated by Fire)","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>This monster regains the listed number of Hit Points each round at the beginning of its turn. Its Dying condition never increases beyond Dying 3 as long as its regeneration is active. However, if it takes damage of a type listed in the regeneration entry, its regeneration deactivates until the end of its next turn. Deactivate the regeneration before applying any damage of a listed type, since that damage might kill the monster by bringing it to Dying 4.</p></p>"},{"n":"Aura of Growth","a":null,"c":"defensive","t":["aura","plant","primal"],"f":"","d":"<p>120 feet. Plants near Dimari-Diji grow larger and more vibrant. Plants in the emanation gain the success effects of the Plant Growth ritual. Any plant spells cast in the area are empowered and use the effects of the spell 1 rank higher than it was cast, to a maximum of 9th rank (Dimari-Diji's spells are unaffected). Finally, other plant creatures gain fast healing 20 while in the area.</p>\n<p>Effect: Aura of Growth</p>"},{"n":"Axe Vulnerability","a":null,"c":"defensive","t":[],"f":"","d":"<p>An arboreal nature-speaker takes 20 additional damage from axes.</p>"},{"n":"Enriching Aura","a":null,"c":"defensive","t":["aura"],"f":"","d":"<p>60 feet. Dimari-Diji's natural power enhances primal spellcasting around him. All creatures within the emanation can alter a primal spell as if they had just used Reach Spell or Widen Spell when they Cast the Spell.</p>"},{"n":"Fungus Sight","a":null,"c":"defensive","t":["primal"],"f":"","d":"<p>Dimari-Diji produces small clumps of fungus that he can use to see beyond his normal sight. He can use a single action, which has the concentrate trait, to project his senses into an intact fungus clump on the Material Plane or to end this projection. Dimari-Diji loses all sensory information from his own body while projecting his senses into fungus.</p>"},{"n":"Forest Growth","a":null,"c":"offensive","t":[],"f":"once per month","d":"<p>Once per month, Dimari-Diji can spend 1 hour to sprout a new forest. He causes the forest to sprout in a 50-foot burst within 300 feet. The forest instantly springs to life, and is composed of fungi, plants, and trees most appropriate to the area he selected. The forest grows to the height, density, and liveliness of a forest that has grown for 10 years. The forest doesn't feature any animals or other creatures, but animals within 1 mile are aware of the new forest and might make the forest their new habitat as appropriate.</p>"},{"n":"Memories of Ages","a":null,"c":"offensive","t":[],"f":"","d":"<p>Dimari-Diji's mental blasts cloud the minds of his foes, making it difficult for them to focus on combat. A creature that takes damage from Dimari-Diji's mental blast is Dazzled for 1 round. If the attack was a critical hit, the creature is dazzled for 1 minute instead.</p>"},{"n":"Memory Maelstrom","a":"3","c":"offensive","t":["concentrate","incapacitation","mental","nonlethal","primal"],"f":"","d":"<p>Dimari - Diji tries to overwhelm foes with a surge of information he has absorbed over his long life. This surge deals 12d6 mental damage to each enemy within 60 feet, who must attempt a DC 32 Will save.</p>\n<p><strong>Critical Success</strong> The creature maintains its composure, takes no damage, and is temporarily immune to Memory Maelstrom for 1 minute.</p>\n<p><strong>Success</strong> The creature is Stunned 1 and takes half damage.</p>\n<p><strong>Failure</strong> The creature takes full damage and is Stunned 3.</p>\n<p><strong>Critical Failure</strong> The creature takes double damage, is Confused for 2d4 rounds, and is stunned 3.</p>"},{"n":"Nature's Concentration","a":"f","c":"offensive","t":[],"f":"","d":"<p><strong>Trigger</strong> Dimari-Diji's turn begins</p><hr><p><strong>Effect</strong> Dimari-Diji calls upon the natural world around him to support his magic. He Sustains a Spell.</p>"},{"n":"Improved Knockdown","a":"f","c":"offensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> The monster's last action was a successful Strike that lists Improved Knockdown in its damage entry</p><hr><p><strong>Effect</strong> The monster attempts to Trip the creature as a free action. This attempt neither applies nor counts toward the monster's multiple attack penalty.</p></p>"}]},"strength-of-thousands-bestiary/book-4-secrets-of-the-temple-city/drenchdead":{"lang":["Common","(can't speak any language)"],"abilities":[{"n":"Wavesense (precise) 60 feet","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>This sense allows a monster to feel vibrations caused by movement through a liquid. It's an imprecise sense with a limited range (listed in the ability). Wavesense functions only if monster and the subject are in the same body of liquid, and only if the subject is moving through the liquid.</p></p>"},{"n":"Aquatic Camouflage","a":null,"c":"offensive","t":[],"f":"","d":"<p>When fully submerged in water, the drenchdead can Hide from other creatures even if it doesn't have cover against them and isn't Concealed from them.</p>"},{"n":"Drag Down","a":"2","c":"offensive","t":[],"f":"","d":"<p><strong>Requirements</strong> The drenchdead is swimming in water at least 10 feet deep</p>\n<hr>\n<p><strong>Effect</strong> The drenchdead attempts an Athletics check to Grapple an adjacent creature (on nearby land or in the water). On a success against a creature on land, in addition to the normal effects of Grapple, the drenchdead pulls the creature into the water into a space adjacent to itself. If the creature is already in the water, on a success, in addition the normal effects of Grapple, the drenchdead drags the creature 10 feet deeper, moving 10 feet with the creature. Moving a creature into water or deeper into water using Drag Down is forced movement for the target creature, but not for the drenchdead.</p>"},{"n":"Drowning Touch","a":"2","c":"offensive","t":["incapacitation","occult","water"],"f":"","d":"<p>The drenchdead touches a creature and causes water from its own body to flow into the creature's lungs. If the creature can't breathe water, it must attempt a DC 32 Fortitude save.</p>\n<p><strong>Success</strong> The creature is unaffected and is temporarily immune to Drowning Touch for 24 hours.</p>\n<p><strong>Failure</strong> The creature becomes Sickened 3.</p>\n<p><strong>Critical Failure</strong> The creature chokes on the water and runs out of air. It falls Unconscious and starts drowning. If the creature is above water, it recovers from drowning as soon as it succeeds at a saving throw against suffocation.</p>"},{"n":"Surface Skimmer","a":null,"c":"offensive","t":[],"f":"","d":"<p>A drenchdead submerged in water has cover from attacks made by creatures out of the water.</p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/dwandek":{"lang":["Common","Necril","Sakvroth"],"gear":["Diadem of Intellect","Wand of Inexhaustible Cynicism (Level 7)"],"notes":{"hp":"void healing, rejuvenation"},"flavor":"<p>A wizard whose insatiable desire for arcane power eclipsed their mortal life, the lich is a truly devious and versatile spellcaster.</p>\n<hr>\n<p>To gain more time to complete their goals, some desperate spellcasters pursue immortality by embracing undeath. After long years of research and the creation of a special container called a <em>soul cage</em>, a spellcaster takes the final step by imbibing a deadly concoction or casting dreadful incantations that transform them into a lich. While most undertake this drastic plan to continue their work or fulfill some long-term plan, others become liches because they fear death or to fulfill some malevolent purpose, such as long-sworn revenge. Regardless, the result is permanent and carries with it the potential to alter history-both that of those who transform themselves and of the countless mortals that will inevitably suffer as a result of a lich's new power.</p>\n<p>After its metamorphosis, a lich often finds some quiet place to dwell, typically protected by a variety of guardians and traps, for two primary purposes. First, a lich requires solitude in order to plan its elaborate schemes, and second, few mortals (if any) deign to interact with these legendarily corrupt necromancers. One reason begets the other, as the self-imposed isolation of a lich often drives the lich insane, further solidifying its separation from civilization. The longer a lich lives, the more meticulous a planner it becomes, secreting itself within a labyrinth of deadly puzzles, misdirection, and monsters. A lich's servants and guardians are absolutely loyal, either due to their nature (such as constructs or other undead) or as a result of compulsion using powerful magic. Many liches go mad, in time, and the nature of a lich's lair is a good indicator of the undead's current mental state.</p>\n<p>For all the protections it arrays around itself, a lich will go to greater lengths to guard its <em>soul cage</em>, as it knows that the destruction of this magical container spells doom for the lich. A lich is notoriously difficult to bargain with, though the threat of damaging its <em>soul cage</em> is a sure way to gain the upper hand in such a negotiation.</p>","abilities":[{"n":"Counterspell","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature casts a spell Dwandek has prepared.</p>\n<hr>\n<p><strong>Effect</strong> Dwandek expends a prepared spell to counter the triggering creature's casting of that same spell. Dwandek loses his spell slot as if he had cast the triggering spell. Dwandek then attempts to counteract the triggering spell.</p>"},{"n":"Rejuvenation","a":null,"c":"defensive","t":["arcane"],"f":"","d":"<p>When a lich is destroyed, its soul immediately transfers to its <em>Soul Cage</em>. A lich can be permanently destroyed only if its <em>soul cage</em> is found and destroyed.</p>"},{"n":"Resist Arcane Magic","a":"r","c":"defensive","t":[],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p>\n<p><strong>Trigger</strong> Dwandek attempts a save against an arcane spell but hasn't rolled yet</p>\n<hr>\n<p><strong>Effect</strong> Dwandek automatically succeeds at his save against the triggering spell.</p>"},{"n":"Resistance 5 to Damage from Arcane Spells","a":null,"c":"defensive","t":[],"f":"","d":""},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Void Shroud","a":null,"c":"defensive","t":["aura","death"],"f":"","d":"<p>30 feet. The lich is surrounded by an aura of death, drawing forth souls to be consumed by the lich's constant hunger.</p>\n<p>Living creatures in the emanation take a -2 status penalty to saves against fear and death effects. In addition, any creature that starts its turn in the area gains the Doomed 1 condition unless it succeeds at a DC 35 Will save against the lich's spell DC-4.</p>\n<p>Effect: Void Shroud</p>"},{"n":"Drain Soul Cage","a":"f","c":"offensive","t":[],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p>\n<hr>\n<p><strong>Effect</strong> Dwandek taps into his <em>Soul Cage's</em> power to cast any arcane spell up to 9th rank, even if the spell being cast is not one of the lich's prepared spells.</p>\n<p>The lich's <em>soul cage</em> doesn't need to be present for the lich to use this ability.</p>"},{"n":"Paralyzing Touch","a":null,"c":"offensive","t":["arcane","curse","incapacitation"],"f":"","d":"<p>A creature damaged by the lich's hand Strike must succeed at a DC 38 Fortitude save.</p>\n<p>The creature becomes Paralyzed for 1 round on a failure. On a critical failure, the creature is paralyzed permanently, falls Prone, and seems dead. A DC 25 Medicine check reveals the victim is alive.</p>"},{"n":"Unflinching Spellcasting","a":null,"c":"offensive","t":[],"f":"","d":"<p>If a reaction would disrupt Dwandek's spellcasting action, Dwandek attempts a DC 12 Flat. On a success, the action isn't disrupted.</p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/electrified-water-ward":{"description":"<p>Passing over an invisible rune on the floor between the north and south doors triggers a dancing burst of electricity.</p>","disable":"<p>DC 26 Thievery (expert), DC 28 Arcana (expert), or DC 28 Occultism (expert) to harmlessly bleed away the electrical energy from the rune. Once the trap has been activated, the electrical energy is stronger, so three successful checks (of any combination of the relevant skills) are necessary to deactivate it, but these checks can be attempted from anywhere in the room.</p>","reset":"<p>The pulses stop as soon as no creatures are in the hallway, and then reset after 1 hour.</p>","routine":"<p>(1 action) The trap deals 4d10 electricity damage (DC 26 basic Reflex save) to all creatures in the room. A creature that fails the save is Slowed 1 (Slowed 2 on a critical failure). A creature that isn't touching the water treats the result of its saving throw as one degree of success better.</p>","stealthNote":"<p>(expert)</p>","abilities":[{"n":"Electrocution","a":"r","c":"offensive","t":["arcane","electricity"],"f":"","d":"<p><strong>Trigger</strong> A creature passes over the invisible underwater rune between the north and south doors</p>\n<hr>\n<p><strong>Effect</strong> The trap deals 4d10 electricity damage (DC 26 basic Reflex save) to creatures touching the water, and then rolls initiative.</p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/entropy-choir":{"description":"<p>A choir of ghostly shadows fill the benches in this room, chanting a haunting and unearthly melody.</p>","disable":"<p>DC 40 Religion (master) to exorcise the spirits and break the power binding them into a single entity, or DC 35 Performance (expert) to counter the choir and nullify the destructive elements of its song</p>","reset":"<p>The entropy choir resets automatically after 24 hours, even if it has been disabled or destroyed. It fades away forever once Dwandek and other members of the cult to which it sings its praises are destroyed.</p>","routine":"<p>(3 actions; auditory, divine, evocation, sonic) The choir continues to sing its grim dirge every round until it is disabled or destroyed. If there are any non‑slowed living creatures in area <strong>A3</strong> when its turn starts, it first uses Call to Nothingness as a single action.</p>\n<p>It uses its remaining actions (or all three actions if there are slowed living creatures in the room already) to focus soul‑shattering choruses onto individual targets.</p>\n<p>The choir can target any living creature in area <strong>A3</strong> with an action, but never more than once per round per creature. It prefers to attack slowed creatures over all others, but it targets non‑slowed creatures if they're the only viable targets. A targeted creature must attempt a DC 36 Fortitude save.</p>\n<hr>\n<p><strong>Critical Success</strong> The target is unaffected.</p>\n<p><strong>Success</strong> The target takes 5d6 sonic damage.</p>\n<p><strong>Failure</strong> The target takes 10d6 sonic damage.</p>\n<p><strong>Critical Failure</strong> The target takes 15d6 sonic damage and increases their Drained condition by 1, to a maximum of drained 4.</p>","stealthNote":"<p><strong>Performance</strong> +33 (master); creatures in the area automatically notice the eerily swaying shadows</p>","abilities":[{"n":"Call to Nothingness","a":"r","c":"offensive","t":["auditory","divine","mental","sonic"],"f":"","d":"<p><strong>Trigger</strong> A living creature moves more than 10 feet into area <strong>A3</strong></p>\n<hr>\n<p><strong>Effect</strong> The eerie call of the entropy choir saps the will of living creatures. A living creature who fails a DC 36 Will save becomes Slowed 1 as long as they remain in area <strong>A3</strong>. The entropy choir then rolls initiative.</p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/fire-pot-ubanu":{"lang":["Common","Draconic","Jotun","Pyric"],"lore":[["Weapons Lore",16]],"gear":["Fulminating Spear","Alchemist's Fire (Moderate) (Infused) (8)","Tanglefoot Bag (Moderate) (Infused) (2)","Smock","Elixir of Life (Lesser) (Infused) (2)"],"abilities":[{"n":"Infused Items","a":null,"c":"interaction","t":[],"f":"","d":"<p>Ubanu carries these infused items: 8 moderate alchemist's fires, 2 lesser elixirs of life, and 2 moderate tanglefoot bags. These items last for 24 hours, or until the next time Ubanu makes his daily preparations.</p>"},{"n":"Distracting Spells","a":null,"c":"offensive","t":[],"f":"","d":"<p>Creatures who fail a saving throw against one of Ubanu's spells are Off-Guard to his attacks until the end of his turn or until the end of his next turn on a critical failure.</p>"},{"n":"Quick Bomber","a":"1","c":"offensive","t":[],"f":"","d":"<p>Ubanu Interacts to draw a bomb, then Strikes with it.</p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/flensing-chute":{"description":"<p>The stairs collapse into a downward spiral.</p>","disable":"<p>DC 35 Thievery (master) to decouple several mechanisms barely accessible through gaps between the shifting risers, or DC 38 Perception to note which stairs have slightly different wear patterns to know which ones are safe to step on</p>","reset":"<p>The flensing chute resets automatically.</p>","stealthNote":"<p>(master)</p>","abilities":[{"n":"Change to Chute","a":"r","c":"offensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A Small or larger creature approaches within 20 feet of the top of the stairs</p>\n<p><strong>Reaction</strong> The stair risers shift downward, forming a steep ramp while exposing lines of razor-sharp blades.</p>\n<p>All creatures on the stairs must succeed at a DC 32 Reflex save or tumble down the chute, taking 2d6 bludgeoning damage + 4d12+26 slashing damage, and landing Prone in area <strong>A4</strong>.</p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/formian-mageslayer":{"lang":["Akitonian","Formian","telepathy 120 feet"],"flavor":"<p>Grim, twisted formians forced into existence through the machinations of the King of Biting Ants, formian mageslayers are created for the express purpose of neutralizing and destroying enemy spellcasters. Wired to never sleep, mageslayers are tortured hunters and guardians whose only relief is found in tearing apart the magic and flesh of spellcasters who oppose the King of Biting Ants. Formian mageslayers have wings resembling those of dragonflies and longer, sleeker bodies than most formians.</p>\n<hr>\n<p>Formians resemble unusually large ants with an insectile humanoid's upper torso. More powerful or influential formians are physically larger; common formian workers are roughly the height of a gnome, while the largest formians, such as taskmasters and queens, rival a giant in size.</p>\n<p>Formian society is a strict matriarchy. Though each hive's queen is theoretically independent and her rule absolute, allegiances are common, and less powerful hives often (grudgingly) defer to more powerful matriarchs.</p>","abilities":[{"n":"Tremorsense 60 feet","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>Tremorsense allows a monster to feel the vibrations through a solid surface caused by movement. It is an imprecise sense with a limited range (listed in the ability). Tremorsense functions only if the monster is on the same surface as the subject, and only if the subject is moving along (or burrowing through) the surface.</p></p>"},{"n":"Telepathy 120 feet","a":null,"c":"interaction","t":["aura","magical"],"f":"","d":"<p><p>A monster with telepathy can communicate mentally with any creatures within the listed radius, as long as they share a language. This doesn't give any special access to their thoughts, and communicates no more information than normal speech would.</p></p>"},{"n":"Hive Mind","a":null,"c":"interaction","t":["primal"],"f":"","d":"<p>Formians operate from a shared hive intelligence that allows them to communicate nearly instantaneously. While within telepathic range of at least one other formian from the same hive mind, a formian worker gains a +2 circumstance bonus to initiative checks, Perception checks, and saving throws against mental effects. If one formian is aware of a combatant, all members of the hive mind within range are aware of it.</p>"},{"n":"Disrupting Aura","a":null,"c":"defensive","t":["aura","primal"],"f":"","d":"<p>30 feet. Formian mageslayers are surrounded by an aura of disruptive energy that disperses magical energy and makes spellcasting difficult for their enemies.</p>\n<p>Whenever an enemy creature within the aura attempts to Cast a Spell or Activate a magic item, they must roll a DC 5 Flat; on a failed check, the spell or activation is lost and the action is wasted. Free action activations disrupted by this aura can't be attempted again until the start of the activating creature's next turn.</p>"},{"n":"Shred Spell","a":"r","c":"defensive","t":["primal"],"f":"","d":"<p><strong>Trigger</strong> A creature within the formian mageslayer's disrupting aura that the formian mageslayer can see succeeds at a DC 5 Flat to Cast the Spell in the aura</p>\n<hr>\n<p><strong>Effect</strong> The mageslayer attempts to unravel the spell's magic and attempts to counteract the spell. They use their Arcana modifier as their counteract modifier with a counteract rank of 8.</p>\n<p>If the formian mageslayer succeeds, they counter the spell and use the dispersed energy to gain a number of temporary Hit Points equal to twice the spell's rank for 1 minute. If the formian mageslayer critically fails this counteract check, their disrupting aura deactivates for 1 minute.</p>"},{"n":"Spell Resistance","a":null,"c":"defensive","t":[],"f":"","d":"<p>A formian mageslayer takes 15 fewer damage from any arcane or primal spell that causes damage, and 10 less damage from any divine or occult spell that causes damage.</p>"},{"n":"Stupefying Touch","a":null,"c":"offensive","t":["curse","primal"],"f":"","d":"<p>A creature damaged by a mageslayer's claw Strike must succeed at a DC 37 Will save. The creature becomes Stupefied 2 for 1 round on a failure. On a critical failure, the creature is stupefied 2 for 1 hour.</p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/formian-queen":{"lang":["Akitonian","Formian","telepathy 200 feet"],"flavor":"<p>The formian queen is the center of the formian hive. The queen identifies and attends to the hive's needs, laying egg clusters that vary from a single formian born to a particular task to hundreds of workers at a time. All formians are born with an instinctive deference for the queen that borders on slavish devotion, though this urge can be corrupted, as with the King of Biting Ants' mutant mageslayers.</p>\n<hr>\n<p>Formians resemble unusually large ants with an insectile humanoid's upper torso. More powerful or influential formians are physically larger; common formian workers are roughly the height of a gnome, while the largest formians, such as taskmasters and queens, rival a giant in size.</p>\n<p>Formian society is a strict matriarchy. Though each hive's queen is theoretically independent and her rule absolute, allegiances are common, and less powerful hives often (grudgingly) defer to more powerful matriarchs.</p>","abilities":[{"n":"Tremorsense 60 feet","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>Tremorsense allows a monster to feel the vibrations through a solid surface caused by movement. It is an imprecise sense with a limited range (listed in the ability). Tremorsense functions only if the monster is on the same surface as the subject, and only if the subject is moving along (or burrowing through) the surface.</p></p>"},{"n":"Telepathy 200 feet","a":null,"c":"interaction","t":["aura","magical"],"f":"","d":"<p><p>A monster with telepathy can communicate mentally with any creatures within the listed radius, as long as they share a language. This doesn't give any special access to their thoughts, and communicates no more information than normal speech would.</p></p>"},{"n":"Hive Mind","a":null,"c":"interaction","t":["primal"],"f":"","d":"<p>Formians operate from a shared hive intelligence that allows them to communicate nearly instantaneously. While within telepathic range of at least one other formian from the same hive mind, a formian worker gains a +2 circumstance bonus to initiative checks, Perception checks, and saving throws against mental effects. If one formian is aware of a combatant, all members of the hive mind within range are aware of it.</p>"},{"n":"Hive Frenzy","a":"1","c":"offensive","t":["mental","primal"],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p>\n<hr>\n<p><strong>Effect</strong> The formian queen stirs all formians within range of her telepathy into a frenzy. Each affected formian gains the Quickened condition for 1 minute, and can use the extra action each round only to Strike or Stride.</p>"},{"n":"Possess Formian","a":"1","c":"offensive","t":["incapacitation","mental","possession","primal"],"f":"","d":"<p>A formian queen transfers her consciousness to the body of any formian within range of her telepathy to whom she has a line of effect. As long as the queen's consciousness is outside her body, her body is Unconscious (though she is aware if any damage is dealt to it).</p>\n<p>An unwilling target can attempt a DC 38 Will saving throw to resist being possessed, but the queen's offspring are part of her hive mind and thus are almost always willing. The queen receives all sensory input from the target creature; she can speak through it, and she can use her own modifier for Intelligence-, Wisdom-, and Charisma-based skill checks.</p>\n<p>If the target creature is slain or moves to a different plane from the queen's body, the queen returns to her own body immediately and is Stunned 1; otherwise, she can return to her own body as a free action, ending the possession effect.</p>"},{"n":"Telepathic Feedback","a":"2","c":"offensive","t":["mental","primal"],"f":"","d":"<p>The formian queen unleashes a blast of debilitating telepathic feedback, targeting as many creatures as she wishes within range of her telepathy and to whom she has a line of effect. Targeted creatures must attempt a DC 38 Will save.</p>\n<hr>\n<p><strong>Critical Success</strong> The creature is unaffected and is temporarily immune to Telepathic Feedback for 24 hours.</p>\n<p><strong>Success</strong> The creature takes 3d6 mental damage, 1d6 persistent mental, and is Sickened 1.</p>\n<p><strong>Failure</strong> The creature takes 6d6 mental damage, 1d6 persistent mental damage, and is Sickened 2.</p>\n<p><strong>Critical Failure</strong> The creature takes 12d6 mental damage, 1d6 persistent mental damage, and is Stunned 3. Upon recovering from the stunned condition, the creature becomes sickened 2.</p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/formian-worker":{"lang":["Akitonian","Formian","telepathy 30 feet"],"flavor":"<p>By far the most common formian on Akiton, workers are focused and industrious, naturally skilled at manual labor and coordinating with peers.</p>\n<hr>\n<p>Formians resemble unusually large ants with an insectile humanoid's upper torso. More powerful or influential formians are physically larger; common formian workers are roughly the height of a gnome, while the largest formians, such as taskmasters and queens, rival a giant in size.</p>\n<p>Formian society is a strict matriarchy. Though each hive's queen is theoretically independent and her rule absolute, allegiances are common, and less powerful hives often (grudgingly) defer to more powerful matriarchs.</p>","abilities":[{"n":"Telepathy 30 feet","a":null,"c":"interaction","t":["aura","magical"],"f":"","d":"<p><p>A monster with telepathy can communicate mentally with any creatures within the listed radius, as long as they share a language. This doesn't give any special access to their thoughts, and communicates no more information than normal speech would.</p></p>"},{"n":"Hive Mind","a":null,"c":"interaction","t":["primal"],"f":"","d":"<p>Formians operate from a shared hive intelligence that allows them to communicate nearly instantaneously. While within telepathic range of at least one other formian from the same hive mind, a formian worker gains a +2 circumstance bonus to initiative checks, Perception checks, and saving throws against mental effects. If one formian is aware of a combatant, all members of the hive mind within range are aware of it.</p>"},{"n":"Able Assistant","a":null,"c":"defensive","t":[],"f":"","d":"<p>When using the Aid action to assist another formian from the same hive mind within range of its hive link, if the formian worker rolls a success, they get a critical success instead, and if they roll a critical failure, they get a failure instead.</p>"},{"n":"Heavy Lifter","a":null,"c":"offensive","t":[],"f":"","d":"<p>Formian workers excel at heavy labor. A formian worker can carry 5 additional bulk beyond the normal limits for their Strength before becoming encumbered or overburdened.</p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/froglegs":{"lang":["Common","Elven","Tripkee","Iruxi"],"lore":[["Underworld Lore",15]],"gear":["Dagger (4)","Habu's Cudgel","Leather Armor","Thieves' Tools (Infiltrator)"],"abilities":[{"n":"Deny Advantage","a":null,"c":"defensive","t":[],"f":"","d":"<p>Froglegs isn't Off-Guard to creatures of 8th level or lower that are Hidden, Undetected, flanking, or using surprise attack.</p>"},{"n":"Knife Fighter","a":null,"c":"offensive","t":[],"f":"","d":"<p>Froglegs deals an additional 2d6 precision damage with weapons from the knife group, and knives gain the deadly d10 weapon property while she wields them. (Already added to dagger attacks)</p>"},{"n":"Roll and Snatch","a":"f","c":"offensive","t":[],"f":"","d":"<p><strong>Trigger</strong> Froglegs successfully Tumbles Through an enemy's space</p>\n<hr>\n<p><strong>Effect</strong> Froglegs attempts to Disarm or Trip the enemy. She can use her tongue for this attempt and does not need to have a free hand.</p>"},{"n":"Twin Slash","a":"1","c":"offensive","t":["flourish"],"f":"","d":"<p>Froglegs makes two dagger Strikes.</p>"}]},"strength-of-thousands-bestiary/book-4-secrets-of-the-temple-city/gambulami":{"lang":["Aklo","Common","Fey"],"gear":["Deflecting Branch","Spear (3)","Leather Armor"],"abilities":[{"n":"Attack of Opportunity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Inspired Feast","a":null,"c":"offensive","t":["emotion","mental"],"f":"","d":"<p>If a biloko feasts on a human corpse for 1 minute or more, they gain a +1 status bonus to attack rolls and a +2 status bonus to damage rolls for 1 hour.</p>"},{"n":"Size Alteration","a":"2","c":"offensive","t":["polymorph","primal"],"f":"","d":"<p>Gambulami is affected by a 4th-rank Enlarge spell. This lasts for 1 minute, and Gambulami can Dismiss the Spell.</p>"},{"n":"Thrashing Chomp","a":"2","c":"offensive","t":[],"f":"","d":"<p><strong>Requirements</strong> Gambulami is larger than Small in size and has a creature Grabbed with his jaws</p><hr>\n<p><strong>Effect</strong> Gambulami whips the creature around, smashing it against other nearby creatures. He makes an Athletics vs. Fortitude DC check against the grabbed creature's Fortitude DC. Regardless of the result, the creature is released from Gambulami's jaws afterward, escaping into the space in which it was grabbed.</p>\n<hr>\n<p><strong>Critical Success</strong> Gambulami uses a mighty spin to smash the held creature against every creature within his reach. Every creature, including the grabbed creature, takes 1d10+7 bludgeoning damage.</p>\n<p><strong>Success</strong> As critical success, but creatures take 1d10 bludgeoning damage.</p>\n<p><strong>Failure</strong> The creature breaks free.</p>\n<p><strong>Critical Failure</strong> The creature breaks free and Gambulami's spin causes him to fall Prone.</p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/gbahali":{"flavor":"<p>Resembling an enormous, long-legged alligator, the gbahali is larger, stronger, faster, and more cunning than all but the largest of its crocodilian kin. Gbahalis will range far from the banks of the rivers they inhabit to seek prey. With a powerful, squat snout, a gbahali viciously bites their quarry, while their powerful hind legs allow them to leap upon fleeing creatures or stride away to safety when threatened.</p>\n<p>Gbahalis are solitary creatures, splitting their time between the rivers that offer easy meals of fish and aquatic snakes and stalking the edges of the hunting territories of larger, meatier prey. Given the option, gbahalis much prefer warm-blooded food, but a hungry or injured gbahali remains near a river where it can more easily consume large fish, snakes, or even crocodiles until it's ready to hunt its preferred quarry once again. An adult gbahali can quickly take down and consume livestock, leaving no sign of its meals but enormous scuffed tracks in the ground, as its jaws are large enough to swallow many creatures whole.</p>\n<p>Gbahalis have a basic understanding of humanoid behavior. A gbahali learns quickly to evade trackers and traps, and can skillfully hunt along the fringes of a settlement for months before its presence becomes known. They usually avoid humanoid prey, even when hungry; they know that humanoid communities may hunt them in dogged retaliation for feasting upon a humanoid. Gbahalis therefore prefer to hunt far-ranging livestock like ranch or grazing animals. If another predator threatens a gbahali's territory, it might attack a humanoid, leave messy remains strewn about, and then retreat from the area for several weeks. In this time, it hopes the angry humanoids will hunt and kill its rival, leaving the gbahali an uncontested hunting ground when it returns.</p>","abilities":[{"n":"Attack of Opportunity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Deep Breath","a":null,"c":"defensive","t":[],"f":"","d":"<p>A gbahali can hold its breath for 2 hours.</p>"},{"n":"Aquatic Ambush","a":"1","c":"offensive","t":[],"f":"","d":"<p>40 feet</p>\n<hr>\n<p><p><strong>Requirements</strong> The monster is hiding in water and a creature that hasn't detected it is within the listed number of feet.</p>\n<hr>\n<p><strong>Effect</strong> The monster moves up to its swim Speed + 10 feet toward the triggering creature, traveling on water and on land. Once the creature is in reach, the monster makes a Strike against it. The creature is Off-Guard against this Strike.</p></p>"},{"n":"Powerful Jumper","a":null,"c":"offensive","t":[],"f":"","d":"<p>A gbahali jumps 10 feet up on a successful High Jump: Athletics or 20 feet up on a critical success.</p>"},{"n":"Swallow Whole","a":"1","c":"offensive","t":["attack"],"f":"","d":"<p>Medium, 2d8+7 bludgeoning, Rupture 20</p>\n<hr>\n<p><p>The monster attempts to swallow a creature of the listed size or smaller that it has grabbed or restrained in its jaws or mouth. If a swallowed creature is of the maximum size listed, the monster can't use Swallow Whole again. If the creature is smaller than the maximum, the monster can usually swallow more creatures; the GM determines the maximum. The monster attempts an Athletics vs. Reflex DC check opposed by the grabbed creature's Reflex DC. If it succeeds, it swallows the creature. The monster's mouth or jaws no longer grab a creature it has swallowed, so the monster is free to use them to Strike or Grab once again. The monster can't attack creatures it has swallowed.</p>\n<p>A swallowed creature is Grabbed, is Slowed 1, and has to hold its breath or start suffocating. The swallowed creature takes the listed amount of damage when first swallowed and at the end of each of its turns while it's swallowed. If the victim Escapes this ability's grabbed condition, it exits through the monster's mouth. This frees any other creature grabbed in the monster's mouth or jaws. A swallowed creature can attack the monster that has swallowed it, but only with unarmed attacks or with weapons of light Bulk or less. The swallowing creature is Off-Guard against the attack. If the monster takes piercing or slashing damage equaling or exceeding the listed Rupture value from a single attack or spell, the swallowed creature cuts itself free. A creature that gets free by either Escaping or cutting itself free can immediately breathe and exits the swallowing monster's space.</p>\n<p>Effect: Engulf and Swallow Whole</p>\n<p>If the monster dies, a swallowed creature can be freed by creatures adjacent to the corpse if they spend a combined total of 3 actions cutting the monster open with a weapon or unarmed attack that deals piercing or slashing damage.</p></p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/giant-goliath-beetle":{"abilities":[{"n":"Trample","a":"3","c":"offensive","t":[],"f":"","d":"<p>Medium or smaller, foot, DC 19 basic Reflex</p>\n<hr>\n<p><p>The monster Strides up to double its Speed and can move through the spaces of creatures of the listed size, Trampling each creature whose space it enters. The monster can attempt to Trample the same creature only once in a single use of Trample. The monster deals the damage of the listed Strike, but trampled creatures can attempt a basic Reflex save at the listed DC (no damage on a critical success, half damage on a success, double damage on a critical failure).</p></p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/giant-mining-bee":{"flavor":"<p>Giant mining bees have smaller bodies than giant worker bees but sometimes look larger due to their bristles, which resemble fur. They dig tunnels in sand, old wood, or stone to create nests and aggressively defend their lairs. Although not truly subterranean, giant mining bees are the most likely type of giant bees to be found underground, and some dwarf apiarists breed and train them.</p>\n<hr>\n<p>Like their smaller counterparts, giant bees are highly territorial. Many types of giant bees construct hives in caves or abandoned buildings and are quick to attack creatures that they deem a threat to the single fertile queen, who almost never leaves the hive. Although most common in warm biomes with lots of vegetation, some giant bees live in arid or cold environments and are solitary rather than hive-dwelling.</p>","abilities":[{"n":"Tremorsense (Imprecise) 30 feet","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>Tremorsense allows a monster to feel the vibrations through a solid surface caused by movement. It is an imprecise sense with a limited range (listed in the ability). Tremorsense functions only if the monster is on the same surface as the subject, and only if the subject is moving along (or burrowing through) the surface.</p></p>"},{"n":"Smoke Susceptibility","a":null,"c":"interaction","t":[],"f":"","d":"<p>A giant bee is Slowed 1 for 1 round if it starts its turn in heavy smoke.</p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/giant-silverfish":{"flavor":"<p>It's uncommon for silverfish to congregate in sufficient numbers to constitute a swarm, but forgotten libraries or similar out-of-the-way places might harbor a multitude of the voracious pests.</p>\n<hr>\n<p>A common pest with a silvery carapace and an undulating, fishlike scuttle, the nocturnal silverfish infests homes and libraries throughout Golarion. These insects aren't typically dangerous, but their tendency to devour books and clothing often puts them at odds with larger creatures.</p>","abilities":[{"n":"Voracious Consumption","a":null,"c":"interaction","t":[],"f":"","d":"<p>Action 1 minute</p>\n<p>A giant silverfish consumes up to 1 Bulk of paper, cloth, or similar material. It can consume up to 8 Bulk each day.</p>"},{"n":"Wriggle","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature the giant silverfish can see targets it with an attack</p>\n<hr>\n<p><strong>Effect</strong> The giant silverfish gains a +2 circumstance bonus to AC against the triggering attack. After the attack resolves, the silverfish Steps.</p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/giant-tsetse-fly":{"notes":{"per":"blood scent"},"flavor":"<p>This blood-sucking fly, the size of a horse, is widely despised as a harbinger of disease. Giant tsetse flies rarely congregate in large numbers, as they require gallons of blood each day to survive and thus crowd out or drive away rivals. Any group of creatures large enough to sustain multiple tsetse flies, such as a herd of dinosaurs, are quite likely to dominate the surrounding ecosystem on their own right.</p>\n<p>A single giant tsetse fly can kill an entire herd of large animals within a few weeks, and those they don't kill often succumb to disease. When not hunting, giant tsetse flies prefer to hide in warm, dark places in forests and swamps, though they sometimes inhabit wet cave systems where prey is plentiful. The thrumming drone of their wings echoes around such cave systems, warning travelers familiar with the noise that the creatures are lairing nearby.</p>\n<p>If food becomes scarce, a giant tsetse fly relocates elsewhere. They tend to follow rivers, animal tracks, or even roads to find food. This can take them to the fringes of civilization, where farms and ranches often have livestock that draws their attention. Settlers who find evidence of a giant tsetse fly should quickly seek out help to eliminate the pests, as all their animals (and, indeed, their families) are in jeopardy as long as the hungry insect is near.</p>\n<p>Giant tsetse flies are only moderately smarter than ordinary flies, but some creatures have learned that they can train the creatures with frequent offerings of fresh blood. Giant tsetse flies might therefore be put to use as guardians or even mounts, but any potential trainer must take care not to become the voracious insect's next meal.</p>","abilities":[{"n":"Blood Scent","a":null,"c":"interaction","t":[],"f":"","d":"<p>The giant tsetse fly can detect blood within 30 feet. This is a precise sense against creatures within 30 feet that are bleeding.</p>"},{"n":"Blood Draw","a":"1","c":"offensive","t":[],"f":"","d":"<p>If the fly's last action was a successful proboscis Strike, it sucks its target's blood. The target takes 1d4 bleed (or 1d6 bleed if the target is an animal).</p>"},{"n":"Sleeping Sickness","a":null,"c":"offensive","t":["disease"],"f":"","d":"<p><strong>Saving Throw</strong> DC 18 Fortitude</p>\n<p><strong>Stage 1</strong> Enfeebled 1 (1 day)</p>\n<p><strong>Stage 2</strong> enfeebled 1 and Drained 1 (1 day)</p>\n<p><strong>Stage 3</strong> Unconscious</p>\n<p>(1 day)</p>\n<p><strong>Stage 4</strong> as Stage 3 (1 day)</p>\n<p><strong>Stage 5</strong> dead</p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/giant-worker-bee":{"flavor":"<p>Worker bees, exclusively female, exist to feed and defend a hive. They have no qualms about sacrificing their lives when confronting intruders in their territory. Worker bees can fight singly, in small groups, or in swarms of dozens. Giant worker bees inject a venom with their stings, but this venom is rarely dangerous except to people sensitive to it. Other worker bees have no stinger and only bite their enemies.</p>\n<hr>\n<p>Like their smaller counterparts, giant bees are highly territorial. Many types of giant bees construct hives in caves or abandoned buildings and are quick to attack creatures that they deem a threat to the single fertile queen, who almost never leaves the hive. Although most common in warm biomes with lots of vegetation, some giant bees live in arid or cold environments and are solitary rather than hive-dwelling.</p>","abilities":[{"n":"Smoke Susceptibility","a":null,"c":"interaction","t":[],"f":"","d":"<p>A giant bee is Slowed 1 for 1 round if it starts its turn in heavy smoke.</p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/gluttonworm":{"notes":{"hp":"sand armor"},"flavor":"<p>Akiton's gluttonworms share many features of Golarion's cave worms, yet these immense predators are their own distinct species. Gluttonworms \"swim\" through the vast deserts of Akiton, moving almost like whales through the ocean as they forage for their next meals.</p>","abilities":[{"n":"Tremorsense 100 feet","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>Tremorsense allows a monster to feel the vibrations through a solid surface caused by movement. It is an imprecise sense with a limited range (listed in the ability). Tremorsense functions only if the monster is on the same surface as the subject, and only if the subject is moving along (or burrowing through) the surface.</p></p>"},{"n":"Dune Dispersal","a":null,"c":"defensive","t":["aura"],"f":"","d":"<p>15 feet. Ground in the aura is greater difficult terrain.</p>"},{"n":"Inexorable","a":null,"c":"defensive","t":[],"f":"","d":"<p>The gluttonworm recovers from the Paralyzed, Slowed, and Stunned conditions at the end of its turn.</p>\n<p>It's also immune to penalties to its Speeds and the Immobilized condition, and it ignores difficult terrain and greater difficult terrain.</p>"},{"n":"Sand Armor","a":null,"c":"defensive","t":["primal"],"f":"","d":"<p>A gluttonworm in contact with a significant body of sand, such as a desert or beach, gains fast healing 10.</p>\n<p>If the gluttonworm is subject to persistent bleed, the flowing blood quickly congeals with the sand covering its body, instantly ending the bleed duration and giving the gluttonworm a +2 circumstance bonus to AC until the end of its next turn.</p>"},{"n":"Fast Swallow","a":"r","c":"offensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The gluttonworm Grabs a creature, or a creature fails a Reflex save against a Gulping Charge</p>\n<hr>\n<p><strong>Effect</strong> The gluttonworm uses Swallow Whole.</p>"},{"n":"Gulping Charge","a":"3","c":"offensive","t":[],"f":"","d":"<p>The gluttonworm Strides up to double its Speed and can move through the spaces of Large or smaller creatures, gulping each creature whose space the worm enters and attempting a body Strike against each of them.</p>\n<p>The gluttonworm can use this Strike on each creature only once in a single use of Gulping Charge. Creatures can attempt a DC 41 basic Reflex save against this damage.</p>"},{"n":"Spew Sandstorm","a":"3","c":"offensive","t":["air","earth","primal"],"f":"","d":"<p>The gluttonworm exhales swirling sand in a 60-foot cone. Creatures in the area must attempt a DC 41 Reflex save.</p>\n<p>It can't Spew Sandstorm again for 1d4 rounds.</p>\n<hr>\n<p><strong>Critical Success</strong> The creature is unaffected.</p>\n<p><strong>Success</strong> The creature takes 4d6 slashing damage and 4d6 bludgeoning damage from the scouring sand.</p>\n<p><strong>Failure</strong> The creature takes 8d6 slashing damage and 8d6 bludgeoning damage from the sand, and is Dazzled until the end of its next turn.</p>\n<p><strong>Critical Failure</strong> The creature takes 12d6 slashing damage and 12d6 bludgeoning damage and is Blinded for 1 hour.</p>"},{"n":"Swallow Whole","a":"1","c":"offensive","t":["attack"],"f":"","d":"<p>Huge, 3d10+17 bludgeoning and 2d6 slashing, Rupture 36</p>\n<hr>\n<p><p>The monster attempts to swallow a creature of the listed size or smaller that it has grabbed or restrained in its jaws or mouth. If a swallowed creature is of the maximum size listed, the monster can't use Swallow Whole again. If the creature is smaller than the maximum, the monster can usually swallow more creatures; the GM determines the maximum. The monster attempts an Athletics vs. Reflex DC check opposed by the grabbed creature's Reflex DC. If it succeeds, it swallows the creature. The monster's mouth or jaws no longer grab a creature it has swallowed, so the monster is free to use them to Strike or Grab once again. The monster can't attack creatures it has swallowed.</p>\n<p>A swallowed creature is Grabbed, is Slowed 1, and has to hold its breath or start suffocating. The swallowed creature takes the listed amount of damage when first swallowed and at the end of each of its turns while it's swallowed. If the victim Escapes this ability's grabbed condition, it exits through the monster's mouth. This frees any other creature grabbed in the monster's mouth or jaws. A swallowed creature can attack the monster that has swallowed it, but only with unarmed attacks or with weapons of light Bulk or less. The swallowing creature is Off-Guard against the attack. If the monster takes piercing or slashing damage equaling or exceeding the listed Rupture value from a single attack or spell, the swallowed creature cuts itself free. A creature that gets free by either Escaping or cutting itself free can immediately breathe and exits the swallowing monster's space.</p>\n<p>Effect: Engulf and Swallow Whole</p>\n<p>If the monster dies, a swallowed creature can be freed by creatures adjacent to the corpse if they spend a combined total of 3 actions cutting the monster open with a weapon or unarmed attack that deals piercing or slashing damage.</p></p>"},{"n":"Improved Grab","a":"f","c":"offensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> The monster's last action was a successful Strike that lists Improved Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with as a free action. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Improved Grab as an action and choose one creature it's grabbing or restraining with an appendage that has Improved Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/gnagrif":{"lang":["Sakvroth"],"gear":["Light Hammer"],"flavor":"<p>Squat, surly, and perpetually covered in wet mud, gnagrifs are gremlins that infest and destroy homes. They possess sharklike faces and two sets of jaws, allowing them to open their mouths 180 degrees and clamp onto flat rocks and walls. They delight in keeping their presence hidden, chewing holes into walls and foundations that weaken structures but don't bring them down until their inhabitants slam their doors too hard or step in the wrong place. Soon as the unwitting victims spring the trap, the building collapses around them.</p>\n<p>Like all fey, gnagrifs detest iron. Gnagrifs become obsessively vengeful if they accidentally swallow an iron nail or hinge, terrorizing families or whole villages for generations over the slight.</p>\n<hr>\n<p>Gremlins are malicious fey that infest and prey upon mortal communities. They live in tunnels, beneath eaves, and in abandoned buildings, stealing what they need from their neighbors instead of creating for themselves.</p>\n<p>While there are gremlins of any and every gender, their appearances don't differ by gender. Young gremlins grow to maturity with alarming speed. Their entire nest raises them communally, though they are often encouraged to wander unsupervised and create mischief away from home instead of inside it.</p>","abilities":[{"n":"Rubble Stride","a":null,"c":"interaction","t":[],"f":"","d":"<p>A gnagrif ignores difficult terrain caused by rocks or rubble, including squares affected by their Stomp Around.</p>"},{"n":"Soften Stone","a":"r","c":"interaction","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature Strides or Steps into difficult terrain adjacent to the gnagrif</p>\n<hr>\n<p><strong>Effect</strong> The gnagrif gives the ground a hearty pound and it shifts beneath the triggering creature's feet. The triggering creature must succeed on a DC 18 Reflex save or fall Prone.</p>"},{"n":"Stomp Around","a":"1","c":"interaction","t":["move"],"f":"","d":"<p>The gnagrif huffs and stamps its feet, churning the ground around it. The square it is in and all unoccupied adjacent squares become difficult terrain.</p>"},{"n":"Lurk","a":"2","c":"defensive","t":[],"f":"","d":"<p><strong>Requirements</strong> A structure made from stone or earth is within the gnagrif's reach</p>\n<hr>\n<p><strong>Effect</strong> The gnagrif partially melds with the stone. It Takes Cover in the stone and makes a Stealth check to Hide: Stealth.</p>"},{"n":"Eat Rocks","a":"1","c":"offensive","t":[],"f":"","d":"<p>The gnagrif gnashes and tears at an object or structure, dealing 2d4+2 piercing damage and ignoring Hardness 2 or lower.</p>"},{"n":"Wrecker","a":null,"c":"offensive","t":[],"f":"","d":"<p>Whenever two or more gnagrifs use Eat Rocks on the same object or structure, the value of Hardness they can ignore increases by 1 for every gnagrif, to a maximum of Hardness 10.</p>"}]},"strength-of-thousands-bestiary/book-4-secrets-of-the-temple-city/gold-defender":{"abilities":[{"n":"Death Throes","a":null,"c":"defensive","t":[],"f":"","d":"<p>When the gold defender is destroyed, it melts into worthless slag. As it melts, it releases a 10-foot burst cloud of fumes and a 10-foot radius puddle of molten metal. Creatures that breathe fumes are exposed to gold defender poison. Creatures that move through the puddle take 10d6 fire damage. The fumes dissipate after 1 round and the puddle cools after 1 minute.</p>"},{"n":"Golem Antimagic","a":null,"c":"defensive","t":[],"f":"","d":"<p>Harmed by cold (6d10 untyped, 2d8 untyped from areas or persistent damage); healed by fire (area 2d8 healing HP); slowed by acid</p><hr><p><p>A golem is immune to spells and magical abilities other than its own, but each type of golem is affected by a few types of magic in special ways. These exceptions are listed in shortened form in the golem's stat block, with the full rules appearing here. If an entry lists multiple types (such as \"cold and water\"), either type of spell can affect the golem.</p><ul><li><strong>Harmed By</strong> Any magic of this type that targets the golem causes it to take the listed amount of damage (this damage has no type) instead of the usual effect. If the golem starts its turn in an area of magic of this type or is affected by a persistent effect of the appropriate type, it takes the damage listed in the parenthetical.</li><li><strong>Healed By</strong> Any magic of this type that targets the golem makes the golem lose the slowed condition and gain HP equal to half the damage the spell would have dealt. If the golem starts its turn in an area of this type of magic, it gains the HP listed in the parenthetical.</li><li><strong>Slowed By</strong> Any magic of this type that targets the golem causes it to be Slowed 1 for 2d6 rounds instead of the usual effect. If the golem starts its turn in an area of this type of magic, it's slowed 1 for that round.</li><li><strong>Vulnerable To</strong> Each golem is vulnerable to one or more specific spells, with the effects described in its stat block.</li></ul></p>"},{"n":"Malleable Shape","a":null,"c":"defensive","t":[],"f":"","d":"<p>The gold defender's body is made from soft gold, which is particularly pliable. If the gold defender is critically hit with an attack that deals bludgeoning damage, the attack partially bends and reshapes the gold defender. The gold defender becomes Clumsy 2 until it spends an Interact action to bend itself back into shape.</p>"},{"n":"Vulnerable to Telekinetic Haul","a":null,"c":"defensive","t":[],"f":"","d":"<p>Casting Telekinetic Haul on the gold defender squeezes its form, compressing it into a smaller and much more awkward shape. The gold defender becomes Clumsy 3 and can't use Light Reflection. The gold defender must take a 1-minute activity, which has the manipulate trait, to restore its shape, removing the clumsy condition and restoring its Light Reflection.</p>"},{"n":"Gold Defender Poison","a":null,"c":"offensive","t":["poison"],"f":"","d":"<p>Any Drained value from this poison is reduced by 1 every hour</p>\n<p><strong>Saving Throw</strong> DC 33 Fortitude</p>\n<p><strong>Maximum Duration</strong> 4 rounds</p>\n<p><strong>Stage 1</strong> 2d6 poison and Drained 1 (1 round)</p>\n<p><strong>Stage 2</strong> 4d6 poison and Drained 2 (1 round)</p>\n<p><strong>Stage 3</strong> 8d6 poison and Drained 3 (1 round).</p>"},{"n":"Inexorable March","a":"1","c":"offensive","t":[],"f":"","d":"<p>The gold defender Strides up to its Speed, pushing back each creature whose space it moves into and damaging them if they try to stop its movement. A creature can attempt to bar the way by succeeding at a DC 37 Fortitude save. On a critical success, the resisting creature takes no damage; otherwise, it is damaged as if hit by the defender's fist Strike.</p>"},{"n":"Light Reflection","a":"2","c":"offensive","t":["primal"],"f":"","d":"<p><strong>Requirements</strong> The gold defender is not in darkness</p>\n<hr>\n<p><strong>Effect</strong> The gold defender reshapes its skin into a reflective surface that magnifies ambient light into a precise beam that burns all creatures in a 30-foot cone, dealing 14d6 fire damage (DC 31 Reflex save if the gold defender is in dim light, DC 33 Reflex save if it's in bright light). It can't use Light Reflection again for 1d4 rounds.</p>\n<hr>\n<p><strong>Critical Success</strong> The creature takes no damage.</p>\n<p><strong>Success</strong> The creature takes half damage.</p>\n<p><strong>Failure</strong> The creature takes full damage and catches fire, taking 1d6 persistent fire damage.</p>\n<p><strong>Critical Failure</strong> As failure, but the persistent fire damage is 5d6 persistent fire.</p>"}]},"strength-of-thousands-bestiary/book-4-secrets-of-the-temple-city/gold-defender-garrison":{"notes":{"hp":"16 squares (160 = 12 squares, 80 = 8 squares)"},"abilities":[{"n":"Form Up","a":"1","c":"interaction","t":[],"f":"","d":"<p><p>The troop chooses one of the squares it currently occupies and redistributes its squares to any configuration in which all squares are contiguous and within 15 feet of the chosen square. The troop can't share its space with other creatures.</p></p>"},{"n":"Death Throes","a":null,"c":"defensive","t":[],"f":"","d":"<p>As the garrison's numbers dwindle, gold defenders melt away into worthless slag. Every time that the garrison is reduced to a threshold, it leaves behind a 10-foot radius cloud of fumes and a 10-foot radius puddle of molten metal. Creatures that breathe fumes are exposed to gold defender poison. Creatures that move through the puddle take 10d6 fire damage. The fumes dissipate after 1 round and the puddle completely evaporates after 1 minute.</p>"},{"n":"Golem Antimagic","a":null,"c":"defensive","t":[],"f":"","d":"<p>Harmed by cold (2d8 untyped from areas or persistent damage); healed by fire (area 2d8 healing HP); slowed by acid</p><hr><p><p>A golem is immune to spells and magical abilities other than its own, but each type of golem is affected by a few types of magic in special ways. These exceptions are listed in shortened form in the golem's stat block, with the full rules appearing here. If an entry lists multiple types (such as \"cold and water\"), either type of spell can affect the golem.</p><ul><li><strong>Harmed By</strong> Any magic of this type that targets the golem causes it to take the listed amount of damage (this damage has no type) instead of the usual effect. If the golem starts its turn in an area of magic of this type or is affected by a persistent effect of the appropriate type, it takes the damage listed in the parenthetical.</li><li><strong>Healed By</strong> Any magic of this type that targets the golem makes the golem lose the slowed condition and gain HP equal to half the damage the spell would have dealt. If the golem starts its turn in an area of this type of magic, it gains the HP listed in the parenthetical.</li><li><strong>Slowed By</strong> Any magic of this type that targets the golem causes it to be Slowed 1 for 2d6 rounds instead of the usual effect. If the golem starts its turn in an area of this type of magic, it's slowed 1 for that round.</li><li><strong>Vulnerable To</strong> Each golem is vulnerable to one or more specific spells, with the effects described in its stat block.</li></ul></p>"},{"n":"Troop Defenses","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>Troops are composed of many individuals, represented by four \"segments\" on a battle grid. Each segment is 10 feet on each side and as tall as the individual members of the troop. Segments must remain contiguous. Each one has to share at least 5 feet of one of its edges with another segment—being adjacent on a diagonal isn't sufficient! You can measure flanking, cover, and the like using the center of any segment.</p>\n<p>A troop has two Hit Point thresholds in its HP entry and loses segments as it crosses thresholds. Typically, the higher threshold is at 2/3 of the troop's maximum Hit Points and the lower is at 1/3 of its maximum. Once the troop drops below the higher threshold, it loses one segment, leaving three segments (12 squares) remaining and setting the first threshold as the troop's new maximum Hit Points. This repeats when the troop drops below the lower threshold, leaving two segments (8 squares). At 0 Hit Points, the troop disperses entirely, with the few remaining members surrendering, Fleeing, or easily dispatched, as determined by the GM. Typically the creature who caused the troop to lose a segment decides which to remove, or the GM decides when a specific creature wasn't responsible. To restore lost segments and maximum Hit Points, a troop needs to spend downtime to use long-term treatment on casualties or recruit new members to replace the fallen.</p>\n<p>Troops are typically immune to non-damaging effects that target a single creature, such as a Charm spell or the Demoralize action. An ability that can target 5 or more creatures can target an entire segment, increasing to two segments if it can target 10 or more creatures and to the entire troop if it can target 20 or more creatures. An ability that affects all creatures in a certain range affects all segments in range (make any checks or saves separately for each segment). As examples, an 8th rank <em>charm</em> spell (with 10 targets) can affect two segments, and an ability that Demoralizes all creatures within 30 feet of you would affect all segments that are fully within that range. A non-damaging ability that would prevent a segment from acting, cause them to flee, or otherwise make them unable to function as part of the troop for a round or more removes the segment entirely. The troop loses a number of HP required to bring it to the next threshold. If an ability both deals damage and has a non-damaging effect, apply the damage then the rest of the effect.</p></p>"},{"n":"Gold Defender Poison","a":null,"c":"offensive","t":["poison"],"f":"","d":"<p>Any Drained value from this poison is reduced by 1 every hour</p>\n<p><strong>Saving Throw</strong> DC 33 Fortitude</p>\n<p><strong>Maximum Duration</strong> 4 rounds</p>\n<p><strong>Stage 1</strong> 2d6 poison and Drained 1 (1 round)</p>\n<p><strong>Stage 2</strong> 4d6 poison and Drained 2 (1 round)</p>\n<p><strong>Stage 3</strong> 8d6 poison and Drained 3 (1 round).</p>"},{"n":"Golden Strike","a":"1","c":"offensive","t":[],"f":"once per round","d":"<p>1 to 3</p>\n<p><strong>Frequency</strong> once per round</p><hr><p><strong>Effect</strong> The garrison makes a melee attack against each enemy in a 5-foot emanation (DC 30 basic Reflex save). The damage depends on the number of actions.</p>\n<p>1 2d8+2 bludgeoning damage</p>\n<p>2 3d8+12 bludgeoning damage</p>\n<p>3 4d8+15 bludgeoning damage</p>"},{"n":"Light Reflection","a":"2","c":"offensive","t":["primal"],"f":"","d":"<p><strong>Requirements</strong> The gold defender garrison is not in darkness</p>\n<hr>\n<p><strong>Effect</strong> The gold defender garrison reshapes its skin into a reflective surface that magnifies ambient light into a precise beam that burns all creatures in a 30-foot cone, dealing 14d6 fire damage (DC 31 Reflex save if the gold defender is in dim light, DC 33 Reflex save if it's in bright light). The size of the cone reduces to a 15-foot cone when the garrison is reduced to 8 or fewer squares. It can't use Light Reflection again for 1d4 rounds.</p>\n<hr>\n<p><strong>Critical Success</strong> The creature takes no damage.</p>\n<p><strong>Success</strong> The creature takes half damage.</p>\n<p><strong>Failure</strong> The creature takes full damage and catches fire, taking 1d6 persistent fire damage.</p>\n<p><strong>Critical Failure</strong> As failure, but the persistent fire damage is 5d6 persistent fire.</p>"},{"n":"Troop Movement","a":null,"c":"offensive","t":[],"f":"","d":"<p>Whenever the garrison Strides, it first Forms Up as a free action to condense into a 20-foot-by-20-foot area (minus any missing squares), then moves up to its Speed. This works just like a Gargantuan creature moving; for instance, if any square enters difficult terrain, the extra movement cost applies to the whole troop.</p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/golgopo":{"lang":["Cyclops"],"flavor":"<p>As their empire crumbled and fell into ruin, many cyclopes turned to increasingly depraved and vicious rituals to enhance their divinations and oracular powers. Some, especially those too fearful or suspicious of their fellow cyclopes to collaborate, constructed servants known as golgopos to aid in their rituals. These squat creatures are made from ancient bones dredged from fetid swamps and packed with mud to resemble a squat humanoid. Their heads are little more than the skull of whatever creature's bones were used in their creation with an extra eye socket punched in the forehead, glowing with eerie light.</p>\n<p>Golgopos spend most of their time perched on the shoulder of a cyclops master, acting as secondary casters for foul rituals and casting spells to aid them as needed. Golgopos are generally not evil, however, and one whose master has abandoned them or been destroyed might be convinced to employ their knowledge of ritual magic in service of another.</p>","abilities":[{"n":"Ritual Conduit","a":null,"c":"defensive","t":[],"f":"","d":"<p>Golgopos were created to assist with complex rituals. The golgopo can always use Occultism to attempt secondary checks during rituals, regardless of the skill normally required.</p>\n<p>If a golgopo would critically fail a secondary check, they fail instead.</p>"},{"n":"Warning Call","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature targets an Off-Guard ally within 10 feet of the golgopo</p>\n<hr>\n<p><strong>Effect</strong> The golgopo has a premonition of the attack and shouts a warning to their ally. The ally gains a +2 circumstance bonus to AC against the triggering attack.</p>"},{"n":"Portents of Doom","a":"1","c":"offensive","t":["auditory","emotion","fear","mental","occult"],"f":"","d":"<p>The golgopo unleashes a wailing cry that heralds impending disaster. Each creature within 30 feet must attempt a DC 26 Will save.</p>\n<p>Golgopos and cyclopes are immune to this effect.</p>\n<hr>\n<p><strong>Critical Success</strong> The creature is unaffected and temporarily immune for 1 minute.</p>\n<p><strong>Success</strong> The creature is unaffected.</p>\n<p><strong>Failure</strong> The creature is Frightened 1.</p>\n<p><strong>Critical Failure</strong> The creature is Frightened 2 and Confused for 1 round.</p>"}]},"strength-of-thousands-bestiary/book-4-secrets-of-the-temple-city/grave-karina":{"lang":["Common","Necril","(can't speak any language)"],"notes":{"per":"smoke vision"},"abilities":[{"n":"Smoke Vision","a":null,"c":"defensive","t":[],"f":"","d":"<p>Smoke doesn't impair a grave karina's vision; they ignore the Concealed condition from smoke, including the ash they create with their Breath Weapon.</p>"},{"n":"Sound Imitation","a":null,"c":"defensive","t":[],"f":"","d":"<p>A grave karina who succeeds at a Deception check to Lie can mimic any voice they have heard. They have a +4 circumstance bonus to this check.</p>"},{"n":"Breath Weapon","a":"2","c":"offensive","t":["divine","fire"],"f":"","d":"<p>The grave karina breathes a cloud of burning ash in 30-foot cone that deals 9d8 fire damage (DC 30 basic Reflex save). The area becomes filled with ash for 1 round. All creatures within the cloud of ash become Concealed, and all creatures outside the cloud become concealed to creatures within it. The grave karina can't use Breath Weapon again for 1d4 rounds.</p>"},{"n":"Grave Blight","a":null,"c":"offensive","t":["disease"],"f":"","d":"<p><strong>Saving Throw</strong> DC 27 Fortitude</p>\n<p><strong>Stage 1</strong> carrier with no ill effect (1 day)</p>\n<p><strong>Stage 2</strong> 2d6 poison damage, and Sickened 1 (1 day)</p>\n<p><strong>Stage 3</strong> 2d8 poison damage, every hour the victim must succeed at another Fortitude save or be Confused for 1 minute, and Sickened 2 (1 day)</p>"},{"n":"Mocking Cry","a":"1","c":"offensive","t":["auditory"],"f":"","d":"<p>The grave karina mimics a voice and mocks a creature within 30 feet. They attempt a Deception check to Demoralize the creature. Regardless of whether the check succeeds, the target is temporarily immune to the grave karina's mocking cry for 1 hour.</p>"},{"n":"Shadow Command","a":"2","c":"offensive","t":["concentrate","manipulate"],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p>\n<p><strong>Requirements</strong> The grave karina is adjacent to a creature that's casting a shadow</p><hr><p><strong>Effect</strong> The grave karina drives a talon into a creature's shadow and attempts to manipulate it like a puppet with the effects of Dominate(DC 27 Will save), except the duration is only 1 minute.</p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/great-grodair":{"lang":["Common","Fey","Thalassic"],"abilities":[{"n":"Death Flood","a":null,"c":"defensive","t":["primal","water"],"f":"","d":"<p>When the great grodair dies, his body explodes in a blast of pressurized water that deals 6d6 bludgeoning damage to creatures within a 15-foot emanation (DC 25 basic Reflex save). A creature that fails its save is pushed 5 feet (or 10 feet on a critical failure).</p>"},{"n":"Muddy Field","a":"1","c":"offensive","t":["primal","water"],"f":"","d":"<p>The great grodair transforms all soil, sand, or similar sediment in a 10-foot emanation into mud for 1 round. This mud is difficult terrain for creatures other than grodairs.</p>"},{"n":"Organ of Endless Water","a":"1","c":"offensive","t":["manipulate","primal","water"],"f":"","d":"<p>The great grodair causes water to pour from a magical sac on his spine, either a stream of water at a rate of 1 gallon per round, or a fountain in a 5-foot-long stream at a rate of 5 gallons per round. He can stop the flow of water as a single action.</p>"},{"n":"Knockdown","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Knockdown in its damage entry</p><hr><p><strong>Effect</strong> The monster attempts to Trip the creature. This attempt neither applies nor counts toward the monster's multiple attack penalty.</p></p>"},{"n":"Push 10 feet","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Push in its damage entry</p><hr><p><strong>Effect</strong> The monster attempts to Shove the creature. This attempt neither applies nor counts toward the monster's multiple attack penalty. If Push lists a distance, change the distance the creature is pushed on a success to that distance.</p></p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/grippli-jinxer":{"lang":["Common","Tripkee"],"gear":["Dart (8)","Staff"],"flavor":"<p>Baneback gripplis with innate magical ability may find themselves drawn to vile magic dealing with poison, vermin, and ill luck. Those who revel in the dreadful legends surrounding their kind often worship evil gods or demons associated with poison, tattooing themselves with mystic symbols to gain powerful control over toxins.</p>\n<hr>\n<p>Gripplis are small, frog-like humanoids native to tropical rainforests. Most gripplis live in tight-knit treetop villages and survive primarily as hunters and gatherers. While most communities are peaceful and harmonious, a lingering superstition has led to a unique group of these people being cut off from their communal bonds and forced to make their own way in the world.</p>\n<p>Among the many gripplis who possess poison glands, a rare subset secrete mind-altering chemicals. These gripplis aren't immune to this toxin, and over many years it may render them erratic at best and selfishly misanthropic at worst. Other gripplis view these \"banebacks\" as cursed and react to their presence with fear and mistrust, which usually leads to their censure and exile. They soon find that their natural skills as hunters, combined with an unlimited supply of their potent toxin, make them ideally suited to taking on work as mercenaries, bandits, or assassins.</p>","abilities":[{"n":"Hypnotic Tattoos","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A hostile creature targets the jinxer with a melee Strike</p>\n<hr>\n<p><strong>Effect</strong> Tattoos on the jinxer's body swirl and shift in mesmerizing patterns. The creature must attempt a DC 22 Will save.</p>\n<hr>\n<p><strong>Critical Success</strong> The creature is unaffected and is temporarily immune for 1 hour.</p>\n<p><strong>Success</strong> The creature is unaffected and is temporarily immune for 1 minute.</p>\n<p><strong>Failure</strong> The creature treats the jinxer as Concealed until the end of its turn.</p>\n<p><strong>Critical Failure</strong> The creature treats the jinxer as Hidden until the end of its turn.</p>"},{"n":"Baneback Poison","a":null,"c":"offensive","t":["poison"],"f":"","d":"<p><strong>Saving Throw</strong> DC 24 Fortitude</p>\n<p><strong>Maximum Duration</strong> 6 rounds</p>\n<p><strong>Stage 1</strong> 2d4 poison damage and Stupefied 1 (1 round)</p>\n<p><strong>Stage 2</strong> 3d4 poison damage and Stupefied 2 (1 round)</p>\n<p><strong>Stage 3</strong> 4d4 poison damage, Stupefied 3, and Off-Guard (1 round)</p>"},{"n":"Curse of Baneful Venom","a":"3","c":"offensive","t":["occult"],"f":"","d":"<p>The jinxer magically intensifies toxins in their foes. Creatures within 30 feet of the jinxer that are currently afflicted by a poison immediately attempt their next saving throw against the poison with a -2 status penalty, then are temporarily immune to Curse of Baleful Venom for 1 hour.</p>\n<p>Effect: Curse of the Baneful Venom</p>"},{"n":"Jungle Stride","a":null,"c":"offensive","t":[],"f":"","d":"<p>Gripplis ignore difficult terrain in forests and jungles.</p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/grippli-skirmisher":{"lang":["Common","Tripkee"],"gear":["Composite Shortbow","Kukri","Leather Armor","Thieves' Tools","Arrows (30)"],"flavor":"<p>Skirmishers are jittery baneback hunters or ambushers. Although they often fight in groups, they aren't loyal to each other and sometimes leave one member of the group behind to face punishment while the others flee.</p>\n<hr>\n<p>Gripplis are small, frog-like humanoids native to tropical rainforests. Most gripplis live in tight-knit treetop villages and survive primarily as hunters and gatherers. While most communities are peaceful and harmonious, a lingering superstition has led to a unique group of these people being cut off from their communal bonds and forced to make their own way in the world.</p>\n<p>Among the many gripplis who possess poison glands, a rare subset secrete mind-altering chemicals. These gripplis aren't immune to this toxin, and over many years it may render them erratic at best and selfishly misanthropic at worst. Other gripplis view these \"banebacks\" as cursed and react to their presence with fear and mistrust, which usually leads to their censure and exile. They soon find that their natural skills as hunters, combined with an unlimited supply of their potent toxin, make them ideally suited to taking on work as mercenaries, bandits, or assassins.</p>","abilities":[{"n":"Springing Step","a":null,"c":"interaction","t":[],"f":"","d":"<p>When the skirmisher uses the Step action they ignore difficult terrain and may move up to 10 feet instead of 5 feet.</p>"},{"n":"Hopping Dodge","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature misses the skirmisher with a melee Strike</p>\n<hr>\n<p><strong>Effect</strong> The skirmisher quickly takes advantage of the attacker's error and Steps.</p>"},{"n":"Baneback Poison","a":null,"c":"offensive","t":["poison"],"f":"","d":"<p><strong>Saving Throw</strong> DC 21 Fortitude</p>\n<p><strong>Maximum Duration</strong> 6 rounds</p>\n<p><strong>Stage 1</strong> 1d4 poison damage and Stupefied 1 (1 round)</p>\n<p><strong>Stage 2</strong> 2d4 poison damage and Stupefied 2 (1 round)</p>\n<p><strong>Stage 3</strong> 2d4 poison damage, Stupefied 3, and Off-Guard (1 round)</p>"},{"n":"Jungle Stride","a":null,"c":"offensive","t":[],"f":"","d":"<p>Gripplis ignore difficult terrain in forests and jungles.</p>"},{"n":"Wily Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>The skirmisher deals an extra 1d6 precision damage to Off-Guard creatures and creatures afflicted by a poison.</p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/grouloop":{"lang":["Boggard"],"gear":["Sickle","Leather Armor","Bag of Dead Dragonflies"],"notes":{"speed":"swamp stride"},"abilities":[{"n":"Soul-Shaking Croak","a":"2","c":"offensive","t":["sonic"],"f":"","d":"<p>Grouloop utters a powerful croak that deals 6d10 sonic damage to any non-boggard within a 30-foot emanation (DC 27 basic Fortitude save).</p>\n<p>A creature with the Frightened condition that fails its saving throw increases its frightened condition by 1 (on a critical failure, the creature is also Fleeing for as long as it is frightened).</p>\n<p>Grouloop can't use Soul-Shaking Croak again for 1d4 rounds.</p>"},{"n":"Swamp Stride","a":null,"c":"offensive","t":[],"f":"","d":"<p>Grouloop ignores difficult terrain caused by swamp terrain features.</p>"},{"n":"Tongue Grab","a":null,"c":"offensive","t":[],"f":"","d":"<p>If Grouloop hits a creature with her tongue, that creature becomes Grabbed. Unlike with a normal grab, the creature isn't Immobilized, but it can't move beyond the reach of Grouloop's tongue.</p>\n<p>A creature can sever the tongue by hitting AC 24 and dealing at least 9 slashing damage. Though this doesn't deal any damage to the boggard, it prevents her from using her tongue Strike until she regrows her tongue, which takes a week.</p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/halbrux-far-sight":{"lang":["Common","Cyclops","Jotun"],"lore":[["Fortune-Telling Lore",22],["Ghol-Gan Lore",24]],"gear":["Greatclub","Manacles (Average) (4)"],"focus":"3","abilities":[{"n":"Flash of History","a":"f","c":"defensive","t":["fortune","occult"],"f":"3 times per day","d":"<p><strong>Frequency</strong> three times per day</p>\n<p><strong>Trigger</strong> Halbrux is about to attempt a skill check</p>\n<hr>\n<p><strong>Effect</strong> Halbrux peers into lore of the past and increases the level of success by one step (for example, a success becomes a critical success).</p>"},{"n":"Resolve","a":null,"c":"defensive","t":[],"f":"","d":"<p>When Halbrux rolls a success on a Will save, she gets a critical success instead.</p>"},{"n":"Curse of Torrential Knowledge","a":null,"c":"offensive","t":[],"f":"","d":"<p>When halbrux uses her revelation spells, her mind fills with a flood of disorienting information.</p>\n<p>The first time Halbrux casts one of her revelation spells in a day, she takes a -4 penalty to initiative rolls until the next time she makes her daily preparations.</p>\n<p>The second time Halbrux casts one of her revelation spells in a day, she is also Off-Guard until the next time she makes her daily preparations.</p>"},{"n":"Predictive Blows","a":"f","c":"offensive","t":["concentrate","occult","visual"],"f":"","d":"<p><strong>Trigger</strong> Halbrux's turn begins</p>\n<hr>\n<p><strong>Effect</strong> Halbrux identifies the immediate movements of a creature she can see and attempts a Fortune-Telling Lore check against that creature's Reflex DC.</p>\n<p>On a success, Halbrux's melee Strikes deal an additional 4d6 precision damage (6d6 precision damage on a critical success) to the creature until the end of Halbrux's turn.</p>"},{"n":"Quickened Casting","a":"f","c":"offensive","t":[],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p>\n<hr>\n<p><strong>Effect</strong> If Halbrux's next action is to cast a cantrip or a 4th-rank or lower spell, reduce the number of actions to cast it by 1 (minimum of 1 action).</p>"},{"n":"Steady Spellcasting","a":null,"c":"offensive","t":[],"f":"","d":"<p>If a reaction would disrupt Halbrux's spellcasting action, she attempts a DC 15 Flat check. On a success, the action isn't disrupted.</p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/hivebound-arboreal":{"lang":["Arboreal","Common","Fey","speak with plants"],"notes":{"speed":"Freedom of Movement"},"abilities":[{"n":"Tremorsense 120 feet","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>Tremorsense allows a monster to feel the vibrations through a solid surface caused by movement. It is an imprecise sense with a limited range (listed in the ability). Tremorsense functions only if the monster is on the same surface as the subject, and only if the subject is moving along (or burrowing through) the surface.</p></p>"},{"n":"Constant Spells","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>A constant spell affects the monster without the monster needing to cast it, and its duration is unlimited. If a constant spell gets counteracted, the monster can reactivate it by spending the normal spellcasting actions the spell requires.</p></p>"},{"n":"Axe Vulnerability","a":null,"c":"defensive","t":[],"f":"","d":"<p>The hivebound arboreal takes 15 additional from axes.</p>"},{"n":"Swarm Host","a":null,"c":"defensive","t":["aura","primal"],"f":"","d":"<p>20 feet. The hivebound arboreal is host to a cloud of flying ants that swarm around it and gnaw at any creature within the aura. Non-arboreal creatures that enter the aura or start their turn within it take 7d8 piercing damage from the bites (DC 38 basic Fortitude). If the hivebound arboreal fails a saving throw against an area effect, the biting ants die off, and the aura is deactivated until new ants swarm out at the end of the hivebound arboreal's next turn (or after 1 minute, if the hivebound arboreal critically fails it saving throw).</p>"},{"n":"Constrict","a":"1","c":"offensive","t":[],"f":"","d":"<p>4d6+16 bludgeoning damage, DC 41 basic Fortitude</p>\n<hr>\n<p><p>The monster deals the listed amount of damage to any number of creatures Grabbed or Restrained by it. Each of those creatures can attempt a basic Fortitude save with the listed DC.</p></p>"},{"n":"Offered to the Swarm","a":"f","c":"offensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The arboreal Grabs or Constricts a foe</p>\n<p><strong>Requirements</strong> The hivebound arboreal's swarm host is active</p><hr><p><strong>Effect</strong> The arboreal offers up the triggering creature to its ants to feed. The triggering creature takes damage as from the swarm host aura, but thereafter gains a +4 circumstance bonus to Escape the Grab until it Escapes.</p>"},{"n":"Throw Rock","a":"1","c":"offensive","t":[],"f":"","d":"<p><p>The monster picks up a rock within reach or retrieves a stowed rock and throws it, making a ranged Strike.</p></p>"},{"n":"Improved Grab","a":"f","c":"offensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> The monster's last action was a successful Strike that lists Improved Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with as a free action. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Improved Grab as an action and choose one creature it's grabbing or restraining with an appendage that has Improved Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/iiko-dragon":{"lang":["Common","Draconic"],"flavor":"<p>I'iko dragons are greedy bullies with long muscular bodies, stubby legs, small wings, and shimmering glass-like scales. From their treetop nests overhanging well-traveled rivers, i'iko dragons land on passing watercrafts and extort the passengers, threatening to capsize boats if not paid with bright treasure. When faced with a well-armed group guarding their desired trinkets, they instead resort to stealth, stealing them under cover of darkness, using their claws to pick locks and disable traps as needed.</p>\n<p>I'iko dragons reside in the jungles of the Mwangi Expanse, particularly in Nantambu where they live under the tall arching bridges that cross the city's many canals, building roosts in the bridge supports. I'iko dragons eat fish and birds, and have a taste for glass, crystals, and gemstones, which they consume to harden and color their scales. Incredibly vain, i'iko dragons collect the most colorful glass they can find to transform their scales into a resplendent rainbow.</p>","abilities":[{"n":"Breath Weapon","a":"1","c":"offensive","t":["arcane"],"f":"","d":"<p>The i'iko dragon breathes a spray of jagged glass shards that deals 7d6 piercing damage in a 15-foot cone (DC 24 basic Reflex save). They can't use Breath Weapon again for 1d4 rounds.</p>"},{"n":"Cunning Capsize","a":"1","c":"offensive","t":["attack"],"f":"","d":"<p>The i'iko dragon attempts to capsize an aquatic vessel of Medium size or smaller that they're on or adjacent to. They must succeed at an DC 25 Athletics check with a DC of 25 or the pilot's Sailing Lore DC, whichever is higher.</p>"},{"n":"Draconic Grandeur","a":"1","c":"offensive","t":["emotion","fear","mental"],"f":"","d":"<p>The i'iko dragon spreads their wings, bares their teeth, and threatens their opponent in a terrifying display of draconic majesty. All creatures within 30 feet must attempt a DC 24 Will save. Regardless of the result of the saving throw, the creatures are temporarily immune to Draconic Grandeur for 1 minute.</p>\n<hr>\n<p><strong>Critical Success</strong> The creature is unaffected.</p>\n<p><strong>Success</strong> The creature is Frightened 1.</p>\n<p><strong>Failure</strong> The creature is Frightened 2.</p>\n<p><strong>Critical Failure</strong> The creature is Frightened 4.</p>"},{"n":"Tackle","a":"2","c":"offensive","t":["move"],"f":"","d":"<p>The i'iko dragon Flies up to their fly Speed, descending at least 10 feet, and then makes a jaws Strike. If the jaws Strike hits and the target is Medium or smaller, the target is knocked Prone.</p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/ikeshti-brood-minder":{"lang":["Akitonian","Ikeshti"],"flavor":"<p>Ikeshti young are near-mindless carnivores. They are watched over by brood-minders, male ikeshtis with a talent for influencing the ravenous spawn, who protect the tiny creatures until they grow into responsible adults.</p>\n<hr>\n<p>Ikeshtis are reptilian humanoids native to Akiton's wastelands. Smaller than Golarion's iruxi, ikeshtis organize around distinct societal roles.</p>","abilities":[{"n":"Squirt Blood","a":"1","c":"offensive","t":[],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p>\n<hr>\n<p><strong>Effect</strong> The ikeshti squirts blood from one of their eyes at a target within 30 feet. The target must attempt a DC 18 Fortitude save or become Sickened 1 (Sickened 2 on a critical failure).</p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/iobane-magus":{"lang":["Common","Draconic"],"gear":["Spear","Black Dragonhide Buckler (High-Grade)","Chain Shirt","Signal Horn"],"notes":{"per":"iobane vision"},"focus":2,"abilities":[{"n":"Attack of Opportunity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Shield Block","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> The monster has its shield raised and takes damage from a physical attack.</p>\n<hr>\n<p><strong>Effect</strong> The monster snaps its shield into place to deflect a blow. The shield prevents the monster from taking an amount of damage up to the shield's Hardness. The monster and the shield each take any remaining damage, possibly breaking or destroying the shield.</p></p>"},{"n":"Iobane Vision","a":null,"c":"offensive","t":["fortune"],"f":"","d":"<p>The Iobane magus can see Invisible creatures and objects as though they are Concealed.</p>\n<p>When they Seek or Sense Motive, they can roll twice and take the higher result.</p>"},{"n":"Spear Dance","a":"2","c":"offensive","t":[],"f":"","d":"<p>The Iobane magus makes three spear Strikes, each with a range of 10 feet.</p>"},{"n":"Spellstrike","a":"2","c":"offensive","t":[],"f":"","d":"<p><strong>Frequency</strong> Until recharged</p>\n<hr>\n<p><strong>Effect</strong> The Iobane magus Casts a Spell that takes 1 or 2 actions to cast and requires a spell attack roll. The effects of the spell do not occur immediately but are imbued into the attack instead. The Iobane magus makes a melee Strike. The spell is coupled with the attack, using the attack roll result to determine the effects of both the Strike and the spell.</p>\n<p>This counts as two attacks for the Iobane magus' multiple attack penalty, but don't apply the penalty until after they have completed the Spellstrike.</p>\n<p>After the Iobane magus uses Spellstrike, they can't do so again until they recharges their Spellstrike as a single action, which has the concentrate trait. The Iobane magus also recharges their Spellstrike when they casts a conflux spell.</p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/ironclad-annihilator-beetle":{"abilities":[{"n":"Carapace Deflection","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The ironclad annihilator beetle is targeted with an attack from an attacker it can see</p>\n<hr>\n<p><strong>Effect</strong> The ironclad annihilator pivots to place its tough carapace in the way of the attack, gaining a +2 circumstance bonus to its AC against the triggering attack. If the attack misses, the ironclad annihilator can Step after the attack.</p>"},{"n":"Constrict","a":"1","c":"offensive","t":[],"f":"","d":"<p>4d6+20 bludgeoning damage, DC 44 basic Fortitude</p>\n<hr>\n<p><p>The monster deals the listed amount of damage to any number of creatures Grabbed or Restrained by it. Each of those creatures can attempt a basic Fortitude save with the listed DC.</p></p>"},{"n":"Earthquake Stomp","a":"1","c":"offensive","t":[],"f":"once per round","d":"<p><strong>Frequency</strong> once per round</p>\n<hr>\n<p><strong>Effect</strong> The ironclad annihilator beetle stomps the ground. All creatures within a 30-foot emanation must succeed at a DC 44 Fortitude saving throw or fall Prone and become Stunned 1 (stunned for 1 round on a critical failure).</p>"},{"n":"Oviposit","a":"2","c":"offensive","t":[],"f":"","d":"<p><strong>Requirements</strong> The ironclad annihilator beetle has a creature Grabbed</p><hr><p><strong>Effect</strong> The ironclad annihilator injects its ovipositor under the grabbed creature's skin. The creature takes 4d6+20 bludgeoning damage (DC 44 basic Fortitude). On a failed save, the beetle implants an egg, and the target creature takes 4d6 bleed that is unusually tenacious. The DC to stop the bleeding using Administer First Aid is DC 40 Medicine, and healing the creature to full Hit Points doesn't automatically stop the bleeding. If the target creature dies from this bleed damage, its body is destroyed and unrecoverable except with powerful magic such as Miracle or Wish, and an immature ironclad annihilator beetle (with statistics as a Giant Stag Beetle) bursts forth.</p>"},{"n":"Sunder Objects","a":null,"c":"offensive","t":[],"f":"","d":"<p>When an ironclad annihilator damages an item or structure, it deals an additional 2d10 damage to that item or structure.</p>"},{"n":"Trample","a":"3","c":"offensive","t":[],"f":"","d":"<p>Huge or smaller, foot, DC 44 basic Reflex save</p>\n<p><p>The monster Strides up to double its Speed and can move through the spaces of creatures of the listed size, Trampling each creature whose space it enters. The monster can attempt to Trample the same creature only once in a single use of Trample. The monster deals the damage of the listed Strike, but trampled creatures can attempt a basic Reflex save at the listed DC (no damage on a critical success, half damage on a success, double damage on a critical failure).</p></p>"},{"n":"Improved Grab","a":"f","c":"offensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> The monster's last action was a successful Strike that lists Improved Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with as a free action. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Improved Grab as an action and choose one creature it's grabbing or restraining with an appendage that has Improved Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/ixamè":{"lang":["Common","Draconic","Sussuran"],"notes":{"hp":"void healing","per":"mist vision","speed":"cloud walk"},"abilities":[{"n":"Deflecting Cloud","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> Ixamè is the target of a ranged attack</p>\n<p><strong>Requirements</strong> Ixamè is aware of the attack and has a free wing</p>\n<hr>\n<p><strong>Effect</strong> Ixamè rapidly flexes one of her wings and creates a billowing cloud of mist. She is treated as if she were Hidden for the purposes of resolving the triggering attack, so normally the attacker must succeed at a DC 11 Flat to target her.</p>\n<p>Ixamè also gains a +4 circumstance bonus to AC against the triggering attack.</p>"},{"n":"Frightful Presence","a":null,"c":"defensive","t":["aura","emotion","fear","mental"],"f":"","d":"<p>90 feet. DC 26 Will</p>\n<hr>\n<p><p>A creature that first enters the area must attempt a Will save.</p>\n<p>Regardless of the result of the saving throw, the creature is temporarily immune to this monster's Frightful Presence for 1 minute.</p>\n<hr>\n<p><strong>Critical Success</strong> The creature is unaffected by the presence.</p>\n<p><strong>Success</strong> The creature is Frightened 1.</p>\n<p><strong>Failure</strong> The creature is Frightened 2.</p>\n<p><strong>Critical Failure</strong> The creature is Frightened 4.</p></p>"},{"n":"Mist Vision","a":null,"c":"defensive","t":[],"f":"","d":"<p>Fog and mist don't impair a cloud dragon's vision; Ixamè ignores the Concealed condition from fog and mist.</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Breath Weapon","a":"2","c":"offensive","t":["poison","primal"],"f":"","d":"<p>Ixamè breathes a cloud of poison like that emitted from Terwa Lake that deals 11d6 poison damage in a 40-foot cone (DC 29 basic Reflex save).</p>\n<p>She can't use Breath Weapon again for 1d4 rounds.</p>"},{"n":"Cloud Walk","a":null,"c":"offensive","t":[],"f":"","d":"<p>Ixamè can tread on clouds or fog as though on solid ground.</p>"},{"n":"Draconic Frenzy","a":"2","c":"offensive","t":[],"f":"","d":"<p>Ixamè makes two claw Strikes and one horn Strike in any order.</p>"},{"n":"Draconic Momentum","a":null,"c":"offensive","t":[],"f":"","d":"<p>Ixamè recharges her Breath Weapon whenever she scores a critical hit when making a Strike.</p>"}]},"strength-of-thousands-bestiary/book-4-secrets-of-the-temple-city/jackal-guard":{"lang":["Common","Mzunu"],"gear":["Spear","Sturdy Shield (Lesser)","Chain Shirt","Religious Symbol of Walkena"],"abilities":[{"n":"Attack of Opportunity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Shield Block","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> The monster has its shield raised and takes damage from a physical attack.</p>\n<hr>\n<p><strong>Effect</strong> The monster snaps its shield into place to deflect a blow. The shield prevents the monster from taking an amount of damage up to the shield's Hardness. The monster and the shield each take any remaining damage, possibly breaking or destroying the shield.</p></p>"},{"n":"Impaling Strike","a":"2","c":"offensive","t":[],"f":"once per round","d":"<p><strong>Frequency</strong> once per round</p><hr>\n<p><strong>Effect</strong> The Jackal Guard lunges forward with their spear and delivers a piercing blow. The Jackal Guard Steps and then makes a melee spear Strike. On a hit, the target also takes 1d6 bleed.</p>"},{"n":"Knocking Sweep","a":"2","c":"offensive","t":[],"f":"once per round","d":"<p><strong>Frequency</strong> once per round</p><hr>\n<p><strong>Effect</strong> The Jackal Guard swings their weapon with a sweeping spin. They attempt separate Athletics checks to Trip any number of creatures within their reach. Each attempt counts toward the Jackal Guard's multiple attack penalty, but the multiple attack penalty doesn't increase until after they make all the attacks.</p>"},{"n":"Spear Vault","a":"2","c":"offensive","t":[],"f":"once per round","d":"<p><strong>Frequency</strong> once per round</p><hr>\n<p><strong>Effect</strong> The Jackal Guard uses their spear to jump over or around a creature and create an opening. The Jackal Guard Strides up to half their Speed. This movement doesn't trigger reactions. During this movement, they can move through the space of one creature, and when the Jackal Guard moves through a creature's space in this way, that creature becomes Off-Guard until the end of the Jackal Guard's turn. If the Jackal Guard ends their movement within melee reach of at least one enemy, they can make a melee Strike against that enemy.</p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/karumzek":{"lang":["Chthonian","Common","Diabolic","Sakvroth"],"notes":{"per":"poison sense (precise) 30 feet"},"abilities":[{"n":"Constant Spells","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>A constant spell affects the monster without the monster needing to cast it, and its duration is unlimited. If a constant spell gets counteracted, the monster can reactivate it by spending the normal spellcasting actions the spell requires.</p></p>"},{"n":"Poison Sense (precise) 30 feet","a":null,"c":"defensive","t":[],"f":"","d":"<p>A karumzek senses any poisoned creature. It can spend an action with the concentrate trait to determine the poison's type and current stage.</p>"},{"n":"Change Shape","a":null,"c":"offensive","t":["arcane","concentrate","polymorph"],"f":"","d":"<p>A karumzek can take the shape of a Tiny spider. This doesn't change its Speed or Strikes.</p>"},{"n":"Karumzek Venom","a":null,"c":"offensive","t":["poison","virulent"],"f":"","d":"<p><strong>Saving Throw</strong> DC 19 Fortitude</p>\n<p><strong>Maximum Duration</strong> 6 rounds</p>\n<p><strong>Stage 1</strong> 1d6 poison (1 round)</p>\n<p><strong>Stage 2</strong> 1d6 poison and Enfeebled 1 (1 round)</p>\n<p><strong>Stage 3</strong> 2d6 poison, Clumsy 1, and enfeebled 1 (1 round)</p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/karumzek-swarm":{"notes":{"per":"poison sense (precise) 30 feet"},"abilities":[{"n":"Poison Sense (precise) 30 feet","a":null,"c":"defensive","t":[],"f":"","d":"<p>A karumzek senses any poisoned creature. It can spend an action with the concentrate trait to determine the poison's type and current stage.</p>"},{"n":"Karumzek Venom","a":null,"c":"offensive","t":["poison","virulent"],"f":"","d":"<p><strong>Saving Throw</strong> DC 28 Fortitude</p>\n<p><strong>Maximum Duration</strong> 6 rounds</p>\n<p><strong>Stage 1</strong> 4d6 poison and Enfeebled 1 (1 round)</p>\n<p><strong>Stage 2</strong> 5d6 poison, Clumsy 1, and Enfeebled 2 (1 round)</p>\n<p><strong>Stage 3</strong> 6d6 poison, Clumsy 2, and enfeebled 2 (1 round)</p>"},{"n":"Swarming Bites","a":"1","c":"offensive","t":[],"f":"","d":"<p>Each enemy in the karumzek swarm's space takes 2d6 piercing damage (DC 27 basic Reflex save) plus karumzek venom.</p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/khefak-scuttler":{"flavor":"<p>These small creatures are ubiquitous vermin found across much of Akiton.</p>\n<hr>\n<p>This unusual arthropod resembles an amalgam of a centipede and a crab. Hard-shelled and perfectly suited to life on Akiton, khefaks are so incredibly useful that a visitor to the planet might assume they were custom engineered for their environs. Such visitors would, in fact, be correct. While khefaks can be found naturally on Akiton, a new species has recently gained a foothold on the planet: alchemically engineered khefaks who excrete a refined substance that can be used as fuel to power advanced engines and devices.</p>","abilities":[{"n":"Tremorsense (Imprecise) 60 feet","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>Tremorsense allows a monster to feel the vibrations through a solid surface caused by movement. It is an imprecise sense with a limited range (listed in the ability). Tremorsense functions only if the monster is on the same surface as the subject, and only if the subject is moving along (or burrowing through) the surface.</p></p>"},{"n":"Consume Objects","a":null,"c":"interaction","t":[],"f":"","d":"<p>A khefak can gain nourishment by eating objects with hardness 10 or lower. When attacking an object with its mandibles, it ignores the first 10 points of that object's Hardness.</p>"}]},"strength-of-thousands-bestiary/book-4-secrets-of-the-temple-city/kilia-mwibo":{"lang":["Fey","(can't speak any language)"],"notes":{"per":"emotion sense 60 feet"},"abilities":[{"n":"Attack of Opportunity (Frond Only)","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Despairing Presence","a":null,"c":"defensive","t":["aura","emotion","fear","incapacitation","mental","primal"],"f":"","d":"<p>60 feet. A creature that enters the emanation or starts its turn within it tumbles down a deep well of dread and must attempt a DC 33 Will save.</p>\n<p><strong>Critical Success</strong> The target is unaffected.</p>\n<p><strong>Success</strong> The target becomes Frightened 1.</p>\n<p><strong>Failure</strong> The target becomes Frightened 2.</p>\n<p><strong>Critical Failure</strong> The target becomes Frightened 3 and Immobilized until it's no longer frightened.</p>"},{"n":"Emotion Sense 60 feet","a":null,"c":"defensive","t":[],"f":"","d":"<p>A kilia mwibo can sense nearby negative emotions. This is a precise sense against creatures who are under powerful emotion effects like rage, those who are frightened, or, at the GM's discretion, those who are in the grips of hatred, sadness, or other overwhelming negative emotions. Against all other creatures that possess emotions, this is an imprecise sense. A creature that has no emotions is effectively Invisible to a kilia mwibo. A creature that knows about emotion sense can take precautions to Hide and Sneak from a kilia mwibo, in this case by suppressing feelings of negativity.</p>"},{"n":"Constrict","a":"1","c":"offensive","t":[],"f":"","d":"<p>2d12+15 bludgeoning, DC 36 basic Fortitude</p>\n<hr>\n<p><p>The monster deals the listed amount of damage to any number of creatures Grabbed or Restrained by it. Each of those creatures can attempt a basic Fortitude save with the listed DC.</p></p>"},{"n":"Consume Emotion","a":"2","c":"offensive","t":["divine","mental"],"f":"","d":"<p>The kilia mwibo feeds on the negative emotions of a creature within 60 feet; this must be a creature that it can precisely sense with its emotion sense. The target must succeed at a DC 36 Will save or increase its Drained condition value by 1 (by 2 on a critical failure), to a maximum of drained 4.</p>"},{"n":"Improved Grab","a":"f","c":"offensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> The monster's last action was a successful Strike that lists Improved Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with as a free action. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Improved Grab as an action and choose one creature it's grabbing or restraining with an appendage that has Improved Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/king-of-biting-ants":{"lang":["Akitonian","Aklo","Chthonian","Common","Diabolic"],"gear":["Wand of Manifold Missiles (7th-Rank Spell)"],"notes":{"ac":"all-around vision"},"abilities":[{"n":"Tremorsense (Imprecise) 30 feet","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>Tremorsense allows a monster to feel the vibrations through a solid surface caused by movement. It is an imprecise sense with a limited range (listed in the ability). Tremorsense functions only if the monster is on the same surface as the subject, and only if the subject is moving along (or burrowing through) the surface.</p></p>"},{"n":"All-Around Vision","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>This monster can see in all directions simultaneously and therefore can't be flanked.</p></p>"},{"n":"Swarm Mind","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>This monster doesn't have a single mind (typically because it's a swarm of smaller creatures), and is immune to mental effects that target only a specific number of creatures. It is still subject to mental effects that affect all creatures in an area.</p></p>"},{"n":"Counterspell","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature Casts a Spell the King of Biting Ants knows</p>\n<hr>\n<p><strong>Effect</strong> The King of Biting Ants expends a spell slot to counter the triggering creature's casting. The King of Biting Ants loses his spell slot as if he had cast the triggering spell. He then attempts to counteract the triggering spell.</p>"},{"n":"Discorporate","a":null,"c":"defensive","t":[],"f":"","d":"<p>When the King of Biting Ants is reduced to 0 HP, he discorporates, and the component ants that make up his body disperse in every direction. If even a single ant escapes, the King of Biting Ants will eventually re-form using a process that typically takes 1d10 days.</p>\n<p>Applying area damage immediately after the King of Biting Ants is killed prevents his return.</p>"},{"n":"Squirming Embrace","a":"1","c":"offensive","t":[],"f":"","d":"<p>The King of Biting Ants Strides to a creature, ends his movement sharing a space with it, and deals 3d8 piercing damage and 3d8 poison damage to it (DC 39 basic Reflex save).</p>\n<p>A creature that fails this save also takes 2d8 persistent piercing damage.</p>"},{"n":"Swarm Shape","a":"1","c":"offensive","t":["concentrate"],"f":"","d":"<p>The King of Biting Ants collapses into a shapeless swarm of ants. He drops all held, worn, and carried items.</p>\n<p>While discorporated, The King of Biting Ants can't use attack actions and can't cast spells, but he can move through areas small enough for his individual ants to fit without having to Squeeze. He can use the same action to coalesce back into his normal form.</p>"},{"n":"Swarming Bites","a":null,"c":"offensive","t":[],"f":"","d":"<p>While a creature is taking persistent piercing damage from the King of Biting Ants's tendril Strike or Squirming Embrace, or while within a Visions of Danger area that it has not disbelieved, it is also Clumsy 1.</p>\n<p>If the creature attempts a concentrate or manipulate action while affected, it must succeed at a DC 5 Flat or the action is lost; roll the check after spending the action, but before any effects are applied.</p>\n<p>Effect: Swarming Bites</p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/kiru":{"lang":["Common","Elven"],"lore":[["Underworld Lore",8]],"gear":["Dagger (6)","Studded Leather Armor","Thieves' Tools"],"abilities":[{"n":"Knife Jab","a":null,"c":"offensive","t":[],"f":"","d":"<p>Creatures hit by Kiru's dagger Strike must succeed at a DC 20 Fortitude save or become Clumsy 1 for 1 round (1 minute on a critical failure). If Kiru's Strike is a critical hit, the DC increases to DC 25 Fortitude.</p>"},{"n":"Sneak Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>Kiru deals an extra 1d6 precision damage to Off-Guard creatures.</p>"},{"n":"Surprise Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>On the first round of combat, creatures that haven't acted yet are Off-Guard to Kiru.</p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/kolbo":{"lang":["Common","Draconic","Dwarven","Jotun"],"gear":["Heavy Crossbow","Longsword","Leather Armor","Strongbox Key","Thieves' Tools","Elixir of Life (Lesser)","Bolts (10)"],"abilities":[{"n":"A Quick Word","a":null,"c":"interaction","t":[],"f":"","d":"<p>If Kolbo is aware of his opponents and isn't prevented from speaking, he rolls Deception for initiative.</p>"},{"n":"Deny Advantage","a":null,"c":"defensive","t":[],"f":"","d":"<p>Kolbo isn't Off-Guard to creatures of 6th level or lower that are Hidden, Undetected, flanking, or using surprise attack.</p>"},{"n":"Low Blow","a":"r","c":"offensive","t":[],"f":"","d":"<p><strong>Requirements</strong> Kolbo successfully Feints an opponent</p>\n<hr>\n<p><strong>Effect</strong> The foe is knocked Prone.</p>"},{"n":"Sneak Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>Kolbo deals an extra 2d6 precision damage to Off-Guard creatures.</p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/kreekoss":{"lang":["Common","Fey","Sussuran","(can't speak any language)"],"abilities":[{"n":"Evasion","a":null,"c":"defensive","t":[],"f":"","d":"<p>When Kreekoss rolls a success on a Reflex save, he gets a critical success instead.</p>"},{"n":"Eagle Dive","a":"1","c":"offensive","t":[],"f":"","d":"<p>Kreekoss Flies up to double his fly Speed in a straight line, descending at least 10 feet, and then makes a talon Strike.</p>"},{"n":"Snatch","a":null,"c":"offensive","t":[],"f":"","d":"<p>Kreekoss can Fly at half Speed while he has a creature Grabbed or Restrained in his talons, carrying that creature along with it.</p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/kurshkin":{"lang":["Common","Kholo","Sakvroth"],"gear":["Shortbow","Shortsword","Arrows (60)"],"notes":{"per":"+2 to hear things"},"abilities":[{"n":"+2 to Perception to hear things","a":null,"c":"defensive","t":[],"f":"","d":""},{"n":"Unluck Aura","a":null,"c":"defensive","t":["aura","mental","misfortune","primal"],"f":"","d":"<p>20 feet. Creatures other than animals, gremlins, and gnolls in the aura become extremely unlucky (DC 20 Will save; creature must roll this Will save twice and take the worse result). On a successful save, the creature is temporarily immune to pugwampi unluck auras for 24 hours. On a failure, the creature must roll twice and take the worse result on all checks as long as it is within the aura.</p>\n<p>Effect: Unluck Aura</p>"},{"n":"Collateral Damage","a":"r","c":"offensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A Strike critically misses Kurshkin</p>\n<hr>\n<p><strong>Effect</strong> Kurshkin redirects the strike to an adjacent creature. The attacker rerolls the Strike against that creature.</p>"},{"n":"Lucky Stabs","a":null,"c":"offensive","t":[],"f":"","d":"<p>Kurshkin deals an additional 1d6 damage with her melee Strikes against creatures affected by her unluck aura.</p>"},{"n":"Natural Thief","a":null,"c":"offensive","t":[],"f":"","d":"<p>When attacking with a finesse melee weapon, Kurshkin adds her Dexterity modifier to damage rolls instead of her Strength modifier.</p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/lignified-adamantine-golem":{"notes":{"hp":"repair mode"},"abilities":[{"n":"Golem Antimagic","a":null,"c":"defensive","t":[],"f":"","d":"<p>Harmed by acid (9d10 untyped, 2d10 untyped from areas or persistent damage); healed by plant (area 2d10 healing HP); slowed by electricity</p><hr><p><p>A golem is immune to spells and magical abilities other than its own, but each type of golem is affected by a few types of magic in special ways. These exceptions are listed in shortened form in the golem's stat block, with the full rules appearing here. If an entry lists multiple types (such as \"cold and water\"), either type of spell can affect the golem.</p><ul><li><strong>Harmed By</strong> Any magic of this type that targets the golem causes it to take the listed amount of damage (this damage has no type) instead of the usual effect. If the golem starts its turn in an area of magic of this type or is affected by a persistent effect of the appropriate type, it takes the damage listed in the parenthetical.</li><li><strong>Healed By</strong> Any magic of this type that targets the golem makes the golem lose the slowed condition and gain HP equal to half the damage the spell would have dealt. If the golem starts its turn in an area of this type of magic, it gains the HP listed in the parenthetical.</li><li><strong>Slowed By</strong> Any magic of this type that targets the golem causes it to be Slowed 1 for 2d6 rounds instead of the usual effect. If the golem starts its turn in an area of this type of magic, it's slowed 1 for that round.</li><li><strong>Vulnerable To</strong> Each golem is vulnerable to one or more specific spells, with the effects described in its stat block.</li></ul></p>"},{"n":"Repair Mode","a":null,"c":"defensive","t":[],"f":"","d":"<p>When the golem is at 0 HP, it isn't destroyed. Instead, it enters repair mode, during which it is Slowed 1, can't take reactions, and can take only the Self-Repair action. Once it has more than 30 HP, it can use any type of action and can use reactions, though it remains slowed 1 and can't take any reactions until the start of its next turn. If a critical hit with an adamantine weapon reduces the golem to 0 HP, or if such a weapon hits it while it's already at 0 HP, then the golem is destroyed.</p>"},{"n":"Vulnerable to Dispelling and Shape Wood","a":null,"c":"defensive","t":[],"f":"","d":"<p>The golem can be targeted by Disjunction, Dispel Magic, and Shape Wood. If targeted by such a spell of 9th rank or higher, the golem has its resistance to physical damage lowered to 10 and is Slowed 1 (or Slowed 2 if in repair mode) for 1d4 rounds. During this time, if the golem is reduced to 0 HP while already in repair mode, it is destroyed.</p>"},{"n":"Destructive Strike","a":null,"c":"offensive","t":[],"f":"","d":"<p>On a critical hit, the golem's staff Strike breaks the target's armor, if any, in addition to dealing damage to the target. If the target has a shield raised, the golem breaks the shield instead.</p>"},{"n":"Inexorable March","a":"1","c":"offensive","t":[],"f":"","d":"<p>The golem Strides up to its Speed, pushing back each creature whose space it moves into and damaging them if they try to stop its movement. A creature can try to bar the way by attempting a DC 43 Fortitude save.</p>\n<hr>\n<p><strong>Critical Success</strong> The creature takes no damage and its armor takes no damage.</p>\n<p><strong>Success</strong> The golem halts its movement and cannot enter the creature's square.</p>\n<p><strong>Failure</strong> The resisting creature is damaged and its armor takes damage as if hit by the golem's staff.</p>"},{"n":"Self-Repair","a":"1","c":"offensive","t":["manipulate"],"f":"","d":"<p>The golem repairs itself, regaining 30 healing Hit Points.</p>"},{"n":"Vent Splinters","a":"1","c":"offensive","t":["arcane","fire"],"f":"","d":"<p>The golem vents a 30-foot cone of fiery splinters from its internal forge. This deals 13d6 piercing damage to all creatures in the cone (DC 38 basic Reflex). Creatures who fail the save also take 2d6 persistent fire damage (4d6 persistent fire damage on a critical failure). The golem can't use Vent Splinters again for 1d4 rounds.</p>"}]},"strength-of-thousands-bestiary/book-4-secrets-of-the-temple-city/living-sun-spire":{"abilities":[{"n":"Attack of Opportunity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Construct Armor (Hardness 14)","a":null,"c":"defensive","t":[],"f":"","d":"<p>Like normal objects, the Living Sun-Spire has Hardness. This Hardness reduces any damage it takes by an amount equal to the Hardness.</p>\n<p>Once the statue is reduced to less than half its Hit Points, or immediately upon being damaged by a critical hit, its construct armor breaks and its Armor Class is reduced to 32.</p>"},{"n":"Steal the Sun","a":"r","c":"defensive","t":["divine"],"f":"","d":"<p><strong>Trigger</strong> A creature within 30 feet of the sun-spire begins to Cast a Spell that has the fire or light trait</p><hr>\n<p><strong>Effect</strong> The sun-spire attempts to redirect the energy from the triggering effect into its sunlight stores. The sun-spire attempts to counteract the triggering spell with a +22 counteract bonus. If it successfully counteracts the spell, the sun-spire's sunlight stores are empowered. While empowered, the sun-spire deals an additional 2d8 fire damage with all of its attacks and abilities. The sun-spire remains empowered until the end of its next turn.</p>"},{"n":"Beam of the Seven Suns","a":"2","c":"offensive","t":["divine","fire"],"f":"","d":"<p>The sun-spire collects solar energy and uses the energy to create a deadly beam of fire. It fires the beam in a 120-foot line, dealing 11d8 fire damage to all creatures in the line (DC 33 basic Reflex save). The concentrated beam ignites everything in its path, including the air, creating a wall of burning flame along the line that continues to burn until the end of the sun-spire's next turn. This wall has the effects of a 5th-rank Wall of Fire spell, dealing 5d6 fire damage to any creature that crosses the wall or occupies the wall's area at the start of its turn. The sun-spire can't use the Beam of the Seven Suns again for 1d4 rounds, although rounds it's not in sunlight don't count toward this number.</p>"},{"n":"Trample","a":"3","c":"offensive","t":[],"f":"","d":"<p>Large or smaller, arm, DC 33 basic Reflex</p>\n<hr>\n<p><p>The monster Strides up to double its Speed and can move through the spaces of creatures of the listed size, Trampling each creature whose space it enters. The monster can attempt to Trample the same creature only once in a single use of Trample. The monster deals the damage of the listed Strike, but trampled creatures can attempt a basic Reflex save at the listed DC (no damage on a critical success, half damage on a success, double damage on a critical failure).</p></p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/loakan":{"lang":["Common","Draconic","Iruxi"],"lore":[["Cooking Lore",10]],"gear":["Greatclub","Recipe Books"],"abilities":[{"n":"Battering Tail","a":"2","c":"offensive","t":[],"f":"","d":"<p>Loakan makes a <em>greatclub</em> Strike and two tail Strikes against the same creature. If the <em>greatclub</em> Strike hits, the target is Off-Guard against both tail Strikes.</p>"},{"n":"Deep Breath","a":null,"c":"offensive","t":[],"f":"","d":"<p>Loakan can hold her breath for 200 rounds (20 minutes).</p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/mashkudu-the-bully":{"lang":["Common"],"gear":["Hand Crossbow","Longsword","Leather Armor","Thieves' Tools","Bolts (10)"],"abilities":[{"n":"Opportunistic Maneuver","a":"r","c":"offensive","t":[],"f":"","d":"<p><strong>Trigger</strong> Mashkudu Shoves, Trips, or Disarms a creature</p>\n<hr>\n<p><strong>Effect</strong> Mashkudu attempts a Thievery check to Steal an object the target carries.</p>"},{"n":"Sneak Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>Mashkudu deals an extra 1d6 precision damage to Off-Guard creatures.</p>"},{"n":"Surprise Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>On the first round of combat, creatures that haven't acted yet are Off-Guard to Mashkudu.</p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/mpeshi":{"flavor":"<p>In the heights of the world, where the hills and mountains reach up to touch the clouds, mpeshis fall to the earth in flashes of lightning and thunder. Most return to the heavens on the gossamer strands of web on which they descend, but those few that remain cry out, lamenting their inability to return to their homes in the sky.</p>\n<p>A mpeshi appears to be a monstrous goat with the foreclaws, hindquarters, and tail of a crocodile. Electricity arcs around its sharp horns, which it can use to both batter and gore with equal facility. Although mpeshis are always seeking methods to return to their homes in the clouds, they aggressively defend their earthbound lairs from outsiders.</p>\n<p>Mpeshis are generally solitary, though some congregate as pairs or small groups that watch cloud movements together. They can sometimes be seen trying to join reach the storm clouds, leaping from high places such as hills, mountains, or cliffs. Though these attempts are rarely successful, the mpeshis always resolve to try again-and some do manage succeed at returning to their mysterious homes amongst the clouds.</p>\n<p>Mpeshis are utterly unafraid of rocs, dragons, or other monstrous flying creatures, usually seeing them as competition. Mpeshis are crafty, though, and sometimes try to negotiate transportation back to the clouds from flying creatures larger than they are.</p>","abilities":[{"n":"Lightning Aura","a":null,"c":"defensive","t":["aura","electricity"],"f":"","d":"<p>5 feet. A buzzing static electricity surrounds the mpeshi. When a creature within the aura takes electricity damage, the damage arcs to a random adjacent creature, dealing 1d6 electricity damage. A creature can only receive arcing damage once from each attack or effect.</p>"},{"n":"Thunderous Fall","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The mpeshi falls at least 10 feet</p>\n<hr>\n<p><strong>Effect</strong> The mpeshi reorients itself to slam headfirst into the ground with a thundering crash. Creatures within 10 feet of the mpeshi take sonic damage equal to the bludgeoning damage the mpeshi took from the fall (DC 23 basic Fortitude save). Creatures that fail this save are Stunned 1 (Stunned 2 on a critical failure).</p>"},{"n":"Charging Leap","a":"2","c":"offensive","t":[],"f":"","d":"<p>The mpeshi leaps up to 40 feet in any direction, including straight up. The mpeshi makes a horn Strike at any point during this leap.</p>"},{"n":"Cloud Walk","a":null,"c":"offensive","t":[],"f":"","d":"<p>The mpeshi can tread on clouds or fog as though on solid ground.</p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/mpondo":{"lang":["Common","Draconic","Necril"],"gear":["Bastard Sword","Spear","Black Dragonhide Buckler (High-Grade)","Chain Shirt","Signal Horn"],"notes":{"per":"iobane vision"},"focus":2,"abilities":[{"n":"Attack of Opportunity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Iobane Vision","a":null,"c":"offensive","t":["fortune"],"f":"","d":"<p>Warder-Chief Mpondo can see Invisible creatures and objects as though they are Concealed.</p>\n<p>When he Seeks or Senses Motive, he can roll twice and take the higher result.</p>"},{"n":"Spellstrike","a":"2","c":"offensive","t":[],"f":"","d":"<p><strong>Frequency</strong> Until recharged</p>\n<hr>\n<p><strong>Effect</strong> Warder-Chief Mpondo Casts a Spell that takes 1 or 2 actions to cast and requires a spell attack roll. The effects of the spell do not occur immediately but are imbued into the attack instead. Mpondo makes a melee Strike. The spell is coupled with the attack, using the attack roll result to determine the effects of both the Strike and the spell.</p>\n<p>This counts as two attacks for Mpondo's multiple attack penalty, but don't apply the penalty until after he has completed the Spellstrike.</p>\n<p>After Mpondo uses Spellstrike, he can't do so again until he recharges his Spellstrike as a single action, which has the concentrate trait. Mpondo also recharges his Spellstrike when he casts a conflux spell.</p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/mutated-sewer-ooze":{"abilities":[{"n":"Motion Sense 60 feet","a":null,"c":"defensive","t":[],"f":"","d":"<p>A sewer ooze can sense nearby motion through vibration and air movements.</p>"},{"n":"Noxious Scent","a":null,"c":"defensive","t":["aura","olfactory"],"f":"","d":"<p>30 feet. A creature that enters the area must attempt a DC 23 Fortitude save. On a failure, the creature is Sickened 1 (Sickened 2 on a critical failure). A creature taking persistent acid damage from the ooze's pseudopod can't recover from the sickened condition. A creature that succeeds at its save is temporarily immune for 1 minute.</p>"},{"n":"Filth Wave","a":"1","c":"offensive","t":[],"f":"once per minute","d":"<p><strong>Frequency</strong> once per minute</p>\n<hr>\n<p><strong>Effect</strong> The sewer ooze unleashes a wave of filth, covering all creatures within a 20-foot emanation. Each creature in the area must succeed at a DC 24 Reflex save or take 1d4 acid damage and a –10-foot penalty to its Speeds for 1 minute (on a critical failure, the creature also falls Prone). A creature can spend an Interact action to clean someone off, decreasing the Speed penalty by 5 feet with each action.</p>\n<p>Effect: Filth Wave</p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/nairu":{"lang":["Common","Elven"],"lore":[["Underworld Lore",14]],"gear":["+1 Striking Composite Shortbow","+1 Rapier","Leather Armor","Darkvision Elixir (Lesser)","Giant Centipede Venom","Invisibility Potion","Simple Injury Poison (8)","Sleep Poison (2)","Arrows (20)"],"flavor":"<p>Assassins commit murder, either for pay or due to their belief in a cause, such as a religion or a political movement. Some assassins work alone and choose their own victims. Others are members of assassins' guilds, organizations that accept contracts to kill in return for money, favors, or both.</p>\n<hr>\n<p>Some criminals are the desperate who have no option but to break the law to survive, while others choose a life of crime for thrills, forming gangs or underworld guilds that specialize in certain illegal ventures.</p>","abilities":[{"n":"Swift Sneak","a":null,"c":"interaction","t":[],"f":"","d":"<p>Nairu can move their full speed when Sneaking.</p>"},{"n":"Deny Advantage","a":null,"c":"defensive","t":[],"f":"","d":"<p>Nairu isn't Off-Guard to creatures of 8th level or lower that are Hidden, Undetected, flanking or using Surprise Attack.</p>"},{"n":"Nimble Dodge","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> Nairu is targeted with a melee or ranged attack by an attacker they can see.</p>\n<hr>\n<p><strong>Effect</strong> Nairu gains a +2 circumstance bonus to AC against the triggering attack.</p>"},{"n":"Poison Weapon","a":"1","c":"offensive","t":["manipulate"],"f":"","d":"<p><strong>Requirements</strong> Nairu is wielding a piercing or slashing weapon and has a free hand.</p>\n<hr>\n<p><strong>Effect</strong> Nairu applied a poison to the weapon.</p>"},{"n":"Quick Draw","a":"1","c":"offensive","t":[],"f":"","d":"<p>Nairu Interacts to draw a weapon, then Strikes with that weapon.</p>"},{"n":"Sneak Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>Nairu deals an extra 2d6 precision damage to Off-Guard creatures.</p>"},{"n":"Surprise Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>On the first round of combat, creatures that haven't acted yet are Off-Guard to Nairu.</p>"}]},"strength-of-thousands-bestiary/book-4-secrets-of-the-temple-city/nkiruka":{"lang":["Common","Draconic","Elven","Mzunu","Taldane"],"gear":["Hand Crossbow","Sickle","Leather Armor","Bolts (20)"],"notes":{"per":"+29 to notice lies and sense motive"},"abilities":[{"n":"+4 to Notice Lies or Sense Motive","a":null,"c":"interaction","t":[],"f":"","d":"<p>+29 to notice lies and Sense Motive</p>"},{"n":"Ear for Lies","a":null,"c":"defensive","t":[],"f":"","d":"<p>Nkiruka's training allows her to recognize microexpressions, voice tone, and other tells. When a creature fails to Lie to Nkiruka, not only does she know they were lying, she also receives a clue about what that creature believes to be the truth.</p>"},{"n":"Group Impression","a":null,"c":"defensive","t":[],"f":"","d":"<p>When Nkiruka Makes an Impression, she can compare her Diplomacy check result to the Will DCs of up to four targets instead of one.</p>"},{"n":"Eye for an Opening","a":null,"c":"offensive","t":[],"f":"","d":"<p>Nkiruka's Strikes against creatures she observes that don't have cover and aren't Concealed deal an additional 2d10 precision damage.</p>"},{"n":"Size Up","a":"1","c":"offensive","t":[],"f":"","d":"<p>Nkiruka attempts a Perception check against the Deception DC or Will DC, whichever is higher, of a creature she can see. On a success, she gleans a notable detail about the creature as if she had successfully Recalled Knowledge about it. Once Nkiruka has Sized Up a creature, she can't do so again for 1 day.</p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/norgorberite-spy":{"lang":["Common"],"gear":["Dagger (4)","Leather Armor","Religious Symbol of Norgorber (Wooden)","Cognitive Mutagen (Greater)","Slumber Wine"],"abilities":[{"n":"Ranged Feint","a":null,"c":"defensive","t":[],"f":"","d":"<p>When the Norgorberite spy successfully Feints a creature, the target is Off-Guard against the spy's ranged attacks as well as melee attacks.</p>"},{"n":"Reaper's Protection","a":"r","c":"defensive","t":["manipulate"],"f":"","d":"<p><strong>Trigger</strong> The spy is about to attempt a saving throw</p>\n<hr>\n<p><strong>Effect</strong> The spy touches their religious symbol of Norgorber and gains a +2 circumstance bonus to the triggering save.</p>"},{"n":"Quick Draw","a":"1","c":"offensive","t":[],"f":"","d":"<p>The Norgorberite spy Interacts to draw a weapon, then Strikes with that weapon.</p>"},{"n":"Sneak Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>The Norgorberite spy deals an additional 4d6 precision damage to Off-Guard creatures or creatures within reach of at least two of their allies.</p>"},{"n":"Surprise Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>On the first round of combat, creatures that haven't acted yet are Off-Guard to the Norgorberite spy.</p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/old-thrasher":{"abilities":[{"n":"Death Roll","a":"1","c":"offensive","t":["attack"],"f":"","d":"<p><strong>Requirements</strong> Old Thrasher must have a creature Grabbed</p>\n<hr>\n<p><strong>Effect</strong> Old Thrasher tucks its legs and rolls rapidly, twisting its victim. It makes a jaws Strike with a +2 circumstance bonus to the attack roll against the grabbed creature. If it hits, it also knocks the creature Prone. If it fails, it releases the creature.</p>"},{"n":"Deep Breath","a":null,"c":"offensive","t":[],"f":"","d":"<p>Old Thrasher can hold its breath for about 4 hours.</p>"},{"n":"Into the Deep","a":"1","c":"offensive","t":[],"f":"","d":"<p><strong>Requirements</strong> Old Thrasher must have a creature grabbed</p>\n<hr>\n<p><strong>Effect</strong> Old Thrasher Swims, bringing its victim along with it.</p>"},{"n":"Thunderous Tail","a":"2","c":"offensive","t":[],"f":"","d":"<p>Old Thrasher makes up to three tail Strikes against different targets. Any target hit must succeed at a Fortitude (success) (Fortitude (critical success)) save or be knocked Prone.</p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/onyiji":{"lang":["Common","Orcish"],"lore":[["Warfare Lore",16]],"gear":["Staff"],"abilities":[{"n":"Attack of Opportunity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Orc Superstition","a":"r","c":"defensive","t":["concentrate"],"f":"","d":"<p><strong>Trigger</strong> Onyiji is about to make a saving throw against a spell or magical effect</p><hr>\n<p><strong>Effect</strong> Onyiji gains a +1 circumstance bonus to the triggering save.</p>"},{"n":"Spellstrike","a":"2","c":"offensive","t":[],"f":"twice per day","d":"<p><strong>Frequency</strong> twice per day</p><hr>\n<p><strong>Effect</strong> Onyiji casts a spell and couples it with a staff Strike. She casts Ignition, Ray of Frost, or Shocking Grasp, but the effects don't occur immediately. She makes a melee Strike with her staff and uses the attack roll result as the effect of both the Strike and the spell.</p>\n<p>This counts as two attacks towards her multiple attack penalty, but the penalties don't apply until after the Spellstrike.</p>"},{"n":"Twisting Tree","a":null,"c":"offensive","t":[],"f":"","d":"<p>When Onyiji wields a staff in one hand, it gains the agile trait and its damage die size increases to d6 (these adjustments are reflected in the Strike above). When she wields a staff in two hands, it gains the parry, reach, and trip traits.</p>\n<p>She can Interact to Release or change her grip on her staff as a free action when she Strikes with the staff (including Strikes made in a Spellstrike).</p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/pugwampi-sot":{"lang":["Kholo","Sakvroth"],"gear":["Shortbow","Shortsword","Arrows (60)"],"notes":{"per":"(-2 to hear things)"},"focus":1,"flavor":"<p>Mean, dog-faced, and craven, pugwampis take disproportionate enjoyment from the accidents and missteps of other creatures-something that happens often due to the supernatural aura of ill fortune these gremlins project. They enjoy preparing pranks involving spikes, excrement, pits full of spiders, and the like. Pugwampis are somewhat deaf and thus often yell loudly to each other when not hiding. Many pugwampis worship gnolls as gods and aspire to be more like gnolls, although gnolls hate pugwampis even more than most creatures do, due to their sycophantic fawning.</p>\n<hr>\n<p>Gremlins are cruel fey tricksters and saboteurs who have fully acclimated to life on the Material Plane, finding distinct niches for their inventive destructiveness. All gremlins delight in ruining or breaking things, whether it's something physical like a device or vehicle or something intangible such as an alliance or relationship. A gremlin's greatest joy is watching the collapse of complex creations, preferably after the lightest and slightest, carefully targeted push from the gremlin. Gremlins tend to denigrate, bully, or even slaughter their lesser kin, particularly mitflits, whom gremlins (and many others) derisively call \"mites.\"</p>","abilities":[{"n":"-2 Penalty on Perception to Hear things","a":null,"c":"interaction","t":[],"f":"","d":""},{"n":"Unluck Aura","a":null,"c":"defensive","t":["aura","mental","misfortune","primal"],"f":"","d":"<p>20 feet. Creatures other than animals, gremlins, and gnolls in the aura become extremely unlucky (DC 16 Will save; creature must roll this Will save twice and take the worse result). On a successful save, the creature is temporarily immune to pugwampi unluck auras for 24 hours. On a failure, the creature must roll twice and take the worse result on all checks as long as it is within the aura.</p>\n<p>Effect: Unluck Aura</p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/ravager-of-tindalos":{"lang":["Aklo"],"focus":1,"flavor":"<p>Lean and athirst, the hounds of Tindalos are drawn to those who tamper with the flow of time, travel through time, or use magic or rare alchemical drugs to send their thoughts or perception back or forward in time. Powerful spellcasters can draw them from the Dimension of Time via rare rituals, but doing so attracts the hounds' ire, so few who traffic in such rituals live long enough to spread their knowledge. While the hounds possess great cunning and cruel intellect, they rarely interact with other creatures-other than to hunt and destroy those who have attracted their unblinking attention.</p>\n<p>Once a hound catches scent of a mortal to hunt, it calls others of its ilk. The pack then pursues its victim through all space and time until it catches, slays and devours them. Those pursued can escape only by avoiding all angles, as hounds of Tindalos could step through them from nothingness at any time.</p>","abilities":[{"n":"Greater Darkvision","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>A creature with greater darkvision can see perfectly well in areas of darkness and dim light, though such vision is in black and white only. A creature with greater darkvision can see through even forms of magical darkness.</p></p>"},{"n":"Constant Spells","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>A constant spell affects the monster without the monster needing to cast it, and its duration is unlimited. If a constant spell gets counteracted, the monster can reactivate it by spending the normal spellcasting actions the spell requires.</p></p>"},{"n":"Otherworldly Mind","a":null,"c":"defensive","t":["mental"],"f":"","d":"<p>Whenever a creature targets the ravager of Tindalos with a mental effect, that creature takes 9d6 mental damage (DC 40 basic Will save).</p>\n<p>On a critical failure, it also becomes Confused for 1 minute.</p>"},{"n":"Ripping Gaze","a":null,"c":"defensive","t":["aura","occult","visual"],"f":"","d":"<p>30 feet. The ravager of Tindalos's eyes glow balefully, causing painful but bloodless wounds to rip open in the body of a creature that meets its awful gaze. When a creature ends its turn in the aura's emanation, it takes 9d6 slashing damage (DC 37 basic Fortitude save).</p>\n<p>A creature that critically succeeds at its save is temporarily immune for 24 hours.</p>"},{"n":"Vulnerable to Curved Space","a":null,"c":"defensive","t":[],"f":"","d":"<p>When a ravager of Tindalos is not adjacent to a structural angle of 90º (or more acute), its resistance to physical damage is suppressed and it becomes Sickened 1. It can't recover from this sickened condition, but the condition ends automatically once the ravager is again adjacent to a suitable angle.</p>\n<p>Effect: Vulnerable to Curved Space</p>"},{"n":"Angled Entry","a":"1","c":"offensive","t":[],"f":"","d":"<p>The ravager of Tindalos casts a 4th-rank Translocate spell, but it must transport itself into a space adjacent to an angle of 90º (or more acute) in the structure or environment around it. For example, it could teleport to a space adjacent to a wall (using the angle between the wall and floor) or a corner in a room, or adjacent to a sizable tree growing straight up out of the ground, but not to a flat plain or a room with only curved corners and edges.</p>\n<p>Once per day, the ravager can use this ability to plane shift to or from the Dimension of Time, with the same restrictions on what angles it can appear next to.</p>"},{"n":"Ferocious Bites","a":"2","c":"offensive","t":[],"f":"","d":"<p>The ravager of Tindalos makes three Strikes with its jaws attack. Each Strike must be against a different opponent within its reach.</p>\n<p>Each attack counts toward the ravager's multiple attack penalty, but does not increase its penalty until it has made all the attacks.</p>"}]},"strength-of-thousands-bestiary/book-4-secrets-of-the-temple-city/reborn-sun-hunter":{"lang":["Common","Necril"],"gear":["Dagger","Religious Symbol of Walkena"],"notes":{"hp":"void healing"},"abilities":[{"n":"Burning Sacrifice","a":null,"c":"defensive","t":["divine","fire"],"f":"","d":"<p>When the sun hunter is destroyed, they explode in a blast of flame that deals 6d6 fire damage in a 10-foot emanation (DC 27 basic Reflex save). Creatures that critically fail their saves are marked with Walkena's religious symbol on a visible area of their body, which remains for 1 day. This mark allows Walkena to treat the creature as if he knew the creature's identity but not having met them for the purposes of Scrying, lowering the spell's DC by 2. The sun hunter's gear and treasure are unaffected by the explosion and left in a pile where they die.</p>"},{"n":"Nimble Dodge","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The sun hunter is targeted with a melee or ranged attack by an attacker they can see</p><hr><p><strong>Effect</strong> The sun hunter gains a +2 circumstance bonus to AC against the triggering attack.</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Sneak Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>The sun hunter's Strikes deal an additional 2d6 precision damage to Off-Guard creatures.</p>"},{"n":"Study Foe","a":"1","c":"offensive","t":[],"f":"","d":"<p>The sun hunter reads a creature they can see within 30 feet to notice openings. The sun hunter attempts a Perception check against that creature's Deception DC or Will DC, whichever is higher. The target is then temporarily immune for 1 minute.</p>\n<hr>\n<p><strong>Critical Success</strong> The sun hunter reads the target like a book. The target is Off-Guard against the sun hunter's attacks until the end of the sun hunter's next turn.</p>\n<p><strong>Success</strong> The sun hunter notices a brief opening. The target is off-guard against the sun hunter's attacks until the end of the sun hunter's turn.</p>\n<p><strong>Failure</strong> The target is unaffected.</p>\n<p><strong>Critical Failure</strong> The sun hunter's intense focus opens them up to other attacks. The target is unaffected, and the sun hunter is off-guard until the start of their next turn.</p>"}]},"strength-of-thousands-bestiary/book-4-secrets-of-the-temple-city/reborn-sun-mage":{"lang":["Common","Necril"],"gear":["Staff of Fire (Major)","Religious Symbol of Walkena"],"notes":{"hp":"void healing"},"abilities":[{"n":"Burning Sacrifice","a":null,"c":"defensive","t":["divine","fire"],"f":"","d":"<p>When the sun mage is destroyed, they explode in a blast of flame that deals 6d6 fire damage in a 10-foot emanation (DC 27 basic Reflex save). Creatures that critically fail their saves are marked with Walkena's religious symbol on a visible area of their body, which remains for 1 day. This mark allows Walkena to treat the creature as if he knew the creature's identity but not having met them for the purposes of Scrying, lowering the spell's DC by 2. The sun mage's gear and treasure are unaffected by the explosion and left in a pile where they die.</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Revitalizing Flame","a":"1","c":"offensive","t":["divine","healing"],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p><hr><p><strong>Effect</strong> The sun mage produces a specialized flame that burns away maladies and restores a creature. If the sun mage's next action is to Cast a Spell with the fire trait that deals damage and isn't a cantrip, the spell doesn't deal any damage. It instead restores a number of Hit Points equal to four times the spell's rank to all targets or creatures. This restoration affects all creatures regardless of whether they are healed by vitality or void energy.</p>"}]},"strength-of-thousands-bestiary/book-4-secrets-of-the-temple-city/reborn-sun-warrior":{"lang":["Common","Necril"],"gear":["Flame Spike","Religious Symbol of Walkena"],"notes":{"hp":"void healing"},"abilities":[{"n":"Burning Sacrifice","a":null,"c":"defensive","t":["divine","fire"],"f":"","d":"<p>When the sun warrior is destroyed, they explode in a blast of flame that deals 6d6 fire damage in a 10-foot emanation (DC 27 basic Reflex save). Creatures that critically fail their saves are marked with Walkena's religious symbol on a visible area of their body, which remains for 1 day. This mark allows Walkena to treat the creature as if he knew the creature's identity but not having met them for the purposes of Scrying, lowering the spell's DC by 2. The sun warrior's gear and treasure are unaffected by the explosion and left in a pile where they die.</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Constrict","a":"1","c":"offensive","t":[],"f":"","d":"<p>1d4+9 bludgeoning plus 2d6 fire damage, DC 27 basic Fortitude save</p>\n<hr>\n<p><p>The monster deals the listed amount of damage to any number of creatures Grabbed or Restrained by it. Each of those creatures can attempt a basic Fortitude save with the listed DC.</p></p>"},{"n":"Knocking Sweep","a":"2","c":"offensive","t":[],"f":"once per round","d":"<p><strong>Frequency</strong> once per round</p><hr>\n<p><strong>Effect</strong> The sun warrior swings their weapon with a sweeping spin. They attempt separate Athletics checks to Trip any number of creatures within their reach. Each attempt counts toward the sun warrior's multiple attack penalty, but the multiple attack penalty doesn't increase until after they make all the attacks.</p>"},{"n":"Pinning Thrust","a":"2","c":"offensive","t":[],"f":"","d":"<p>The sun warrior attempts to drive their spear through a foe to pin them in place. The sun warrior makes a spear Strike. On a hit, the target's clothes, armor, or other piece of equipment becomes pinned to the ground. The sun warrior Releases the spear, and the target is Immobilized until they can remove the spear (Escape). If the Strike was a critical hit, the DC increases by 2.</p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/red-commander-ant":{"lang":["Common"],"abilities":[{"n":"Attack of Opportunity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Constrict","a":"1","c":"offensive","t":[],"f":"","d":"<p>5d10 bludgeoning damage, DC 38 basic Fortitude.</p>\n<p>Before using Constrict, the ant can choose to smash one creature that it has Grabbed or Restrained against the ground. That creature uses the result one degree of success worse than its Fortitude save result against Constrict, but it is then no longer Grabbed or restrained by the ant.</p>\n<hr>\n<p><p>The monster deals the listed amount of damage to any number of creatures Grabbed or Restrained by it. Each of those creatures can attempt a basic Fortitude save with the listed DC.</p></p>"},{"n":"For the Queen!","a":"2","c":"offensive","t":["olfactory"],"f":"","d":"<p>The red commander ant gives a pheromone signal to spur other ants into a fury. All ants within 30 feet who can smell this signal gain a +1 status bonus to attack rolls, reduce their frightened condition to 0, and are immune to the frightened condition for 1 minute.</p>"},{"n":"Red Ant Venom","a":null,"c":"offensive","t":["poison"],"f":"","d":"<p><strong>Saving Throw</strong> DC 38 Fortitude</p>\n<p><strong>Maximum Duration</strong> 4 rounds</p>\n<p><strong>Stage 1</strong> 3d6 poison damage and Enfeebled 1 (1 round)</p>\n<p><strong>Stage 2</strong> 4d6 poison damage and Enfeebled 2 (1 round)</p>\n<p><strong>Stage 3</strong> 6d6 poison damage and Enfeebled 3 (1 round)</p>"},{"n":"The Queen's Enemy","a":"1","c":"offensive","t":["concentrate"],"f":"","d":"<p>The red commander ant designates a single creature within 60 feet that it can see as its queen's enemy. All ants within 120 feet of the red commander ant deal an additional 1d8 bleed damage when they hit the target with mandibles Strikes. These effects last for 1 minute, or until the red commander ant uses The Queen's Enemy on a different creature.</p>"},{"n":"Improved Grab","a":"f","c":"offensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> The monster's last action was a successful Strike that lists Improved Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with as a free action. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Improved Grab as an action and choose one creature it's grabbing or restraining with an appendage that has Improved Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/red-guard-ant":{"lang":["Common"],"abilities":[{"n":"Attack of Opportunity (Stinger Only)","a":"r","c":"defensive","t":[],"f":"","d":"<p>Stinger only</p>\n<hr>\n<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Formic Acid Spray","a":"2","c":"offensive","t":["acid","primal"],"f":"","d":"<p>The red guard ant sprays a 15-foot cone of acid from its abdomen that deals 10d10 acid damage (DC 34 basic Reflex). It can't use Formic Acid Spray again for 1d4 rounds.</p>"},{"n":"Haul Away","a":"1","c":"offensive","t":[],"f":"","d":"<p><strong>Requirements</strong> The red guard ant has a Huge or smaller creature Grabbed</p>\n<hr>\n<p><strong>Effect</strong> The ant Strides up to its full Speed, carrying the grabbed creature with it. It's encumbered if the grabbed creature is Large or larger.</p>"},{"n":"Pack Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>A red guard ant deals an additional 2d6 precision damage to any creature within reach of at least two of the ant's allies.</p>"},{"n":"Red Ant Venom","a":null,"c":"offensive","t":["poison"],"f":"","d":"<p><strong>Saving Throw</strong> DC 36 Fortitude</p>\n<p><strong>Maximum Duration</strong> 4 rounds</p>\n<p><strong>Stage 1</strong> 3d6 poison damage and Enfeebled 1 (1 round)</p>\n<p><strong>Stage 2</strong> 4d6 poison damage and Enfeebled 2 (1 round)</p>\n<p><strong>Stage 3</strong> 6d6 poison damage and Enfeebled 3 (1 round)</p>"},{"n":"Swarming Flank","a":null,"c":"offensive","t":[],"f":"","d":"<p>If at least three red guard ants have a creature within their reach, they flank the creature, even if they can't draw a line to each other that passes through opposite sides of the creature's space.</p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/red-queen":{"lang":["Common"],"gear":["Ornate Platinum and Ruby Jewelry"],"abilities":[{"n":"Attack of Opportunity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Lead by Example","a":"2","c":"offensive","t":["visual"],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p>\n<hr>\n<p><strong>Effect</strong> The Red Queen Strikes a creature with a vicious display that inspires her allies. Allies who can see the Red Queen can use a reaction to Step or Stride to a space adjacent to an enemy, or to Strike.</p>"},{"n":"Practiced Subterfuge","a":null,"c":"offensive","t":[],"f":"","d":"<p>When the Red Queen makes a Deception check to Feint, she compares her result to the Will DC of each enemy within 30 feet to determine the effect against that enemy. On a critical success, the creature is Off-Guard to all melee attacks, not just melee attacks from the Red Queen, until the end of her next turn.</p>"},{"n":"Red Ant Venom","a":null,"c":"offensive","t":["poison"],"f":"","d":"<p><strong>Saving Throw</strong> DC 40 Fortitude</p>\n<p><strong>Maximum Duration</strong> 4 rounds</p>\n<p><strong>Stage 1</strong> 3d6 poison damage and Enfeebled 1 (1 round)</p>\n<p><strong>Stage 2</strong> 4d6 poison damage and Enfeebled 2 (1 round)</p>\n<p><strong>Stage 3</strong> 6d6 poison damage and Enfeebled 3 (1 round)</p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/reth":{"lang":["Common","Draconic","Iruxi"],"gear":["Hand Crossbow","Leather Armor","Key Ring","Thieves' Tools","Bolts (10)"],"abilities":[{"n":"Deadly Bolts","a":"1","c":"offensive","t":["stance"],"f":"","d":"<p><strong>Requirements</strong> Reth is wielding a crossbow</p>\n<hr>\n<p><strong>Effect</strong> Reth gains a deadly focus with crossbows while in this stance. His crossbow Strikes deal an additional 3d8 precision damage. He doesn't provoke reactions for making ranged Strikes with crossbows.</p>"},{"n":"Deep Breath","a":null,"c":"offensive","t":[],"f":"","d":"<p>Reth can hold his breath for 200 rounds (20 minutes).</p>"},{"n":"Running Reload","a":"1","c":"offensive","t":[],"f":"","d":"<p>Reth Strides, Steps, or Sneaks, then Interacts to reload.</p>"},{"n":"Skirmishing Shot","a":"1","c":"offensive","t":["flourish"],"f":"","d":"<p>Reth Strides or Steps, then Strikes with his hand crossbow.</p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/riding-frog":{"abilities":[{"n":"Sticky Feet","a":null,"c":"offensive","t":[],"f":"","d":"<p>Giant frogs are not off-guard when Balancing on a narrow surface, and they gain a +4 bonus to Reflex saves to avoid falling.</p>"},{"n":"Tongue Grab","a":null,"c":"offensive","t":[],"f":"","d":"<p>A creature hit by the riding frog's tongue becomes Grabbed by the riding frog. The creature isn't Immobilized, but it can't move beyond the reach of the frog's tongue. A creature can sever the tongue with a Strike against AC 13 that deals at least 2 slashing damage.</p>\n<p>This deals no damage to the frog but prevents it from using its tongue Strike until it regrows its tongue, which takes a week.</p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/rigged-ramen-cart":{"description":"<p>A seemingly innocent ramen cart is rigged to detonate if moved from its current location.</p>","disable":"<p>DC 40 Thievery (master) to disable the detonation trigger</p>","stealthNote":"<p>(expert)</p>","abilities":[{"n":"Death by Noodle","a":"r","c":"offensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The cart is moved, damaged, or physically searched</p>\n<hr>\n<p><strong>Effect</strong> The cart explodes in a 40-foot radius, dealing 10d6 fire damage and and 10d6 piercing damage to all creatures within the area (DC 36 basic Reflex save).</p>\n<p>Creatures who fail their save against this effect are also covered in \"noodles\" of tar and other sticky alchemical substances that make the creature Clumsy 2 until they spend at least an hour scrubbing the noodles off.</p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/salathiss":{"lang":["Aklo","Common","Draconic","telepathy 100 feet"],"gear":["Bands of Force","Choker of Elocution (Xanmba)"],"notes":{"saves":"+4 status to Will vs. mental, +1 status to all saves vs. magic"},"abilities":[{"n":"Telepathy 100 feet","a":null,"c":"interaction","t":["aura","magical"],"f":"","d":"<p><p>A monster with telepathy can communicate mentally with any creatures within the listed radius, as long as they share a language. This doesn't give any special access to their thoughts, and communicates no more information than normal speech would.</p></p>"},{"n":"+1 Status to All Saves vs. Magic","a":null,"c":"defensive","t":[],"f":"","d":""},{"n":"+4 Status to Will vs. Mental","a":null,"c":"defensive","t":[],"f":"","d":""},{"n":"Morphic Weapon","a":"1","c":"offensive","t":["morph","occult"],"f":"","d":"<p>Salathiss transforms one of his hands into a tentacle with a blade at the end, allowing him to make morphic weapon Strikes. If he's disguised, whether by magical or mundane means, his disguise immediately ends. He can return his hand to normal with another use of this ability, but doing so doesn't restore his disguise.</p>"},{"n":"Peerless Duplicate","a":null,"c":"offensive","t":["exploration","fortune","occult"],"f":"","d":"<p>If Salathiss interacts with a creature for 10 minutes, he can choose to expertly duplicate that person. He can roll any Deception check to Impersonate that person twice and take the higher result. This benefit lasts for 24 hours or until he uses this ability on a different creature.</p>"},{"n":"Serpentfolk Venom","a":null,"c":"offensive","t":["poison"],"f":"","d":"<p><strong>Saving Throw</strong> DC 26 basic Fortitude</p>\n<p><strong>Maximum Duration</strong> 6 rounds</p>\n<p><strong>Stage 1</strong> 2d4 poison damage and Enfeebled 1 (1 round)</p>\n<p><strong>Stage 2</strong> 3d4 poison damage and Enfeebled 2 (1 round)</p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/screaming-sulfur":{"lang":["Common"],"notes":{"hp":"void healing, rejuvenation"},"flavor":"<p>A screaming sulfur is a creature born from gasping death and suffocating suffering. When an earthquake or other geological phenomena releases toxic gases, these gases can build up beneath lakes and other large bodies of water. Eventually, they escape the water, expanding into massive clouds that cover the immediate area. Its silent, unexpected arrival can take thousands of lives in an instant. Confused, in pain, and desperate for a way out, the dying souls become trapped in the noxious cloud and amass into this horrifying creature.</p>\n<p>While not truly undead, a screaming sulfur shares many similarities with undead creatures, including the malice of vengeful spirits and the hatred of all living creatures who breathe freely and painlessly.</p>\n<p>A screaming sulfur resembles a cloud made of countless, featureless faces, mouths agape and releasing ghastly wails.</p>","abilities":[{"n":"Site Bound","a":null,"c":"interaction","t":[],"f":"","d":"<p>A screaming sulfur becomes bound to the location where the people whose souls make up its form died. It can stray up to 1,000 feet from this site of death, or up to 100 feet from the edges of any waterway associated with its death, whichever distance is shorter.</p>\n<hr>\n<p>A typical ghost can stray only a short distance from where it was killed or the place it haunts. A typical limit is 120 feet. Some ghosts are instead bound to a room, building, item, or creature that was special to it rather than a location.</p>"},{"n":"Agonizing Cries","a":null,"c":"defensive","t":["auditory","aura","emotion","mental"],"f":"","d":"<p>30 feet. The screaming sulfur constantly shrieks with the pained wails of countless spirits.</p>\n<p>A living creature that enters or starts its turn in the aura must succeed at a DC 26 Will save or become Frightened 1 as long as it remains in the aura (Frightened 2 on a critical failure).</p>\n<p>A creature that succeeds is temporarily immune for 1 hour.</p>"},{"n":"Rejuvenation","a":null,"c":"defensive","t":["divine"],"f":"","d":"<p>Blessing the site where the screaming sulfur was formed and burying whatever dead remain allows the spirits within the screaming sulfur to move on to the afterlife, rendering it inert.</p>\n<hr>\n<p>When a ghost is destroyed, it re-forms after 2d4 days within the location it's bound to, fully healed. A ghost can be permanently destroyed only if someone determines the reason for its existence and sets right whatever prevents the spirit from resting.</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Choke","a":"2","c":"offensive","t":["divine","illusion","mental"],"f":"","d":"<p>The screaming sulfur bombards all creatures within its Agonizing Cries aura with visions of death and a feeling of suffocation. Each creature takes 4d6 mental damage (DC 26 basic Will save).</p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/scrit":{"lang":["Sakvroth"],"flavor":"<p>Scrits are short, spindly gremlins with gray or beige leathery skin and a coat of smeared ink on their fingers. They make themselves the nightmare of many scribes and librarians, as they delight in nothing more than destroying books, scrolls, artwork, and other records or writing. The oils on a scrit's skin smears ink and renders text-even magical writing-completely illegible. Once they have smeared every page of a book, scrits devour them whole, absorbing the contents the book used to hold. After eating books they find stupid or funny, scrits hold skits for other gremlins which mock the mortal authors for the amusement of the other fey.</p>\n<hr>\n<p>Gremlins are malicious fey that infest and prey upon mortal communities. They live in tunnels, beneath eaves, and in abandoned buildings, stealing what they need from their neighbors instead of creating for themselves.</p>\n<p>While there are gremlins of any and every gender, their appearances don't differ by gender. Young gremlins grow to maturity with alarming speed. Their entire nest raises them communally, though they are often encouraged to wander unsupervised and create mischief away from home instead of inside it.</p>","abilities":[{"n":"Eat Book","a":"3","c":"defensive","t":[],"f":"","d":"<p>A scrit can consume a book after smearing its pages to absorb its contents (it gains no benefit from consuming a book with pages smeared by another scrit). For 1 day after consuming the book, the scrit can make Recall Knowledge skill checks on the book's subject with a +4 item bonus, and it can speak and understand the languages the book was written in. If it Eats another Book, it replaces the benefits of the previous Eat Book.</p>"},{"n":"Nasty Ink","a":null,"c":"offensive","t":["poison"],"f":"","d":"<p>A scrit's fingers are perpetually covered in smeared ink from the writing it's destroyed. This ink mixes with its skin oils to create a disgusting, sticky poison.</p>\n<p><strong>Saving Throw</strong> DC 14 Fortitude</p>\n<p><strong>Maximum Duration</strong> 4 rounds</p>\n<p><strong>Stage 1</strong> 1d4 poison damage and Sickened 1 (1 round)</p>"},{"n":"Smear Text","a":"1","c":"offensive","t":[],"f":"","d":"<p>The scrit rubs its fingers against one page of writing, smearing the text and rendering it unreadable. The scrit can smear and destroy magical writing such as a Rune Trap or a Sigil by succeeding at a counteract check (using the scrit's spell attack modifier) against the caster's DC.</p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/serpent-ward":{"description":"<p>Illusionary snakes erupt from the trapped door, inflicting a venomous curse on intruders.</p>","disable":"<p>DC 26 Thievery (expert) or DC 24 Occultism (expert) to deactivate the magical trigger</p>","stealthNote":"<p>(expert)</p>","abilities":[{"n":"Curse the Intruders","a":"r","c":"offensive","t":["curse","illusion","occult"],"f":"","d":"<p><strong>Trigger</strong> The trapped door is opened other than by a serpentfolk</p>\n<hr>\n<p><strong>Effect</strong> Hissing, illusionary snakes leap from the door. Each living creature within 30 feet is subjected to the curse of potent poison. If a living creature opened the door, that creature must roll its saving throw against the curse twice and take the worse result (this is a misfortune effect).</p>\n<hr>\n<h3>Curse of Potent Poison (uncommon, curse, magical) CURSE 5</h3>\n<p>This curse magically speeds poison through your body.</p>\n<p><strong>Saving Throw</strong> DC 20 Will</p>\n<hr>\n<p><strong>Effect</strong> You take a -1 status penalty to Fortitude saves and you gain weakness 3 to poison (if you already have weakness to poison, increase it by 3). The curse remains until removed by Cleanse Affliction or similar magic.</p>\n<p>Effect: Curse of Potent Poison</p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/serpentfolk-granitescale":{"lang":["Aklo","Common","telepathy 100 feet"],"gear":["Javelin (5)","Longspear"],"notes":{"ac":"(22 with shed scales)","saves":"+2 status to Will vs. mental"},"flavor":"<p>Many burly aapoph serpentfolk bear minor mutations. Granitescales have bulky frames covered in hard, speckled gray plates. These scales offer additional protection but shed when struck with too much force. As granitescales regrow lost scales quickly, they make effective long-term sentinels and vanguards for guerilla tactics. Granitescales like to carve their shed scales into small chips and attach them as rattles to the ends of their spears. Many an unsuspecting victim has heard the shaking hiss of a granitescale's rattle too late.</p>\n<hr>\n<p>Ancient and cunning, the once mighty serpentfolk have suffered numerous setbacks and indignities since the decapitation of their god, Ydersius, millennia ago. Scattered in isolated pockets, the reptilian humanoids constantly scheme their return to glory. Though many serpentfolk labor to restore Ydersius and reclaim power through him, others pursue different avenues to greatness, such as by mastering uncanny magic or practicing spycraft to take down enemy organizations from the inside.</p>","abilities":[{"n":"Telepathy 100 feet","a":null,"c":"interaction","t":["aura","magical"],"f":"","d":"<p><p>A monster with telepathy can communicate mentally with any creatures within the listed radius, as long as they share a language. This doesn't give any special access to their thoughts, and communicates no more information than normal speech would.</p></p>"},{"n":"+2 Status to Will vs. Mental","a":null,"c":"defensive","t":[],"f":"","d":""},{"n":"Attack of Opportunity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Chipping Scales","a":"r","c":"defensive","t":[],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p>\n<p><strong>Trigger</strong> The granitescale takes piercing or slashing damage</p>\n<hr>\n<p><strong>Effect</strong> The granitescale twists to take the blow on their hardest scales, which they shed to reduce the incoming force. The granitescale reduces the damage by 10, but their AC is reduced by 2 for 1 day, when the shed scales regrow.</p>"},{"n":"Rattling Spear","a":"1","c":"offensive","t":["auditory","emotion","mental"],"f":"","d":"<p><strong>Requirements</strong> The granitescale's last action was a successful spear Strike</p>\n<hr>\n<p><strong>Effect</strong> The granitescale rattles the base of their spear, attempting an Intimidation check to Demoralize all enemies within 30 feet (compare the granitescale's Intimidation check result to the targets' Will DCs individually).</p>"},{"n":"Serpentfolk Venom","a":null,"c":"offensive","t":["poison"],"f":"","d":"<p><strong>Saving Throw</strong> DC 22 basic Fortitude</p>\n<p><strong>Maximum Duration</strong> 6 rounds</p>\n<p><strong>Stage 1</strong> 1d4 poison damage and Enfeebled 1 (1 round)</p>\n<p><strong>Stage 2</strong> 2d4 poison damage and enfeebled 1 (1 round)</p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/serpentfolk-venom-caller":{"lang":["Aklo","Common","Draconic","telepathy 100 feet"],"gear":["Shortbow","Sickle","Arrows (20)"],"notes":{"saves":"+4 status to Will vs. mental, +1 status to all saves vs. magic"},"flavor":"<p>Venom callers are zyss serpentfolk spellcasters that specialize in the use of acid and poison magic, viewing them as natural extensions of their inherent venom. They have a reputation for bold action, something that puts them at odds with other zyss who prefer stealth and subterfuge. When a venom caller can't eliminate their rivals to seize control of their colony, they often leave in a dramatic demonstration of arrogance, insisting that slithering in shadows does the serpentfolk cause no favors.</p>\n<p>Though venom callers aren't considered subtle by their kin, their schemes-which often revolve around acquiring rare magical lore-can nevertheless take humanoid communities by surprise. Venom callers often lure away unsuspecting victims, murder them, and disfigure their venom-wracked bodies with acid; the venom caller then assumes the victim's form. Authorities, believing all members of the community are accounted for, assume the unrecognizable corpse must have been a traveler. Most venom callers have broken with other serpentfolk communities and have no qualms about murdering their kin or infiltrating other serpentfolk cells if it serves their purposes.</p>\n<hr>\n<p>Ancient and cunning, the once mighty serpentfolk have suffered numerous setbacks and indignities since the decapitation of their god, Ydersius, millennia ago. Scattered in isolated pockets, the reptilian humanoids constantly scheme their return to glory. Though many serpentfolk labor to restore Ydersius and reclaim power through him, others pursue different avenues to greatness, such as by mastering uncanny magic or practicing spycraft to take down enemy organizations from the inside.</p>","abilities":[{"n":"Telepathy 100 feet","a":null,"c":"interaction","t":["aura","magical"],"f":"","d":"<p><p>A monster with telepathy can communicate mentally with any creatures within the listed radius, as long as they share a language. This doesn't give any special access to their thoughts, and communicates no more information than normal speech would.</p></p>"},{"n":"+1 Status to All Saves vs. Magic","a":null,"c":"defensive","t":[],"f":"","d":""},{"n":"+4 Status to Will vs. Mental","a":null,"c":"defensive","t":[],"f":"","d":""},{"n":"Serpentfolk Venom","a":null,"c":"offensive","t":["poison"],"f":"","d":"<p><strong>Saving Throw</strong> DC 23 basic Fortitude</p>\n<p><strong>Maximum Duration</strong> 6 rounds</p>\n<p><strong>Stage 1</strong> 1d4 poison damage and Enfeebled 1 (1 round)</p>\n<p><strong>Stage 2</strong> 2d4 poison damage and enfeebled 1 (1 round)</p>"},{"n":"Venom Pool","a":"2","c":"offensive","t":["arcane","poison"],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p>\n<hr>\n<p><strong>Effect</strong> The venom caller conjures a 10-foot burst of liquid poison within 60 feet. Each creature that begins its turn in the area takes 4d6 poison damage (DC 25 basic Fortitude save). On a critical failure, creatures also take 1d6 persistent poison. Once per turn, starting the turn after the venom caller uses Venom Pool, the venom caller can use a single action, which has the concentrate trait, to increase the radius of the burst by 5 feet. The pool of venom lasts for 1 minute, at which time it evaporates without a trace.</p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/shianshi-waymaker":{"lang":["Aklo","Common","Necril"],"gear":["Greatsword"],"notes":{"hp":"(void healing)"},"abilities":[{"n":"Greater Darkvision","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>A creature with greater darkvision can see perfectly well in areas of darkness and dim light, though such vision is in black and white only. A creature with greater darkvision can see through even forms of magical darkness.</p></p>"},{"n":"Attack of Opportunity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Claim Trophy","a":"1","c":"offensive","t":[],"f":"","d":"<p>Shianshi claims the soul of a creature she killed within the last minute. This works like Seize Soul, except that no black sapphire is required and the soul is turned into a glowing blue light called a soul trophy. Anyone who kills Shianshi can then free the soul from any soul trophy by touching it and speaking the word for \"freedom\" in any language.</p>"},{"n":"Huntblade Brutality","a":null,"c":"offensive","t":[],"f":"","d":"<p>Shianshi's greatsword Strikes have the death trait and deal an additional 2d8 damage to Drained, Off-Guard, or Frightened creatures.</p>"},{"n":"Hunter's Leap","a":"r","c":"offensive","t":["occult","teleportation"],"f":"","d":"<p><strong>Trigger</strong> Shianshi kills a creature</p>\n<hr>\n<p><strong>Effect</strong> Shianshi teleports up to 30 feet and makes a greatsword Strike; on a hit, the target of the Strike is Frightened 1 (Frightened 3 on a critical hit).</p>"},{"n":"Whip Drain","a":"1","c":"offensive","t":["arcane","death"],"f":"","d":"<p><strong>Requirements</strong> Shianshi has a creature Grabbed with her shadow whip</p>\n<hr>\n<p><strong>Effect</strong> The grabbed creature must succeed at a DC 41 Fortitude save or become Drained 2 (Drained 3 on a critical failure). If the creature is already drained, this increases its drained value instead, to a maximum of drained 4.</p>"},{"n":"Improved Grab","a":"f","c":"offensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> The monster's last action was a successful Strike that lists Improved Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with as a free action. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Improved Grab as an action and choose one creature it's grabbing or restraining with an appendage that has Improved Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/shieldbearer-construct":{"gear":["Wooden Sword","Wooden Shield"],"abilities":[{"n":"Attack of Opportunity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Critical Vulnerability","a":null,"c":"defensive","t":[],"f":"","d":"<p>A critical hit damages the construct's controls, making it Clumsy 1 until repaired. Additional critical hits increase this value, up to Clumsy 4.</p>"},{"n":"Ridden Construct","a":null,"c":"defensive","t":[],"f":"","d":"<p>The construct is piloted by a Leaf Leshy who can be targeted separately but has greater cover. The leshy can't take actions of their own while inside the construct, other than to leave it, which takes 1 minute.</p>"},{"n":"Shield Block","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> The monster has its shield raised and takes damage from a physical attack.</p>\n<hr>\n<p><strong>Effect</strong> The monster snaps its shield into place to deflect a blow. The shield prevents the monster from taking an amount of damage up to the shield's Hardness. The monster and the shield each take any remaining damage, possibly breaking or destroying the shield.</p></p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/shobhad-enforcer":{"lang":["Akitonian","Shobhad"],"gear":["Greatsword","+2 Striking Handwraps of Mighty Blows","Chain Mail"],"flavor":"<p>In rough Akitonian cities like Seldo, shobhad bruisers and fist-fighters act as protection for businesses and enforcers for crime bosses. Shobhad enforcers are more rare and far more dangerous. In the wilds of Akiton, shobhad enforcers protect wealthy caravans using combat techniques honed and proven over multiple generations to devastate any creature that might mistake the caravan as an attractive target for a raid. \"Enforcer\" is a loose translation of a word in the Shobhad language that is only granted to a warrior who has proven themselves in combat against one of the deadly threats of the Akitonian desert, such as gluttonworms or ikeshti riveners. Every enforcer is a battle-tested veteran with the scars to prove their prowess.</p>\n<hr>\n<p>These four-armed humanoids often live as nomads on Akiton. Self-sufficient and able to construct the equipment they need to survive from natural materials, shobhads traditionally avoid large cities and the smaller people of the planet, except to engage in trade. Some shobhads eschew these traditions, finding life in urban centers to be more appealing. Rifts between these shobhads and those who continue to lead nomadic lives in the Akitonian wilderness sometimes lead to clashes when members of the two societies meet.</p>\n<p>Shobhads are highly sought after for their martial expertise, unparalleled knowledge of Akiton's wilds, and unbreakable codes of honor. These warriors may operate independently, in their traditional clans, or in modern mercenary companies that blend ancestral traditions with the needs of modern military freelancers.</p>","abilities":[{"n":"Four-Armed","a":null,"c":"interaction","t":[],"f":"","d":"<p>Shobhad enforcers have four powerful arms. They can Interact with and manipulate objects or perform combat maneuvers that require a free hand such as grabbing or tripping, even while wielding a two-handed weapon or carrying an object in two hands.</p>"},{"n":"Attack of Opportunity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Ferocity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> The monster is reduced to 0 HP.</p>\n<hr>\n<p><strong>Effect</strong> The monster avoids being knocked out and remains at 1 HP, but its Wounded value increases by 1. When it is Wounded 3, it can no longer use this ability</p></p>"},{"n":"Brutal Blows","a":"2","c":"offensive","t":[],"f":"","d":"<p><strong>Requirements</strong> The shobhad enforcer has at least two free hands</p>\n<hr>\n<p><strong>Effect</strong> The shobhad enforcer makes a fist Strike against an adjacent creature. If the Strike hits, the enforcer automatically Grapples its target and makes a second fist Strike with the following success conditions.</p>\n<p>The second Strike applies the enforcer's multiple attack penalty normally.</p>\n<hr>\n<p><strong>Critical Success</strong> The target is Stunned 1, and Stupefied 2 for 1 round.</p>\n<p><strong>Success</strong> The target is Stupefied 1 for 1 round.</p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/shobhad-sniper":{"lang":["Akitonian","Shobhad"],"gear":["Shobhad Longrifle","+2 Striking Handwraps of Mighty Blows","Leather Armor"],"flavor":"<p>Enemies rarely see a shobhad sniper before the deadly blast of their powerful rifles snatches away the offender's life. Selected from among the most talented enforcers after proving themselves in combat, shobhad snipers learn how to cross the desert sands undetected, combine their powerful ranged weapons with close-combat techniques, and survive Akiton's freezing nights for weeks on end while scouting potential settlements or enemy strongholds.</p>\n<hr>\n<p>These four-armed humanoids often live as nomads on Akiton. Self-sufficient and able to construct the equipment they need to survive from natural materials, shobhads traditionally avoid large cities and the smaller people of the planet, except to engage in trade. Some shobhads eschew these traditions, finding life in urban centers to be more appealing. Rifts between these shobhads and those who continue to lead nomadic lives in the Akitonian wilderness sometimes lead to clashes when members of the two societies meet.</p>\n<p>Shobhads are highly sought after for their martial expertise, unparalleled knowledge of Akiton's wilds, and unbreakable codes of honor. These warriors may operate independently, in their traditional clans, or in modern mercenary companies that blend ancestral traditions with the needs of modern military freelancers.</p>","abilities":[{"n":"Four-Armed","a":null,"c":"interaction","t":[],"f":"","d":"<p>Shobhad enforcers have four powerful arms. They can Interact with and manipulate objects or perform combat maneuvers that require a free hand such as grabbing or tripping, even while wielding a two-handed weapon or carrying an object in two hands.</p>"},{"n":"Four-Armed","a":null,"c":"interaction","t":[],"f":"","d":"<p>Shobhad enforcers have four powerful arms. They can Interact with and manipulate objects or perform combat maneuvers that require a free hand such as grabbing or tripping, even while wielding a two-handed weapon or carrying an object in two hands.</p>"},{"n":"Attack of Opportunity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Ferocity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> The monster is reduced to 0 HP.</p>\n<hr>\n<p><strong>Effect</strong> The monster avoids being knocked out and remains at 1 HP, but its Wounded value increases by 1. When it is Wounded 3, it can no longer use this ability</p></p>"},{"n":"Sniper's Devastation","a":"3","c":"offensive","t":[],"f":"","d":"<p>The shobhad sniper makes a fist Strike against a Medium or smaller creature. If this attack is successful, the shobhad sniper deals no damage, but they immediately Grab and throw their target up to 30 feet in a direction of their choice and then make a ranged Strike with their longrifle against the target, after which the target falls Prone in the designated location.</p>\n<p>As normal, the creature doesn't take any additional falling damage from the throw.</p>"},{"n":"Sniping Shot","a":"2","c":"offensive","t":[],"f":"","d":"<p>The shobhad sniper makes a Strike with their longrifle, gaining a +2 circumstance bonus to this Strike's attack roll and ignoring the target's concealment.</p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/sicklehand-construct":{"gear":["Wooden Sickle (2)"],"abilities":[{"n":"Critical Vulnerability","a":null,"c":"defensive","t":[],"f":"","d":"<p>A critical hit damages the construct's controls, making it Clumsy 1 until repaired. Additional critical hits increase this value, up to Clumsy 4.</p>"},{"n":"Ridden Construct","a":null,"c":"defensive","t":[],"f":"","d":"<p>The construct is piloted by a Leaf Leshy who can be targeted separately but has greater cover. The leshy can't take actions of their own while inside the construct, other than to leave it, which takes 1 minute.</p>"},{"n":"Menacing Sickles","a":null,"c":"offensive","t":[],"f":"","d":"<p>The construct deals an additional 1d4 precision damage to Off-Guard or Prone creatures.</p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/silverfish-swarm":{"flavor":"<p>It's uncommon for silverfish to congregate in sufficient numbers to constitute a swarm, but forgotten libraries or similar out-of-the-way places might harbor a multitude of the voracious pests.</p>\n<hr>\n<p>A common pest with a silvery carapace and an undulating, fishlike scuttle, the nocturnal silverfish infests homes and libraries throughout Golarion. These insects aren't typically dangerous, but their tendency to devour books and clothing often puts them at odds with larger creatures.</p>","abilities":[{"n":"Voracious Consumption","a":null,"c":"interaction","t":[],"f":"","d":"<p>Action 1 minute</p>\n<p>A silverfish swarm consumes up to 1 Bulk of paper, cloth, or similar material. It can consume up to 4 Bulk each day.</p>"},{"n":"Swarm Mind","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>This monster doesn't have a single mind (typically because it's a swarm of smaller creatures), and is immune to mental effects that target only a specific number of creatures. It is still subject to mental effects that affect all creatures in an area.</p></p>"},{"n":"Swarming Bites","a":"1","c":"offensive","t":[],"f":"","d":"<p>Each enemy in the silverfish swarm's space takes 1d4 piercing damage (DC 14 basic Fortitude save). A creature that fails its save is Sickened 1.</p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/skartitch-chip-tooth":{"lang":["Akitonian","Shobhad"],"lore":[["Engineering Lore",27],["Underworld Lore",29]],"gear":["Crossbow","+2 Striking Handwraps of Mighty Blows","Leather Armor","Disintegration Bolt (3)","Bolts (10)"],"abilities":[{"n":"Nimble Dodge","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Requirements</strong> Skartitch can't use this reaction while encumbered</p>\n<p><strong>Trigger</strong> Skartitch is hit or critically hit by an attack made by a creature she can see</p>\n<hr>\n<p><strong>Effect</strong> Skartitch gains a +2 circumstance bonus to her Armor Class against the triggering attack.</p>"},{"n":"Cunning Discernment","a":"1","c":"offensive","t":[],"f":"","d":"<p>Skartitch attempts a Recall Knowledge check against an opponent using the standard DC for a creature of that level. On a success, that opponent is Off-Guard against Skartitch's attacks until the start of her next turn; on a critical success, the opponent is off-guard against Skartitch's attacks for 1 minute.</p>"},{"n":"Deadly Deception","a":"2","c":"offensive","t":[],"f":"","d":"<p>Skartitch attempts a Deception check to Feint against an opponent she can see. On a success, Skartitch can immediately Strike with one unarmed attack and one ranged weapon attack against the target. The ranged attack does not trigger reactions from the target of the Feint.</p>\n<p>Both of these attacks count toward her multiple attack penalty, but do not apply the penalty until both attacks are completed.</p>"},{"n":"Sneak Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>Skartitch deals an extra 4d6 precision damage to Off-Guard creatures.</p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/slana":{"lang":["Common","Fey"],"notes":{"hp":"fast healing 20","speed":"Freedom of Movement"},"flavor":"<p>The rolling thunder before the rain provides the massive, leonine humanoids known as slanas with a tremendous power. These solitary and nomadic creatures primarily dwell in the jungles and savannas of the Mwangi Expanse, but they can range into nearby areas in search of prey or when drawn by strange primal forces only slanas can recognize. Slanas view each other as rivals who test each other's prowess, so when drawn together by this strange calling they nearly always fight to the death. A slana's roar echoes like thunder across the countryside, and denizens of the Mwangi fear a slana's approach whenever an oncoming storm's thunder seems more ferocious than its rain.</p>","abilities":[{"n":"Constant Spells","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>A constant spell affects the monster without the monster needing to cast it, and its duration is unlimited. If a constant spell gets counteracted, the monster can reactivate it by spending the normal spellcasting actions the spell requires.</p></p>"},{"n":"Fast Healing 20","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A monster with this ability regains the given number of Hit Points each round at the beginning of its turn.</p></p>"},{"n":"Great Roar","a":"2","c":"offensive","t":["primal","sonic"],"f":"","d":"<p>The slana emits a deafening roar. All creatures within a 100-foot cone take 16d8 sonic damage (DC 44 basic Reflex saving throw). On a failed save, a creature is also Deafened for 1 minute and Stunned 1 (or deafened permanently and Stunned 3 on a critical failure). The slana can't use Great Roar again for 1d4 rounds.</p>"},{"n":"Pounce","a":"1","c":"offensive","t":[],"f":"","d":"<p>The slana Strides and makes a Strike at the end of that movement. If the slana began this action Hidden, they remain hidden until after the ability's Strike.</p>"},{"n":"Thunder Trap","a":null,"c":"offensive","t":[],"f":"","d":"<p>A creature hit by the slana's thunderclap attack is Immobilized and held in place by reverberations of sound until it Escapes or Forces Open the bonds of thunder that constrain it (DC 44). The target is Deafened as long as it is immobilized by a thunder trap.</p>"},{"n":"Improved Grab","a":"f","c":"offensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> The monster's last action was a successful Strike that lists Improved Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with as a free action. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Improved Grab as an action and choose one creature it's grabbing or restraining with an appendage that has Improved Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-4-secrets-of-the-temple-city/soul-swarm":{"lang":["Common"],"notes":{"hp":"16 squares (156 = 12 squares, 78 = 8 squares)"},"abilities":[{"n":"Form Up","a":"1","c":"interaction","t":[],"f":"","d":"<p><p>The troop chooses one of the squares it currently occupies and redistributes its squares to any configuration in which all squares are contiguous and within 15 feet of the chosen square. The troop can't share its space with other creatures.</p></p>"},{"n":"Constant Spells","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>A constant spell affects the monster without the monster needing to cast it, and its duration is unlimited. If a constant spell gets counteracted, the monster can reactivate it by spending the normal spellcasting actions the spell requires.</p></p>"},{"n":"Frightful Presence","a":null,"c":"defensive","t":["aura","emotion","fear","mental"],"f":"","d":"<p>60 feet. DC 30 Will</p>\n<hr>\n<p><p>A creature that first enters the area must attempt a Will save.</p>\n<p>Regardless of the result of the saving throw, the creature is temporarily immune to this monster's Frightful Presence for 1 minute.</p>\n<hr>\n<p><strong>Critical Success</strong> The creature is unaffected by the presence.</p>\n<p><strong>Success</strong> The creature is Frightened 1.</p>\n<p><strong>Failure</strong> The creature is Frightened 2.</p>\n<p><strong>Critical Failure</strong> The creature is Frightened 4.</p></p>"},{"n":"Troop Defenses","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>Troops are composed of many individuals, represented by four \"segments\" on a battle grid. Each segment is 10 feet on each side and as tall as the individual members of the troop. Segments must remain contiguous. Each one has to share at least 5 feet of one of its edges with another segment—being adjacent on a diagonal isn't sufficient! You can measure flanking, cover, and the like using the center of any segment.</p>\n<p>A troop has two Hit Point thresholds in its HP entry and loses segments as it crosses thresholds. Typically, the higher threshold is at 2/3 of the troop's maximum Hit Points and the lower is at 1/3 of its maximum. Once the troop drops below the higher threshold, it loses one segment, leaving three segments (12 squares) remaining and setting the first threshold as the troop's new maximum Hit Points. This repeats when the troop drops below the lower threshold, leaving two segments (8 squares). At 0 Hit Points, the troop disperses entirely, with the few remaining members surrendering, Fleeing, or easily dispatched, as determined by the GM. Typically the creature who caused the troop to lose a segment decides which to remove, or the GM decides when a specific creature wasn't responsible. To restore lost segments and maximum Hit Points, a troop needs to spend downtime to use long-term treatment on casualties or recruit new members to replace the fallen.</p>\n<p>Troops are typically immune to non-damaging effects that target a single creature, such as a Charm spell or the Demoralize action. An ability that can target 5 or more creatures can target an entire segment, increasing to two segments if it can target 10 or more creatures and to the entire troop if it can target 20 or more creatures. An ability that affects all creatures in a certain range affects all segments in range (make any checks or saves separately for each segment). As examples, an 8th rank <em>charm</em> spell (with 10 targets) can affect two segments, and an ability that Demoralizes all creatures within 30 feet of you would affect all segments that are fully within that range. A non-damaging ability that would prevent a segment from acting, cause them to flee, or otherwise make them unable to function as part of the troop for a round or more removes the segment entirely. The troop loses a number of HP required to bring it to the next threshold. If an ability both deals damage and has a non-damaging effect, apply the damage then the rest of the effect.</p></p>"},{"n":"Cosmic Explosion","a":"2","c":"offensive","t":[],"f":"","d":"<p>The soul swarm unleashes a blast of burning sunlight or moonlight, dealing 4d8+6 fire damage to creatures in a 10-foot burst within 20 feet (DC 30 basic Reflex save). When the soul swarm is reduced to 8 or fewer squares, this decreases to a 5-foot burst.</p>"},{"n":"Soul Grasp","a":"1","c":"offensive","t":[],"f":"once per round","d":"<p>1 to 3</p>\n<p><strong>Frequency</strong> once per round</p><hr><p><strong>Effect</strong> The soul swarm reaches out and tries to tear at the spiritual energy of enemies within 5 feet (DC 32 basic Reflex save). The soul swarm can choose to deal slashing damage as it cuts away at a creature, fire damage as it burns other souls away, or void damage as it attempts to unmake a soul. The damage depends on the number of actions.</p>\n<p>1 2d6+1 untyped damage</p>\n<p>2 4d6+11 untyped damage</p>\n<p>3 6d6+11 untyped damage</p>"},{"n":"Troop Movement","a":null,"c":"offensive","t":[],"f":"","d":"<p>Whenever the soul swarm Strides, the soul swarm first Forms Up as a free action to condense into a 20-foot-by-20-foot area (minus any missing squares), then moves. This works just like a Gargantuan creature moving; for instance, if any square of the soul swarm enters difficult terrain, the extra movement cost applies to the whole soul swarm.</p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/sparkeater":{"notes":{"hp":"void healing","per":"soulsense 60 feet"},"flavor":"<p>Raveners require a steady diet of souls, and a ravener that's unable to feed for too long eventually cannibalizes their own soul. Should a ravener's soul ward ever be reduced to 0 Hit Points by hunger while the ravener has more than 1 Hit Point (see Soul Ward), they lose all traces of their former identity and descend into a feral, nearly mindless state. Even if a ravener husk later consumes soul energy, the transformation can be reversed only via Ravenous Repast.</p>\n<hr>\n<p>Though their lifespans can measure in millennia, all dragons must eventually perish. While many do so on the blades or under the spells of dragonslayers, some manage to outlast their enemies and must, in time, face the truth that awaits all living creatures at the end of their natural lifespan. As with many other creatures, some dragons respond to such looming reminders of their own mortality poorly, and the particularly prideful or wrathful of their kind often lash out in anger when confronted by this grim truth. Peace and acceptance may find some dragons, but the most stubborn of their ilk (and invariably the most wicked) may pursue a different answer to the problem. These dragons seek out sinister rites that can transform them into undead creatures known as raveners.</p>\n<p>A ravener's flesh is stripped away as part of the transformation, leaving only their skeleton. What they lose in flesh, however, the dragon gains in soul-rending power, as their raw spiritual energy forms a protective barrier around their skeleton, keeping it intact and allowing flight with now-skeletal wings. This new existence is not so easy to maintain as other forms of undeath, however, and the ravener must feed regularly on the souls of living creatures to power their profane metabolism. This hunger is much greater than that of a living dragon, so raveners are forced to relocate regularly, traveling to fresh hunting grounds each time they strip their current home of prey. A ravener may depopulate whole regions at a time in order to sate their endless hunger for souls, lest they lose much of their power and become a ravener husk.</p>","abilities":[{"n":"Failed Ravener","a":null,"c":"interaction","t":[],"f":"","d":"<p>Sparkeater has the same statistics as a normal Ravener Husk but is Large instead of Gargantuan. His melee Strikes have a reach of only 5 feet, and he lacks the Ravenous Repast ability, as he was never a ravener in the first place.</p>"},{"n":"Soulsense 60 feet","a":null,"c":"interaction","t":[],"f":"","d":"<p>Sparkeater senses the spiritual essence of living and undead creatures within the listed range. Creatures whose material bodies are one unit with their souls, like celestials and fiends, appear brighter to this sense.</p>"},{"n":"Boneshatter","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> Sparkeater takes any amount of bludgeoning damage</p>\n<hr>\n<p><strong>Effect</strong> Sparkeater's brittle bones shatter, spraying bone shards everywhere. Every creature within a 10-foot emanation of Sparkeater takes 7d6 piercing damage (DC 31 basic Reflex save).</p>"},{"n":"Frightful Presence","a":null,"c":"defensive","t":["aura","emotion","fear","mental"],"f":"","d":"<p>90 feet. DC 31 Will</p>\n<hr>\n<p><p>A creature that first enters the area must attempt a Will save.</p>\n<p>Regardless of the result of the saving throw, the creature is temporarily immune to this monster's Frightful Presence for 1 minute.</p>\n<hr>\n<p><strong>Critical Success</strong> The creature is unaffected by the presence.</p>\n<p><strong>Success</strong> The creature is Frightened 1.</p>\n<p><strong>Failure</strong> The creature is Frightened 2.</p>\n<p><strong>Critical Failure</strong> The creature is Frightened 4.</p></p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Breath Weapon","a":"2","c":"offensive","t":["divine","void"],"f":"","d":"<p>Sparkeater breathes a torrent of void energy that deals 16d6 void damage in a 40-foot cone (DC 34 basic Reflex save).</p>\n<p>He can't use Breath Weapon again for 1d4 rounds.</p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/spawn-of-taon":{"lang":["Common","Necril"],"notes":{"hp":"void healing"},"flavor":"<p>The weight of murder wears heavy on the soul. With souls marked by a lifetime of dealing death, these killers, whether mass murderers, bloodthirsty soldiers, or sadistic executioners, sometimes do not let judgment and lawful execution stanch their slaying sprees. When such individuals are brought to justice, they may rise after death as mohrgs to continue their ruinous work.</p>\n<p>Drawn to others of their kind, mohrgs prefer to hunt in small groups, occasionally in partnership with weaker free-willed undead such as shadows and wights. They seek out weak prey and revel in causing drawn-out suffering. Some mohrgs haunt locations they favored in life, reenacting old crimes on new victims. They may even skulk about in public, wearing rags, cloaks, or freshly harvested skins to hide their nature. The most dangerous mohrgs are those who grow powerful enough to no longer fear being struck down again and openly assault settlements in an attempt to turn living towns into mass graves.</p>\n<p>Since those slain by a mohrg rise soon thereafter as mohrg spawn, the murders of a mohrg rarely go unnoticed for long, even when they take extra care to prey only on a society's dregs. Since mohrg spawn remain under a mohrg's control, a canny mohrg might order its spawn to remain in hiding to keep its presence secret until a point where it feels confident unleashing its undead army upon a doomed settlement.</p>\n<p>Mohrgs retain a twisted sentimentality for the crimes of their mortal life, seeking out trinkets that remind them of favorite murders. When not out hunting, mohrgs arrange their mementos into disturbing shrines. Often, these trinkets are valuable objects, and might even provide important clues to ongoing mysteries.</p>","abilities":[{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Paralysis","a":null,"c":"offensive","t":["incapacitation","occult"],"f":"","d":"<p>A living creature hit by a mohrg's tongue Strike must succeed at a DC 30 Fortitude save or become Paralyzed. The creature can attempt a new save at the end of each of its turns, and the DC cumulatively decreases by 1 on each attempt.</p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/spellskein":{"lang":["Common","(can't speak any language)"],"flavor":"<p>Magic can be used for many purposes-creating objects, summoning creatures, and manipulating the elements. Usually when a ritual is cast, the outcome is reliable and predictable, but sometimes magic takes unexpected turns and a spell's energy lands in unintended places.</p>\n<p>Spellskeins are scraps of fabric and paper infused with magic and brought to life. Once animated, they fold themselves into different shapes, changing both their appearance and their abilities based on their configuration. Spellskeins are only rarely aggressive and sometimes downright timid, but most have a playful streak.</p>\n<p>Though they are often made accidentally out of magical leakage from rituals, some ritualists intentionally create spellskeins to serve as magical toys or animated decor. These planned spellskeins tend to be more obedient and less mischievous than their accidental counterparts, following commands or routines set by their creators even after said creators are long gone.</p>\n<p>Scrap pieces torn from the body of a spellskein sometimes animate as ever smaller, more mischievous constructs, which usually dart away to hide until it's safe to come out and cause trouble.</p>","abilities":[{"n":"Collapse","a":null,"c":"interaction","t":[],"f":"","d":"<p>The spellskein can collapse flat to the ground to Hide; it can attempt to Hide even if it doesn't have any cover or concealment.</p>"},{"n":"Crane Glide","a":"1","c":"interaction","t":[],"f":"","d":"<p><strong>Requirements</strong> The spellskein is folded into its crane shape</p>\n<hr>\n<p><strong>Effect</strong> The spellskein gains a 25-foot fly Speed until the beginning of its next turn.</p>"},{"n":"Frog Hop","a":"2","c":"interaction","t":[],"f":"","d":"<p><strong>Requirements</strong> The spellskein is folded into its frog shape</p>\n<hr>\n<p><strong>Effect</strong> The spellskein Leaps 15 feet horizontally or vertically and gains a 10-foot climb Speed until the beginning of its next turn.</p>"},{"n":"Refold","a":"1","c":"interaction","t":[],"f":"","d":"<p>The spellskein folds itself into a crane, frog, or lizard shape, as it chooses.</p>"},{"n":"Lizard Frill","a":"1","c":"offensive","t":["arcane","fear","mental"],"f":"","d":"<p><strong>Requirements</strong> The spellskein is folded into its lizard shape</p>\n<hr>\n<p><strong>Effect</strong> The spellskein puffs out its cloth frills and shakes them from side to side to look fierce. The first creature hit by its sharp edge Strike before the start of its next turn must succeed on a DC 14 Will save or become Frightened 1 (Frightened 2 on a critical failure).</p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/spellskein-consecrate":{"lang":["Common","(can't speak any language)"],"flavor":"<p>Spellskeins created during Consecrate rituals have a religious symbol form and can use the one-action activity anoint while in that form.</p>\n<hr>\n<p>Magic can be used for many purposes-creating objects, summoning creatures, and manipulating the elements. Usually when a ritual is cast, the outcome is reliable and predictable, but sometimes magic takes unexpected turns and a spell's energy lands in unintended places.</p>\n<p>Spellskeins are scraps of fabric and paper infused with magic and brought to life. Once animated, they fold themselves into different shapes, changing both their appearance and their abilities based on their configuration. Spellskeins are only rarely aggressive and sometimes downright timid, but most have a playful streak.</p>\n<p>Though they are often made accidentally out of magical leakage from rituals, some ritualists intentionally create spellskeins to serve as magical toys or animated decor. These planned spellskeins tend to be more obedient and less mischievous than their accidental counterparts, following commands or routines set by their creators even after said creators are long gone.</p>\n<p>Scrap pieces torn from the body of a spellskein sometimes animate as ever smaller, more mischievous constructs, which usually dart away to hide until it's safe to come out and cause trouble.</p>","abilities":[{"n":"Collapse","a":null,"c":"interaction","t":[],"f":"","d":"<p>The spellskein can collapse flat to the ground to Hide; it can attempt to Hide even if it doesn't have any cover or concealment.</p>"},{"n":"Crane Glide","a":"1","c":"interaction","t":[],"f":"","d":"<p><strong>Requirements</strong> The spellskein is folded into its crane shape</p>\n<hr>\n<p><strong>Effect</strong> The spellskein gains a 25-foot fly Speed until the beginning of its next turn.</p>"},{"n":"Frog Hop","a":"2","c":"interaction","t":[],"f":"","d":"<p><strong>Requirements</strong> The spellskein is folded into its frog shape</p>\n<hr>\n<p><strong>Effect</strong> The spellskein Leaps 15 feet horizontally or vertically and gains a 10-foot climb Speed until the beginning of its next turn.</p>"},{"n":"Refold","a":"1","c":"interaction","t":[],"f":"","d":"<p>The spellskein folds itself into a crane, frog, lizard, or religious symbol shape, as it chooses.</p>"},{"n":"Anoint","a":"1","c":"defensive","t":[],"f":"","d":"<p><strong>Requirements</strong> The spellskein is folded into its religious symbol form.</p>\n<hr>\n<p><strong>Effect</strong> One creature within 10 feet gains a +1 status bonus to saving throws for one round.</p>"},{"n":"Lizard Frill","a":"1","c":"offensive","t":["arcane","fear","mental"],"f":"","d":"<p><strong>Requirements</strong> The spellskein is folded into its lizard shape</p>\n<hr>\n<p><strong>Effect</strong> The spellskein puffs out its cloth frills and shakes them from side to side to look fierce. The first creature hit by its sharp edge Strike before the start of its next turn must succeed on a DC 14 Will save or become Frightened 1 (Frightened 2 on a critical failure).</p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/spellskein-control-weather":{"lang":["Common","(can't speak any language)"],"flavor":"<p>Spellskeins created during Control Weather rituals have a storm cloud form and can gain the following attack in that form.</p>\n<hr>\n<p>Magic can be used for many purposes-creating objects, summoning creatures, and manipulating the elements. Usually when a ritual is cast, the outcome is reliable and predictable, but sometimes magic takes unexpected turns and a spell's energy lands in unintended places.</p>\n<p>Spellskeins are scraps of fabric and paper infused with magic and brought to life. Once animated, they fold themselves into different shapes, changing both their appearance and their abilities based on their configuration. Spellskeins are only rarely aggressive and sometimes downright timid, but most have a playful streak.</p>\n<p>Though they are often made accidentally out of magical leakage from rituals, some ritualists intentionally create spellskeins to serve as magical toys or animated decor. These planned spellskeins tend to be more obedient and less mischievous than their accidental counterparts, following commands or routines set by their creators even after said creators are long gone.</p>\n<p>Scrap pieces torn from the body of a spellskein sometimes animate as ever smaller, more mischievous constructs, which usually dart away to hide until it's safe to come out and cause trouble.</p>","abilities":[{"n":"Collapse","a":null,"c":"interaction","t":[],"f":"","d":"<p>The spellskein can collapse flat to the ground to Hide; it can attempt to Hide even if it doesn't have any cover or concealment.</p>"},{"n":"Crane Glide","a":"1","c":"interaction","t":[],"f":"","d":"<p><strong>Requirements</strong> The spellskein is folded into its crane shape</p>\n<hr>\n<p><strong>Effect</strong> The spellskein gains a 25-foot fly Speed until the beginning of its next turn.</p>"},{"n":"Frog Hop","a":"2","c":"interaction","t":[],"f":"","d":"<p><strong>Requirements</strong> The spellskein is folded into its frog shape</p>\n<hr>\n<p><strong>Effect</strong> The spellskein Leaps 15 feet horizontally or vertically and gains a 10-foot climb Speed until the beginning of its next turn.</p>"},{"n":"Refold","a":"1","c":"interaction","t":[],"f":"","d":"<p>The spellskein folds itself into a crane, frog, lizard, or cloud shape, as it chooses.</p>"},{"n":"Lizard Frill","a":"1","c":"offensive","t":["arcane","fear","mental"],"f":"","d":"<p><strong>Requirements</strong> The spellskein is folded into its lizard shape</p>\n<hr>\n<p><strong>Effect</strong> The spellskein puffs out its cloth frills and shakes them from side to side to look fierce. The first creature hit by its sharp edge Strike before the start of its next turn must succeed on a DC 14 Will save or become Frightened 1 (Frightened 2 on a critical failure).</p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/spellskein-heroes-feast":{"lang":["Common","(can't speak any language)"],"flavor":"<p>Spellskeins created during Fortifying Brew rituals have a teapot form and can use the two-action activity serve tea while in that form.</p>\n<hr>\n<p>Magic can be used for many purposes-creating objects, summoning creatures, and manipulating the elements. Usually when a ritual is cast, the outcome is reliable and predictable, but sometimes magic takes unexpected turns and a spell's energy lands in unintended places.</p>\n<p>Spellskeins are scraps of fabric and paper infused with magic and brought to life. Once animated, they fold themselves into different shapes, changing both their appearance and their abilities based on their configuration. Spellskeins are only rarely aggressive and sometimes downright timid, but most have a playful streak.</p>\n<p>Though they are often made accidentally out of magical leakage from rituals, some ritualists intentionally create spellskeins to serve as magical toys or animated decor. These planned spellskeins tend to be more obedient and less mischievous than their accidental counterparts, following commands or routines set by their creators even after said creators are long gone.</p>\n<p>Scrap pieces torn from the body of a spellskein sometimes animate as ever smaller, more mischievous constructs, which usually dart away to hide until it's safe to come out and cause trouble.</p>","abilities":[{"n":"Collapse","a":null,"c":"interaction","t":[],"f":"","d":"<p>The spellskein can collapse flat to the ground to Hide; it can attempt to Hide even if it doesn't have any cover or concealment.</p>"},{"n":"Crane Glide","a":"1","c":"interaction","t":[],"f":"","d":"<p><strong>Requirements</strong> The spellskein is folded into its crane shape</p>\n<hr>\n<p><strong>Effect</strong> The spellskein gains a 25-foot fly Speed until the beginning of its next turn.</p>"},{"n":"Frog Hop","a":"2","c":"interaction","t":[],"f":"","d":"<p><strong>Requirements</strong> The spellskein is folded into its frog shape</p>\n<hr>\n<p><strong>Effect</strong> The spellskein Leaps 15 feet horizontally or vertically and gains a 10-foot climb Speed until the beginning of its next turn.</p>"},{"n":"Refold","a":"1","c":"interaction","t":[],"f":"","d":"<p>The spellskein folds itself into a crane, frog, lizard, or teapot shape, as it chooses.</p>"},{"n":"Serve Tea","a":"2","c":"interaction","t":[],"f":"","d":"<p>A living creature that drinks the tea with an Interact action regains 1d4 healing Hit Points and is temporarily immune for 10 minutes.</p>\n<p>Unconsumed tea disappears at the beginning of tthe spellskein's next turn.</p>"},{"n":"Lizard Frill","a":"1","c":"offensive","t":["arcane","fear","mental"],"f":"","d":"<p><strong>Requirements</strong> The spellskein is folded into its lizard shape</p>\n<hr>\n<p><strong>Effect</strong> The spellskein puffs out its cloth frills and shakes them from side to side to look fierce. The first creature hit by its sharp edge Strike before the start of its next turn must succeed on a DC 14 Will save or become Frightened 1 (Frightened 2 on a critical failure).</p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/spider-summoning-rune":{"description":"<p>An Invisible rune on the floor summons a Goliath Spider when disturbed by someone who isn't wearing Norgorber's religious symbol.</p>","disable":"<p>DC 34 Thievery (master) to erase the rune or Dispel Magic (6th rank; counteract DC 36) to dispel the rune.</p>","reset":"<p>The trap resets after 24 hours.</p>","stealthNote":"<p>(master)</p>","abilities":[{"n":"Summon Animal","a":"r","c":"offensive","t":["divine","summon"],"f":"","d":"<p><strong>Trigger</strong> A creature that isn't wearing a religious symbol of Norgorber enters the area above the rune</p><hr><p><strong>Effect</strong> The trap summons a Goliath Spider. The goliath spider rolls initiative and remains for 2d6 rounds, after which the spell ends and the spider disappears. The spider also disappears if someone disables the trap before the duration expires. Unlike most summoned creatures, the goliath spider can use 3 actions each round and can use reactions.</p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/ssumzili":{"lang":["Aklo","Common","Fey"],"notes":{"speed":"puddle stride"},"flavor":"<p>Ssumzilis are lanky, murderous fey who delight in the thrill of the hunt. They are particularly skilled/adept at stalking their prey in the rain and most commonly reside in rainforests and coastal regions, where frequent rain provides ample opportunity to hunt. Camouflaged by their cloud-gray skin, ssumzilis often compete in tests of stealth when hunting in groups, taking particular delight in approaching their quarry as closely as possible without being observed.</p>","abilities":[{"n":"Deluge Vision","a":null,"c":"interaction","t":[],"f":"","d":"<p>A ssumzili ignores sensory difficulties caused by rain.</p>"},{"n":"Precipitation Camouflage","a":null,"c":"interaction","t":[],"f":"","d":"<p>A ssumzili can Hide and Sneak in rainfall, even if it doesn't have cover.</p>"},{"n":"Constant Spells","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>A constant spell affects the monster without the monster needing to cast it, and its duration is unlimited. If a constant spell gets counteracted, the monster can reactivate it by spending the normal spellcasting actions the spell requires.</p></p>"},{"n":"Standing Water","a":null,"c":"defensive","t":["aura","primal"],"f":"","d":"<p>10 feet. When it rains, the ground near a ssumzili becomes slick. When raining, all terrain within 10 feet of a ssumzili is slippery, with the effects of Grease (DC 29). Ssumzilis are immune to this effect.</p>"},{"n":"Puddle Stride","a":null,"c":"offensive","t":[],"f":"","d":"<p>A ssumzili ignores difficult terrain caused by rain, such as puddles or wet rocks.</p>"},{"n":"Sneak Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>A ssumzili deals an additional 2d6 precision damage precision damage to Off-Guard creatures.</p>"},{"n":"Soaking Strike","a":"2","c":"offensive","t":[],"f":"","d":"<p>The ssumzili makes a melee Strike. If the Strike damages the target, the target must also attempt a DC 32 Fortitude save.</p>\n<hr>\n<p><strong>Critical Success</strong> The creature is unaffected.</p>\n<p><strong>Success</strong> The creature becomes soaked, causing them to treat the environmental temperature as one step colder (mild to severe, severe to extreme, and so on) until they dry off.</p>\n<p><strong>Failure</strong> As success, and the creature is Fatigued for 1 minute.</p>\n<p><strong>Critical Failure</strong> As failure but the fatigue lasts until the target gets a full night's rest.</p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/stinger-ward-trap":{"description":"<p>A ghostly stinger appears in the air and jabs at anyone moving through the opening.</p>","disable":"<p>DC 36 Thievery (master) to prevent the ghostly stinger from forming or Dispel Magic (6th rank; counteract DC 34).</p>","reset":"<p>The trap resets after 24 hours.</p>","stealthNote":"<p>(expert)</p>","abilities":[{"n":"Deadly Sting","a":"r","c":"offensive","t":["divine","poison"],"f":"","d":"<p><strong>Trigger</strong> A creature who isn't wearing a religious symbol of Norgorber moves the trapdoor</p><hr>\n<p><strong>Effect</strong> The trap targets the creature with <em>Purple Worm sting</em> (DC 30 Fortitude save).</p>\n<p><strong>Maximum Duration</strong> 6 rounds</p>\n<p><strong>Stage 1</strong> 5d6 poison damage and Enfeebled 2 (1 round)</p>\n<p><strong>Stage 2</strong> 6d6 poison damage and enfeebled 2 (1 round)</p>\n<p><strong>Stage 3</strong> 8d6 poison damage and enfeebled 2 (1 round)</p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/stone-ghost":{"lang":["Common","Kholo","Petran"],"lore":[["Magaambya Lore",12]],"gear":["Morningstar","Sling","Leather Armor","Sling Bullets (10)"],"abilities":[{"n":"Stone Spirit","a":null,"c":"interaction","t":[],"f":"","d":"<p>Stone Ghost can pass through objects made of stone or soil, including walls. When inside an object, Stone Ghost can't perceive, attack, or interact with anything outside the object, and if he starts his turn inside an object, he is Slowed 1.</p>"},{"n":"Entombing Grasp","a":"2","c":"offensive","t":["earth","manipulate"],"f":"","d":"<p><strong>Requirements</strong> A foe within Stone Ghost's reach is standing on stone or soil</p>\n<hr>\n<p><strong>Effect</strong> Stone Ghost briefly extends his intangibility to a foe and drags or pounds them into the earth. He makes an Athletics vs. Fortitude DC check against the target's Fortitude DC. On a success, the foe is planted waist-deep in the ground and is Immobilized and Off-Guard until it Escapes. On a critical success, the foe is completely buried and must hold its breath until it is free or else start suffocating. A successful Escape returns the foe to its original square on the surface, or the closest unoccupied square.</p>"}]},"strength-of-thousands-bestiary/book-4-secrets-of-the-temple-city/sun-warrior-brigade":{"lang":["Common","Mzunu"],"notes":{"hp":"16 squares (144 = 12 squares, 72 = 8 squares)"},"abilities":[{"n":"Form Up","a":"1","c":"interaction","t":[],"f":"","d":"<p><p>The troop chooses one of the squares it currently occupies and redistributes its squares to any configuration in which all squares are contiguous and within 15 feet of the chosen square. The troop can't share its space with other creatures.</p></p>"},{"n":"Troop Defenses","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>Troops are composed of many individuals, represented by four \"segments\" on a battle grid. Each segment is 10 feet on each side and as tall as the individual members of the troop. Segments must remain contiguous. Each one has to share at least 5 feet of one of its edges with another segment—being adjacent on a diagonal isn't sufficient! You can measure flanking, cover, and the like using the center of any segment.</p>\n<p>A troop has two Hit Point thresholds in its HP entry and loses segments as it crosses thresholds. Typically, the higher threshold is at 2/3 of the troop's maximum Hit Points and the lower is at 1/3 of its maximum. Once the troop drops below the higher threshold, it loses one segment, leaving three segments (12 squares) remaining and setting the first threshold as the troop's new maximum Hit Points. This repeats when the troop drops below the lower threshold, leaving two segments (8 squares). At 0 Hit Points, the troop disperses entirely, with the few remaining members surrendering, Fleeing, or easily dispatched, as determined by the GM. Typically the creature who caused the troop to lose a segment decides which to remove, or the GM decides when a specific creature wasn't responsible. To restore lost segments and maximum Hit Points, a troop needs to spend downtime to use long-term treatment on casualties or recruit new members to replace the fallen.</p>\n<p>Troops are typically immune to non-damaging effects that target a single creature, such as a Charm spell or the Demoralize action. An ability that can target 5 or more creatures can target an entire segment, increasing to two segments if it can target 10 or more creatures and to the entire troop if it can target 20 or more creatures. An ability that affects all creatures in a certain range affects all segments in range (make any checks or saves separately for each segment). As examples, an 8th rank <em>charm</em> spell (with 10 targets) can affect two segments, and an ability that Demoralizes all creatures within 30 feet of you would affect all segments that are fully within that range. A non-damaging ability that would prevent a segment from acting, cause them to flee, or otherwise make them unable to function as part of the troop for a round or more removes the segment entirely. The troop loses a number of HP required to bring it to the next threshold. If an ability both deals damage and has a non-damaging effect, apply the damage then the rest of the effect.</p></p>"},{"n":"Frenetic Assault","a":"1","c":"offensive","t":[],"f":"once per round","d":"<p>1 to 3</p>\n<p><strong>Frequency</strong> once per round</p><hr><p><strong>Effect</strong> The members of the brigade wildly swing their weapons-primarily spears-in a frenzied attack at each enemy adjacent to the troop (DC 29 basic Reflex save). The damage depends on the number of actions.</p>\n<p>1 1d12+1 piercing damage</p>\n<p>2 2d12+11 piercing damage</p>\n<p>3 3d12+11 piercing damage</p>"},{"n":"Troop Movement","a":null,"c":"offensive","t":[],"f":"","d":"<p>Whenever the troop Strides, they first Form Up as a free action to condense into a 20-foot-by-20-foot area (minus any missing squares), then move up to their Speed. This works just like a Gargantuan creature moving; for instance, if any square of the troop enters difficult terrain, the extra movement cost applies to the whole troop.</p>"},{"n":"Troop Spellcasting","a":null,"c":"offensive","t":[],"f":"","d":"<p>When the sun warrior brigade Casts a Spell, its constituent members combine their efforts into casting a more powerful version of the spell than any one member could achieve alone. When Casting a Spell that has an area of a burst, cone, or line and doesn't have a duration, increase the area of that spell. Add 5 feet to the radius of a burst that normally has a radius of at least 10 feet (a burst with a smaller radius is not affected). Add 5 feet to the length of a cone or line that is normally 15 feet long or smaller, and add 10 feet to the length of a larger cone or line.</p>"},{"n":"Walkena's Radiance","a":"2","c":"offensive","t":["divine","fire","light"],"f":"","d":"<p>The brigade calls upon Walkena to burn and blind their foes. The sun warriors present their religious symbols and create a white-hot flash of light in a 45-foot cone. Creatures in the cone take 10d8 fire damage (DC 29 basic Fortitude save). Creatures that fail their save become Dazzled for 1 round. Creatures that critically fail become Blinded for 1 round instead. When the troop is reduced to 2 or fewer segments, this area decreases to a 20-foot cone.</p>"}]},"strength-of-thousands-bestiary/book-4-secrets-of-the-temple-city/sunburst-corpse":{"lang":["Common","(can't speak any language)"],"abilities":[{"n":"Blinding Aura","a":null,"c":"defensive","t":["aura","incapacitation","light","occult","visual"],"f":"","d":"<p>60 feet. The sunburst corpse sheds bright light. Any creature that starts its turn in the emanation must succeed at a DC 31 Fortitude save. If it fails, it's Blinded for 1 minute, and if it critically fails, it's blinded permanently. A creature that succeeds at its save is temporarily immune to this effect for 24 hours.</p>"},{"n":"Darkness Vulnerability","a":null,"c":"defensive","t":[],"f":"","d":"<p>A sunburst corpse is Sickened 1 while in areas of magical darkness. If the level of the magical darkness effect is at least half of the sunburst corpse's level (a 7th-rank effect against most sunburst corpses), the sunburst corpse is also Slowed 1 while in the area.</p>"},{"n":"Light Camouflage","a":null,"c":"defensive","t":[],"f":"","d":"<p>The sunburst corpse is Concealed in areas of natural bright light, such as due to sunlight or torches, even to creatures that can see clearly in bright light. Magical bright light and light from the sunburst corpse's blinding aura don't conceal the sunburst corpse.</p>"},{"n":"Constrict","a":"1","c":"offensive","t":[],"f":"","d":"<p>2d6+6 bludgeoning plus 2d8 fire and Residual Light, DC 34 basic Fortitude</p>\n<hr>\n<p><p>The monster deals the listed amount of damage to any number of creatures Grabbed or Restrained by it. Each of those creatures can attempt a basic Fortitude save with the listed DC.</p></p>"},{"n":"Nova Burst","a":"3","c":"offensive","t":["light","occult"],"f":"","d":"<p>The sunburst corpse intensifies its light and unleashes a burning blast of energy. It deals 12d8 fire damage to all creatures in a 20-foot emanation (DC 34 basic Fortitude save). A creature that fails its save becomes Dazzled until the end of its next turn. The sunburst corpse can't use Nova Burst again for 1d4 rounds, and its blinding aura becomes inactive during this time.</p>"},{"n":"Residual Light","a":null,"c":"offensive","t":["light","occult"],"f":"","d":"<p>When a sunburst corpse Strikes or Grapples a creature, some of the corpse's light clings to the creature for a moment. The creature must attempt a DC 34 Fortitude save. On a failure, the creature is Dazzled until the end of its next turn. On a critical failure, the creature is dazzled for 1 minute. A dazzled creature can use an Interact action to wick off the light and remove the dazzled condition.</p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/taapundo":{"lang":["Common","Fey"],"notes":{"per":"greensight","speed":"woodland stride"},"flavor":"<p>The First World still holds the first rough draft of many creatures in the Material Plane, but it's hard to tell what sort of creature the ta'apundo was ever intended to be. Its bark poses significant danger to metallic objects, as it converts any metal touching it into wood as fibrous and as flexible as its own body. Capricious and skittish, ta'apundos make friends easily but consider anyone who wields or wears metal to be a hated enemy.</p>","abilities":[{"n":"Greensight","a":null,"c":"defensive","t":[],"f":"","d":"<p>Vegetation doesn't impair a ta'apundo's vision and doesn't provide a creature cover or concealment from a ta'apundo.</p>"},{"n":"Lignification","a":"r","c":"defensive","t":["primal"],"f":"","d":"<p><strong>Trigger</strong> a non-cold iron metal object damages the ta'apundo</p><hr>\n<p><strong>Effect</strong> The ta'apundo emits a jolt of magic into the object, transforming it into wood with an unlimited duration. A thrown weapon, ammunition, or other unattended item automatically transforms; the wielder of an attended object can resist this effect with a successful DC 41 Fortitude save. Dispel Magic can end the effect. While a weapon is wood, the ta'apundo's resistance applies. Once transformed, a formerly metal item's Hardness and HP change to those of wood. This typically inflicts a -2 circumstance penalty to attack rolls made with metal weapons and a -2 circumstance penalty to AC for those wearing metal armor; the GM might determine a different penalty for a specific weapon or armor.</p>"},{"n":"Wood Resistance","a":null,"c":"defensive","t":["primal"],"f":"","d":"<p>A ta'apundo has resistance 20 against wooden objects and unarmed attacks from creatures made mostly of wood (such as arboreals).</p>"},{"n":"Branch Whip","a":"2","c":"offensive","t":[],"f":"","d":"<p>The ta'apundo makes four branch Strikes against different targets, increasing its reach to 20 feet for these Strikes. These attacks count toward its multiple attack penalty, but this penalty doesn't increase until after all four attacks.</p>"},{"n":"Woodland Stride","a":null,"c":"offensive","t":[],"f":"","d":"<p>The ta'apundo ignores difficult and greater difficult terrain from foliage.</p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/takulu-ot":{"lang":["Amurrun","Common","Elven","Fey","Iruxi","Xanmba"],"lore":[["Academia Lore",13],["Library Lore",11]],"gear":["Staff","Anteater Mask","Healing Potion (Minor)"],"abilities":[{"n":"Quick Lesson","a":"r","c":"interaction","t":["auditory"],"f":"","d":"<p><strong>Trigger</strong> An ally Takulu can see and who can hear Takulu makes a skill check or an attack roll</p>\n<hr>\n<p><strong>Effect</strong> Takulu grants the ally a +2 circumstance bonus to the triggering check.</p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/taon":{"lang":["Common","Necril"],"gear":["Spellcutter"],"notes":{"hp":"void healing"},"flavor":"<p>The weight of murder wears heavy on the soul. With souls marked by a lifetime of dealing death, these killers, whether mass murderers, bloodthirsty soldiers, or sadistic executioners, sometimes do not let judgment and lawful execution stanch their slaying sprees. When such individuals are brought to justice, they may rise after death as mohrgs to continue their ruinous work.</p>\n<p>Drawn to others of their kind, mohrgs prefer to hunt in small groups, occasionally in partnership with weaker free-willed undead such as shadows and wights. They seek out weak prey and revel in causing drawn-out suffering. Some mohrgs haunt locations they favored in life, reenacting old crimes on new victims. They may even skulk about in public, wearing rags, cloaks, or freshly harvested skins to hide their nature. The most dangerous mohrgs are those who grow powerful enough to no longer fear being struck down again and openly assault settlements in an attempt to turn living towns into mass graves.</p>\n<p>Since those slain by a mohrg rise soon thereafter as mohrg spawn, the murders of a mohrg rarely go unnoticed for long, even when they take extra care to prey only on a society's dregs. Since mohrg spawn remain under a mohrg's control, a canny mohrg might order its spawn to remain in hiding to keep its presence secret until a point where it feels confident unleashing its undead army upon a doomed settlement.</p>\n<p>Mohrgs retain a twisted sentimentality for the crimes of their mortal life, seeking out trinkets that remind them of favorite murders. When not out hunting, mohrgs arrange their mementos into disturbing shrines. Often, these trinkets are valuable objects, and might even provide important clues to ongoing mysteries.</p>","abilities":[{"n":"Attack of Opportunity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Mohrg Spawn","a":null,"c":"defensive","t":["occult"],"f":"","d":"<p>A living creature slain by a mohrg that had a lower level than the mohrg rises as a mohrg spawn after 1d4 rounds, on its turn. This mohrg spawn is under the command of the mohrg that created it.</p>\n<p>If the creator of the mohrg spawn is destroyed, the mohrg spawn is destroyed as well, immediately collapsing into a pile of decayed flesh and bones.</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Cruel Reactions","a":null,"c":"offensive","t":[],"f":"","d":"<p>Taon gains an extra reaction each round that can be used only to make an Attack of Opportunity.</p>"},{"n":"Paralysis","a":null,"c":"offensive","t":["incapacitation","occult"],"f":"","d":"<p>A living creature hit by a mohrg's tongue Strike must succeed at a DC 30 Fortitude save or become Paralyzed. The creature can attempt a new save at the end of each of its turns, and the DC cumulatively decreases by 1 on each attempt.</p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}],"strikeNotes":{"Spellcutter":"<p><em>Spellcutter</em> cannot damage living creatures</p>"}},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/tatterthread":{"lang":["Common","Jotun","tongues"],"lore":[["Lore (all)",32]],"notes":{"hp":"regeneration 15 (deactivated by cold iron)","saves":"+1 status to all saves vs. magic","per":"detect magic"},"abilities":[{"n":"Greater Darkvision","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>A creature with greater darkvision can see perfectly well in areas of darkness and dim light, though such vision is in black and white only. A creature with greater darkvision can see through even forms of magical darkness.</p></p>"},{"n":"Lifesense 120 feet","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>Lifesense allows a monster to sense the vital essence of living and undead creatures within the listed range. The sense can distinguish between the vitality energy animating living creatures and the void energy animating undead creatures, much as sight distinguishes colors.</p></p>"},{"n":"Constant Spells","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>A constant spell affects the monster without the monster needing to cast it, and its duration is unlimited. If a constant spell gets counteracted, the monster can reactivate it by spending the normal spellcasting actions the spell requires.</p></p>"},{"n":"+1 Status to All Saves vs. Magic","a":null,"c":"defensive","t":[],"f":"","d":""},{"n":"Regeneration 15 (Deactivated by Cold Iron)","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>This monster regains the listed number of Hit Points each round at the beginning of its turn. Its Dying condition never increases beyond Dying 3 as long as its regeneration is active. However, if it takes damage of a type listed in the regeneration entry, its regeneration deactivates until the end of its next turn. Deactivate the regeneration before applying any damage of a listed type, since that damage might kill the monster by bringing it to Dying 4.</p></p>"},{"n":"Deny Fate","a":null,"c":"defensive","t":["misfortune"],"f":"","d":"<p>When Tatterthread rolls initiative, enemies she can see within 120 feet that are also rolling initiative automatically roll a 1.</p>\n<p>Effect: Deny Fate</p>"},{"n":"Fated","a":null,"c":"offensive","t":[],"f":"","d":"<p>When a creature is subject to a fortune effect from a norn and a misfortune effect from any source other than a norn (or vice versa), the norn's effect automatically counteracts the other effect and then takes place normally, rather than the two effects canceling each other out. If both the fortune and misfortune effect are from a norn, then the two cancel each other out as normal. At the GM's discretion, powerful entities related to fate or luck, like Desna, Magdh, or Pharasma, count as a norn for the purpose of this ability.</p>"},{"n":"Shadow Corrosion","a":null,"c":"offensive","t":["acid","occult"],"f":"","d":"<p>When Tatterthread deals acid damage with a Strike, she regains 10 healing Hit Points. The target must succeed at a DC 39 Fortitude save or become Doomed 1 (Doomed 2 on a critical failure).</p>"},{"n":"Shadow Snip","a":"2","c":"offensive","t":["acid","death","manipulate","occult"],"f":"3 times per day","d":"<p><strong>Frequency</strong> three times per day</p>\n<hr>\n<p><strong>Effect</strong> Tatterthread produces a scrap of shadow linked to the fate of a creature within 100 feet of her, then snips it with her caustic shears. The target takes 100 acid damage (DC 42 basic Fortitude). If the target is reduced to 0 Hit Points from this damage, it melts into a puddle of fetid acid and dies immediately. If the target failed the saving throw, it loses any acid resistance it has for 1 minute (1 day on a critical failure). A creature slain by Shadow Snip can't be restored to life except by miracle, wish, or similarly powerful magic, or by divine intervention. Regardless of the outcome of its save, a creature targeted by Shadow Snip becomes temporarily immune for 24 hours. The norn can't use Shadow Snip again for 1d4 rounds.</p>"},{"n":"Shift Fate","a":"r","c":"offensive","t":["occult"],"f":"","d":"<p><strong>Trigger</strong> A creature within 120 feet attempts a saving throw</p>\n<hr>\n<p><strong>Effect</strong> The creature rolls the save twice, and then Tatterthread decides which result applies. If she chooses the lower roll, this is a misfortune effect; if she chooses the higher roll, it's a fortune effect; if they're the same, she decides which trait to apply.</p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/terwa-chosen":{"lang":["Common","Iruxi"],"lore":[["Astrology Lore",14]],"gear":["Mambele","Leather Armor"],"abilities":[{"n":"Attack of Opportunity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Born Lucky","a":"r","c":"defensive","t":["divine"],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p>\n<p><strong>Trigger</strong> The Terwa chosen rolls a success or a critical failure on a check</p><hr><p><strong>Effect</strong> The Terwa chosen improves the triggering roll by one degree of success, only from a success to a critical success or from a critical failure to a failure.</p>"},{"n":"Deep Breath","a":null,"c":"defensive","t":[],"f":"","d":"<p>A Terwa chosen can hold their breath for 10 minutes.</p>"},{"n":"Celestial Might","a":"2","c":"offensive","t":[],"f":"once per round","d":"<p><strong>Frequency</strong> once per round</p><hr><p><strong>Effect</strong> The Terwa chosen calls upon the stars to empower their attack. They attempt a Strike. If the Strike hits, the Terwa chosen deals an additional 2d6 precision damage.</p>"},{"n":"Champion's Star","a":"1","c":"offensive","t":["divine","fortune"],"f":"once per hour","d":"<p><strong>Frequency</strong> once per hour</p><hr>\n<p><strong>Effect</strong> The Terwa chosen looks to the sky for a star to guide their attack. The Terwa chosen gains the effects of Sure Strike.</p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/terwa-prodigy":{"lang":["Common","Draconic","Iruxi"],"lore":[["Astrology Lore",11]],"gear":["Longbow","Leather Armor"],"abilities":[{"n":"Deep Breath","a":null,"c":"defensive","t":[],"f":"","d":"<p>A terwa prodigy can hold their breath for 10 minutes.</p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/terwa-star-reader":{"lang":["Common","Draconic","Iruxi"],"lore":[["Astrology Lore",19]],"gear":["Staff of Fire","Hide Armor"],"abilities":[{"n":"Deep Breath","a":null,"c":"defensive","t":[],"f":"","d":"<p>A Terwa star reader can hold their breath for 10 minutes.</p>"},{"n":"Move the Stars","a":"r","c":"defensive","t":["occult"],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p>\n<p><strong>Trigger</strong> An attack or effect would reduce an ally within 30 feet to 0 Hit Points or would cause the ally to gain the dying condition</p><hr><p><strong>Effect</strong> The star reader interprets the meaning of astrological omens in an instant, determining a new fate for the ally. The triggering ally remains at 1 Hit Point, does not increase their dying or wounded condition, and gains 10 temporary Hit Points for 1 round.</p>"},{"n":"Guiding Star","a":"1","c":"offensive","t":["fortune","occult"],"f":"","d":"<p>The star reader finds the star that would guide their own attack or that of an ally. The star reader grants themselves or an ally within 30 feet the effects of Sure Strike. If the star reader chooses an ally, the duration lasts until the end of that creature's turn. The target is then temporarily immune to Guiding Star for 1 day.</p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/thasteron-khefak":{"flavor":"<p>Thasteron khefaks are alchemically enhanced versions of standard khefaks, capable of converting the minerals they eat into thasteron. While thasteron remains highly valuable as fuel and for specialized weapons, finding an experienced thasteron khefak breeder is hard because the creatures become radioactive over time.</p>\n<hr>\n<p>This unusual arthropod resembles an amalgam of a centipede and a crab. Hard-shelled and perfectly suited to life on Akiton, khefaks are so incredibly useful that a visitor to the planet might assume they were custom engineered for their environs. Such visitors would, in fact, be correct. While khefaks can be found naturally on Akiton, a new species has recently gained a foothold on the planet: alchemically engineered khefaks who excrete a refined substance that can be used as fuel to power advanced engines and devices.</p>","abilities":[{"n":"Tremorsense (Imprecise) 60 feet","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>Tremorsense allows a monster to feel the vibrations through a solid surface caused by movement. It is an imprecise sense with a limited range (listed in the ability). Tremorsense functions only if the monster is on the same surface as the subject, and only if the subject is moving along (or burrowing through) the surface.</p></p>"},{"n":"Consume Objects","a":null,"c":"interaction","t":[],"f":"","d":"<p>A khefak can gain nourishment by eating objects with hardness 10 or lower. When attacking an object with its mandibles, it ignores the first 10 points of that object's Hardness.</p>"},{"n":"Radiation Aura","a":null,"c":"interaction","t":["aura","radiation"],"f":"","d":"<p>10 feet. Thasteron khefaks convert radioactive minerals they eat into thasteron, a combustive fuel. The more radioactive elements of the material concentrates in their chitin and taints the air around them. A creature who begins their turn within this aura must succeed at a DC 20 Fortitude saving throw or become Sickened 1 (Sickened 2 on a critical failure).</p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/thiarvo-the-quick":{"lang":["Common","Draconic","Elven","Halfling","Iruxi"],"gear":["Alchemist's Fire (Moderate) (4)","+1 Striking Rod of Wonder","Studded Leather Armor","Thieves' Tools (Infiltrator)","Healing Potion (Moderate)"],"abilities":[{"n":"Halfling Luck","a":"r","c":"defensive","t":["fortune"],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p>\n<p><strong>Trigger</strong> Thiarvo fails a skill check or a saving throw</p>\n<hr>\n<p><strong>Effect</strong> Thiarvo rerolls the triggering check and must use the new result.</p>"},{"n":"Fighting Rod","a":null,"c":"offensive","t":[],"f":"","d":"<p>Thiarvo's <em>Rod of Wonder</em> is supple wood and can be used as a Fighting Stick. It can be enchanted with fundamental runes but not property runes, and it's currently enchanted with the <em>Weapon Potency (+1)</em> and <em>Striking</em> runes.</p>"},{"n":"Lethal Fighter","a":null,"c":"offensive","t":[],"f":"","d":"<p>Thiarvo can make lethal attacks using weapons with the nonlethal trait without taking the usual -2 penalty. His attacks with weapons with the nonlethal trait deal an additional 2d8 precision damage, whether he's making nonlethal attacks or lethal attacks with them. This damage is included in his melee entry.</p>"},{"n":"Slippery Halfling","a":null,"c":"offensive","t":[],"f":"","d":"<p>Thiarvo ignores difficult terrain from trees, foliage, rubble, and undergrowth.</p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/thorn-guardian":{"abilities":[{"n":"Attack of Opportunity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Extra Reaction","a":null,"c":"defensive","t":[],"f":"","d":"<p>A thorn guardian gains an additional reaction each turn but can use this extra reaction only to Retaliate.</p>"},{"n":"Retaliate","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature within the thorn guardian's reach attacks the guardian's ward</p>\n<hr>\n<p><strong>Effect</strong> The thorn guardian makes a briar Strike against the triggering creature. If it hits, it deals an additional 2d6 bleed.</p>"},{"n":"Bond with Ward","a":"1","c":"offensive","t":["concentrate","move"],"f":"","d":"<p><strong>Requirements</strong> The thorn guardian is adjacent to its ward</p><hr>\n<p><strong>Effect</strong> The thorn guardian enters its ward's space and encases the creature. This doesn't interfere with its ward's senses or actions. The thorn guardian occupies the same space as its ward and moves with its ward.</p>\n<p>While worn, the thorn guardian establishes a constant Share Life effect with its ward. Attacks that target the thorn guardian target the ward instead but use the higher AC or saving throw values between the thorn guardian and the ward. Area effects apply to both the thorn guardian and the ward, as normal for an area effect.</p>"},{"n":"Fly Free","a":"1","c":"offensive","t":["concentrate","move"],"f":"","d":"<p><strong>Requirements</strong> The thorn guardian is Bonded with its Ward</p><hr><p><strong>Effect</strong> The thorn guardian removes itself from the ward and enters an adjacent space.</p>"},{"n":"Interpose","a":"1","c":"offensive","t":[],"f":"","d":"<p><strong>Requirements</strong> The thorn guardian is Bonded with or adjacent to its ward</p>\n<hr>\n<p><strong>Effect</strong> The thorn guardian interposes itself between the ward and its foes, granting its ward a +2 circumstance bonus to AC until the start of the thorn guardian's next turn.</p>\n<p>Effect: Interpose</p>"}]},"strength-of-thousands-bestiary/book-5-doorway-to-the-red-star/tollvych":{"lang":["Common","Diabolic","Taldane"],"lore":[["Academia Lore",27]],"notes":{"hp":"void healing, rejuvenation"},"abilities":[{"n":"Rejuvenation","a":null,"c":"defensive","t":["divine"],"f":"","d":"<p>If the heroes destroy Dwandek (even if only temporarily, before destroying his <em>soul cage</em> as well), the cathedral's hold over Tollvych's soul loosens; the next time the heroes enter this room (or 24 hours later), his ghost rises one last time from his remains with a sigh, and then moves into the afterlife.</p>\n<hr>\n<p>When a ghost is destroyed, it re-forms after 2d4 days within the location it's bound to, fully healed. A ghost can be permanently destroyed only if someone determines the reason for its existence and sets right whatever prevents the spirit from resting.</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Bone-Shattering Cry","a":"2","c":"offensive","t":["divine","sonic"],"f":"","d":"<p>Tollvych cries out in pain as his body twists and grinds into horrific, distorted shapes. All creatures within a 30-foot emanation take 16d6 bludgeoning damage (DC 36 basic Reflex save) as the sound of the Bone-Shattering Cry shakes and shatters their own bones.</p>\n<p>Tollvych can't use Bone-Shattering Cry for 1d4 rounds.</p>"},{"n":"Frightful Moan","a":"2","c":"offensive","t":["auditory","divine","emotion","fear","mental"],"f":"","d":"<p>Tollvych laments his fate, forcing each living creature within 30 feet to attempt a DC 36 Will save.</p>\n<p>On a failure, a creature becomes Frightened 2 (or Frightened 3 on a critical failure). On a success, a creature is temporarily immune to this Tollvych's frightful moan for 1 minute.</p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/umbo":{"lang":["Sakvroth","telepathy 100 feet (myceloids and those afflicted by purple pox only)"],"abilities":[{"n":"Telepathy 100 feet (Myceloids and Those Afflicted by Purple Pox Only)","a":null,"c":"interaction","t":["aura","magical"],"f":"","d":"<p><p>A monster with telepathy can communicate mentally with any creatures within the listed radius, as long as they share a language. This doesn't give any special access to their thoughts, and communicates no more information than normal speech would.</p></p>"},{"n":"Spore Pop","a":null,"c":"defensive","t":[],"f":"","d":"<p>If Umbo is reduced to 0 HP by a critical hit, he pops, forcing him to immediately Emit Spores, even if he has already used the ability that day.</p>"},{"n":"Emit Spores","a":"1","c":"offensive","t":[],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p>\n<hr>\n<p><strong>Effect</strong> Umbo expels spores in a 10-foot burst centered on a corner of his own space. This cloud lasts until the start of the myceloid's next turn. Each creature that is in the cloud or enters it is exposed to purple pox.</p>"},{"n":"Purple Pox","a":null,"c":"offensive","t":["disease"],"f":"","d":"<p>Myceloids are immune</p>\n<p><strong>Saving Throw</strong> DC 18 Fortitude</p>\n<p><strong>Onset</strong> 1 minute</p>\n<p><strong>Stage 1</strong> 1d6 poison damage and Stupefied 1 (1 day)</p>\n<p><strong>Stage 2</strong> 4d6 poison damage, Stupefied 3, and the creature is compelled to seek out the nearest myceloid colony-this compulsion is a mental emotion effect (1 day)</p>\n<p><strong>Stage 3</strong> The creature dies. Over 24 hours, its corpse becomes bloated and bursts, releasing a new, fully grown myceloid.</p>"},{"n":"Spore Domination","a":"2","c":"offensive","t":["emotion","incapacitation","mental","primal"],"f":"","d":"<p>Umbo targets one creature affected by purple pox within 30 feet. That creature must attempt a DC 18 Will save. It is then temporarily immune to spore domination for 10 minutes.</p>\n<hr>\n<p><strong>Critical Success</strong> The target is unaffected.</p>\n<p><strong>Success</strong> Until the end of its next turn, the target is helpful to myceloids and can't take hostile actions against them. If attacked by Umbo, the target is freed from this effect at the end of Umbo's turn.</p>\n<p><strong>Failure</strong> As success, but for 1 minute.</p>\n<p><strong>Critical Failure</strong> As success, but until the purple pox is cured.</p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/unshadowed-anchor-root":{"lang":["Amurrun","Common","Fey","Iruxi","Kholo","Necril"],"lore":[["Academia Lore",31]],"abilities":[{"n":"Shadow's Displeasure","a":null,"c":"defensive","t":[],"f":"","d":"<p>When Anchor Root has fewer than 150 Hit Points, her shadow pulls at her essence to show the <em>Vesicant Egg's</em> displeasure. She looks pained and confused, and she becomes Clumsy 1 and Stupefied 1 until healed to 150 Hit Points or more. These conditions increase to 2 when below 100 Hit Points. When below 50 Hit Points, she falls Unconscious.</p>"},{"n":"Vesicated Shadow","a":null,"c":"defensive","t":[],"f":"","d":"<p>Anchor Root's shadow has become corrupted via the power of the <em>Vesicant Egg</em>. Her shredded shadow grants her some control over acid and shadows. She gains a +4 status bonus to resist acid and shadow effects.</p>"},{"n":"Rupture Shadow","a":"2","c":"offensive","t":["acid","occult","shadow"],"f":"","d":"<p>Anchor Root can create immense blisters on a creature's shadow, which immediately burst, dealing 20d6 acid damage. She targets a creature within 60 feet that is casting a shadow, which must attempt a DC 37 Will save. Anchor Root can't use Rupture Shadow again for 1d4 rounds.</p>\n<hr>\n<p><strong>Critical Success</strong> The target is unaffected and becomes temporarily immune for 1 day.</p>\n<p><strong>Success</strong> The target takes half damage. The bursting shadow deals 5 acid splash damage to all creatures within 5 feet of the target.</p>\n<p><strong>Failure</strong> The target takes full damage, and the bursting shadow deals 10 acid splash damage.</p>\n<p><strong>Critical Failure</strong> The target takes double damage, the bursting shadow deals 20 acid splash damage, and the target also takes 4d6 persistent acid damage.</p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/unshadowed-haibram":{"lang":["Common","Dwarven"],"lore":[["Academia Lore",31]],"gear":["Mambele"],"abilities":[{"n":"Shadow's Displeasure","a":null,"c":"defensive","t":[],"f":"","d":"<p>When Haibam has fewer than 150 Hit Points, his shadow pulls at his essence to show the <em>Vesicant Egg's</em> displeasure. He looks pained and confused, and he becomes Clumsy 1 and Stupefied 1 until healed to 150 Hit Points or more. These conditions increase to 2 when below 100 Hit Points. When below 50 Hit Points, he falls Unconscious.</p>"},{"n":"Vesicated Shadow","a":null,"c":"defensive","t":[],"f":"","d":"<p>Haibam's shadow has become corrupted via the power of the <em>Vesicant Egg</em>. His shredded shadow grants him some control over acid and shadows. He gains a +4 status bonus to resist acid and shadow effects.</p>"},{"n":"Rupture Shadow","a":"2","c":"offensive","t":["acid","occult","shadow"],"f":"","d":"<p>Haibam can create immense blisters on a creature's shadow, which immediately burst, dealing 20d6 acid damage. He targets a creature within 60 feet that is casting a shadow, which must attempt a DC 37 Will save. Haibam can't use Rupture Shadow again for 1d4 rounds.</p>\n<hr>\n<p><strong>Critical Success</strong> The target is unaffected and becomes temporarily immune for 1 day.</p>\n<p><strong>Success</strong> The target takes half damage. The bursting shadow deals 5 acid splash damage to all creatures within 5 feet of the target.</p>\n<p><strong>Failure</strong> The target takes full damage, and the bursting shadow deals 10 acid splash damage.</p>\n<p><strong>Critical Failure</strong> The target takes double damage, the bursting shadow deals 20 acid splash damage, and the target also takes 4d6 persistent acid damage.</p>"},{"n":"Wind Step","a":"2","c":"offensive","t":["air","arcane"],"f":"","d":"<p>Haibram draws air around him to aid his movement. He Strides up to his Speed, gaining the effects of Air Walk and ignoring difficult terrain while moving. He can increase the number of actions to 3 to Stride up to three times his Speed instead. Haibram begins to fall immediately after using Wind Step but treats the fall as 60 feet shorter thanks to the supporting winds.</p>"},{"n":"Wind Touch","a":"1","c":"offensive","t":[],"f":"","d":"<p>Haibram imbues a weapon he's holding with the power of the wind until the start of his next turn. The wind's power allows Haibram to swing and hurl the weapon with great force, causing the weapon to deal an additional 2d10 damage. If the weapon does not have the thrown trait, it also gains the thrown 10 feet trait during this attack.</p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/unshadowed-koride":{"lang":["Common","Draconic","Fey","Iruxi","Kholo","Necril","Orcish"],"lore":[["Academia Lore",37]],"gear":["+3 Major Striking Staff of Nature's Vengeance (Major)"],"abilities":[{"n":"Shadow's Displeasure","a":null,"c":"defensive","t":[],"f":"","d":"<p>When Koride has fewer than 150 Hit Points, her shadow pulls at her essence to show the <em>Vesicant Egg's</em> displeasure. She looks pained and confused, and she becomes Clumsy 1 and Stupefied 1 until healed to 150 Hit Points or more. These conditions increase to 2 when below 100 Hit Points. When below 50 Hit Points, she falls Unconscious.</p>"},{"n":"Vesicated Shadow","a":null,"c":"defensive","t":[],"f":"","d":"<p>Koride's shadow has become corrupted via the power of the <em>Vesicant Egg</em>. Her shredded shadow grants her some control over acid and shadows. She gains a +4 status bonus to resist acid and shadow effects.</p>"},{"n":"Rupture Shadow","a":"2","c":"offensive","t":["acid","occult","shadow"],"f":"","d":"<p>Koride can create immense blisters on a creature's shadow, which immediately burst, dealing 20d6 acid damage. She targets a creature within 60 feet that is casting a shadow, which must attempt a DC 37 Will save. Koride can't use Rupture Shadow again for 1d4 rounds.</p>\n<hr>\n<p><strong>Critical Success</strong> The target is unaffected and becomes temporarily immune for 1 day.</p>\n<p><strong>Success</strong> The target takes half damage. The bursting shadow deals 5 acid splash damage to all creatures within 5 feet of the target.</p>\n<p><strong>Failure</strong> The target takes full damage, and the bursting shadow deals 10 acid splash damage.</p>\n<p><strong>Critical Failure</strong> The target takes double damage, the bursting shadow deals 20 acid splash damage, and the target also takes 4d6 persistent acid damage.</p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/unshadowed-mariama":{"lang":["Common","Dwarven","Fey","Kholo"],"lore":[["Academia Lore",35]],"focus":3,"abilities":[{"n":"Shadow's Displeasure","a":null,"c":"defensive","t":[],"f":"","d":"<p>When Mariama has fewer than 150 Hit Points, her shadow pulls at her essence to show the <em>Vesicant Egg's</em> displeasure. She looks pained and confused. When below 50 Hit Points, she falls Unconscious.</p>"},{"n":"Vesicated Shadow","a":null,"c":"defensive","t":[],"f":"","d":"<p>Mariama's shadow has become corrupted via the power of the <em>Vesicant Egg</em>. Her shredded shadow grants her some control over acid and shadows. She gains a +4 status bonus to resist acid and shadow effects.</p>"},{"n":"Weird Astrology","a":null,"c":"defensive","t":[],"f":"","d":"<p>Perhaps because of Mariama's quirky nature, she has received all the effects of the astrological evaluator. When she gains any of the Clumsy, Drained, Enfeebled, or Stupefied conditions, she reduces the value by 1. This means her Shadow's Displeasure doesn't affect her until she has fewer than 50 Hit Points, when she falls Unconscious.</p>"},{"n":"Bind Destinies","a":"3","c":"offensive","t":["curse","occult"],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p>\n<hr>\n<p><strong>Effect</strong> Mariama ties her fate with that of another creature within 30 feet. The creature must attempt a DC 40 Will save. Regardless of the result of its save, the creature is temporarily immune for 1 day.</p>\n<hr>\n<p><strong>Critical Success</strong> The creature is unaffected.</p>\n<p><strong>Success</strong> The two fates are bound. Whenever Mariama takes damage, the creature takes damage of the same type equal to half the damage Mariama took (DC 37 basic Fortitude). Immunities, resistances, and weaknesses still apply as normal. The creature can attempt to sever the bond by spending an action, which has the concentrate trait, to attempt another DC 40 Will save. On a success, the bond is severed, and the effect ends. The bond also ends when Mariama falls Unconscious, or if she actively ends the effect herself as a free action.</p>\n<p><strong>Failure</strong> As success, but the creature takes damage equal to the full amount Mariama took. Severing the bond requires a 2-action activity, which has the concentrate trait.</p>\n<p><strong>Critical Failure</strong> As failure, but DC 40 basic Fortitude. Severing the bond requires a 3-action activity, which has the concentrate trait.</p>"},{"n":"Rupture Shadow","a":"2","c":"offensive","t":["acid","occult","shadow"],"f":"","d":"<p>Mariama can create immense blisters on a creature's shadow, which immediately burst, dealing 20d6 acid damage. She targets a creature within 60 feet that is casting a shadow, which must attempt a DC 37 Will save. Mariama can't use Rupture Shadow again for 1d4 rounds.</p>\n<hr>\n<p><strong>Critical Success</strong> The target is unaffected and becomes temporarily immune for 1 day.</p>\n<p><strong>Success</strong> The target takes half damage. The bursting shadow deals 5 acid splash damage to all creatures within 5 feet of the target.</p>\n<p><strong>Failure</strong> The target takes full damage, and the bursting shadow deals 10 acid splash damage.</p>\n<p><strong>Critical Failure</strong> The target takes double damage, the bursting shadow deals 20 acid splash damage, and the target also takes 4d6 persistent acid damage.</p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/unshadowed-okoro":{"lang":["Common","Draconic","Elven","Petran"],"lore":[["Academia Lore",33],["Games Lore",31]],"gear":["Composite Shortbow","Arrows (30)"],"abilities":[{"n":"Shadow's Displeasure","a":null,"c":"defensive","t":[],"f":"","d":"<p>When Okoro has fewer than 150 Hit Points, his shadow pulls at his essence to show the <em>Vesicant Egg's</em> displeasure. He looks pained and confused, and he becomes Clumsy 1 and Stupefied 1 until healed to 150 Hit Points or more. These conditions increase to 2 when below 100 Hit Points. When below 50 Hit Points, he falls Unconscious.</p>"},{"n":"Vesicated Shadow","a":null,"c":"defensive","t":[],"f":"","d":"<p>Okoro's shadow has become corrupted via the power of the <em>Vesicant Egg</em>. His shredded shadow grants him some control over acid and shadows. He gains a +4 status bonus to resist acid and shadow effects.</p>"},{"n":"Observe Weakness","a":"1","c":"offensive","t":["concentrate","fortune","occult"],"f":"","d":"<p>Okoro studies a creature within 30 feet to find an opening to attack. On his next attack roll against the creature this turn, he rolls twice and uses the higher result, and his attack gains the fortune trait. The target becomes temporarily immune for 1d4 rounds.</p>"},{"n":"Rupture Shadow","a":"2","c":"offensive","t":["acid","occult","shadow"],"f":"","d":"<p>Okoro can create immense blisters on a creature's shadow, which immediately burst, dealing 20d6 acid damage. He targets a creature within 60 feet that is casting a shadow, which must attempt a DC 37 Will save. Okoro can't use Rupture Shadow again for 1d4 rounds.</p>\n<hr>\n<p><strong>Critical Success</strong> The target is unaffected and becomes temporarily immune for 1 day.</p>\n<p><strong>Success</strong> The target takes half damage. The bursting shadow deals 5 acid splash damage to all creatures within 5 feet of the target.</p>\n<p><strong>Failure</strong> The target takes full damage, and the bursting shadow deals 10 acid splash damage.</p>\n<p><strong>Critical Failure</strong> The target takes double damage, the bursting shadow deals 20 acid splash damage, and the target also takes 4d6 persistent acid damage.</p>"},{"n":"Push My Luck","a":"r","c":"offensive","t":[],"f":"","d":"<p><strong>Trigger</strong> Okoro targets a creature with an attack</p>\n<p><strong>Requirements</strong> The triggering creature was the target of Observe Weakness this turn</p><hr><p><strong>Effect</strong> Okoro draws upon his future luck to guarantee his attack. When he makes his attack roll, if he rolls lower than 10 on the die, he treats that attack roll as a 10 instead. This is in addition to rolling twice and taking the higher result from Observe Weakness. Afterward, Okoro's luck is temporarily spent, and he must roll twice and use the lower result of his next 3 checks; this is a misfortune effect. He can't use Push My Luck again until he's completed these 3 checks.</p>\n<p>Effect: Push My Luck (Misfortune)</p>"}]},"strength-of-thousands-bestiary/book-1-kindled-magic/urbel":{"lang":["Sakvroth"],"gear":["Pick","Pouch with 4 gold teeth"],"focus":1,"flavor":"<p>The \"towering\" hunchbacked nuglubs are among the largest gremlins, though they're not quite three feet tall. Nuglubs have three glowing blue eyes and black, oily hair on their head and back that covers them like a cloak. Nuglubs enjoy killing with a glee that other gremlins reserve for sabotage. Indeed, they spend long hours preparing ambushes for unwary travelers or plotting the murders of sleeping villagers. Though less technically inclined than their kin, nuglubs do enjoy building traps. They delight in stealthily constructing traps in places their victims consider familiar, such as front doors and the floors around beds. If someone else gets blamed for the mayhem the nuglub creates, all the better.</p>\n<p>In combat, nuglubs focus on targets wearing metal armor. Some attribute this to envy on the part of the nuglubs, who find it difficult to fit armor on their twisted bodies. Nuglubs are particularly talented at causing those nearby to stumble over them and fall prone. Once an enemy falls to the ground, all the nuglubs descend upon the target, biting and scratching until nothing remains.</p>\n<p>Nuglubs rarely gather in groups larger than half a dozen, as quarrels often lead to violence and cannibalism. A lone nuglub who bullies a group of smaller gremlins is more likely to get their way, and thus less likely to attack their allies.</p>","abilities":[{"n":"Kneecapper","a":"r","c":"defensive","t":["move"],"f":"","d":"<p><strong>Trigger</strong> A Medium creature within Urbel's reach leaves a square during its move action</p>\n<hr>\n<p><strong>Effect</strong> Urbel lashes out at the triggering creature's knees and tries to knock them Prone. He attempts an Acrobatics vs. Reflex DC check against the creature's Reflex DC. On a success, the target falls and lands Prone.</p>"},{"n":"Bully","a":null,"c":"offensive","t":[],"f":"","d":"<p>Any melee weapon Urbel uses gains the shove trait, and if he rolls a critical failure when attempting to Shove a creature with the weapon, he treats the result as a failure instead.</p>"},{"n":"Pound Down","a":null,"c":"offensive","t":[],"f":"","d":"<p>Urbel's melee Strikes deal an additional 1d6 damage to Prone targets.</p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/venom-pool":{"description":"A shallow, foul-smelling puddle of toxic acid blocks a narrow hall (marked with a dotted line on the map), and poison bursts from it when disturbed.","disable":"<p>DC 40 Crafting (master) or DC 42 Survival (legendary) to neutralize the acid while within reach of it. Three successes using either skill (or a combination of both) destroys the hazard.</p>","reset":"The hazard ends after 1 minute, contracting to its original size and keeping still until disturbed again.","routine":"<p>(2 actions) The hazard uses its first action to spread 10 feet down the hallway in both directions. Once out of the hall, each side spreads in a random direction each round, but they don't go through doors. The hazard uses its second action to move the center of the Toxic Cloud up to 20 feet in any direction to which any part of the pool has line of effect (normally, to encompass the greatest number of characters). If the <em>cloudkill</em> isn't present, it instead uses its second action to produce a new <em>cloudkill</em>, as Poison Puff.</p>","stealthNote":"<p>(legendary) to distinguish between the hazard and the oozes within it; DC 0 Perception to notice the pool</p>","abilities":[{"n":"Deadly Footing","a":null,"c":"defensive","t":[],"f":"","d":"<p>The area of the venom pool is difficult terrain, and each creature moving through it takes 10 acid for every square of its area that it moves into.</p>"},{"n":"Poison Puff","a":"r","c":"offensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature moves through any square in the hazard's space</p><hr>\n<p><strong>Effect</strong> The pool produces a 9th-rank Toxic Cloud; (DC 40 Fortitude) at its center. It then rolls initiative.</p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/wereant-disciple":{"lang":["Common","insect empathy, telepathy 120 feet"],"flavor":"<p>Insectile werecreatures, such as wereants, only come about in unusual circumstances, such as powerful curses from inhuman gods or transformative magic run amok. Wereants work together with a natural cohesion that's rare in other types of werecreatures. The wereants presented here are more powerful than most wereants, as they've been warped by the forces contained within the Vesicant Egg.</p>\n<p>Some wereants have a religious zeal about training to protect their community and gladly give their lives for the hive.</p>","abilities":[{"n":"Telepathy 120 feet","a":null,"c":"interaction","t":["aura","magical"],"f":"","d":"<p><p>A monster with telepathy can communicate mentally with any creatures within the listed radius, as long as they share a language. This doesn't give any special access to their thoughts, and communicates no more information than normal speech would.</p></p>"},{"n":"Insect Empathy","a":null,"c":"interaction","t":["primal"],"f":"","d":"<p>The wereant can communicate with insects.</p>"},{"n":"Gnawing Retort","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature adjacent to the wereant critically misses the wereant with a melee Strike</p><hr>\n<p><strong>Effect</strong> The wereant makes a mandibles Strike against the triggering creature.</p>"},{"n":"Hive Mind","a":null,"c":"defensive","t":["primal"],"f":"","d":"<p>Wereants operate with a shared hive intelligence. While within telepathic range of at least one other wereant, a wereant disciple gains a +2 circumstance bonus to initiative checks, Perception checks, and saving throws against mental effects. If one wereant is aware of a combatant, all members of the hive mind within telepathic range are aware of it.</p>"},{"n":"Change Shape","a":"1","c":"offensive","t":["concentrate","polymorph","primal"],"f":"","d":"<p>The wereant changes into their humanoid, hybrid, or animal shape. Each shape has a specific, persistent appearance. A true wereant's natural form is their hybrid shape. In humanoid shape, they use their original humanoid size, lose their jaws and claw Strikes, and gain a melee fist Strike that deals bludgeoning damage equal to the slashing damage dealt by their mandibles. In animal shape, they take the form of a Medium giant ant, gain a climb Speed of 20 feet, gain Grab on their mandibles Strike, and lose their weapon Strikes.</p>\n<hr>\n<p><p>The monster changes its shape indefinitely. It can use this action again to return to its natural shape or adopt a new shape. Unless otherwise noted, a monster cannot use Change Shape to appear as a specific individual. Using Change Shape counts as creating a disguise for the Impersonate use of Deception. The monster's transformation automatically defeats Perception DCs to determine whether the creature is a member of the ancestry or creature type into which it transformed, and it gains a +4 status bonus to its Deception DC to prevent others from seeing through its disguise. Change Shape abilities specify what shapes the monster can adopt. The monster doesn't gain any special abilities of the new shape, only its physical form. For example, in each shape, it replaces its normal Speeds and Strikes, and might potentially change its senses or size. Any changes are listed in its stat block.</p></p>"},{"n":"Curse of the Wereant","a":null,"c":"offensive","t":["curse","primal"],"f":"","d":"<p>This curse affects only humanoids</p>\n<p><strong>Saving Throw</strong> DC 34 Fortitude.</p>\n<p>On each full moon, the cursed creature must succeed at another Fortitude save or turn into a wereant until dawn.</p>\n<p>The creature is under the GM's control and goes on a rampage for half the night before falling Unconscious until dawn.</p>"},{"n":"Flying Leap","a":"1","c":"offensive","t":[],"f":"once per round","d":"<p><strong>Frequency</strong> once per round</p><hr>\n<p><strong>Effect</strong> The wereant disciple Flies and makes two Strikes against different targets at any point during that movement. These Strikes deal an additional 2d6 precision damage if the disciple is above the target. If the wereant began this action Hidden, they remain hidden until after this ability's Strikes. Both attacks count toward the disciple's multiple attack penalty, but the penalty doesn't increase until after both Strikes.</p>"},{"n":"Moon Frenzy","a":null,"c":"offensive","t":["polymorph","primal"],"f":"","d":"<p>When a full moon appears in the night sky, the wereant must enter hybrid form, can't Change Shape thereafter, becomes one size larger, increases its reach by 5 feet, and increases the damage of their mandibles Strike by 2.</p>\n<p>When the moon sets or the sun rises, the werecreature returns to humanoid form and is Fatigued for 2d4 hours.</p>\n<p>Effect: Moon Frenzy</p>"},{"n":"Staggering Blow","a":null,"c":"offensive","t":[],"f":"","d":"<p>A creature damaged by the wereant disciple's carapace fist Strike must succeed at a DC 35 Fortitude save or become Stunned 1 (Stunned 2 on a critical failure). If the Strike is a critical hit, a creature that fails the save is also Paralyzed for 1 round.</p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/wereant-poisoner":{"lang":["Common","inset empathy; telepathy 120 feet"],"gear":["Kukri (2)"],"flavor":"<p>Insectile werecreatures, such as wereants, only come about in unusual circumstances, such as powerful curses from inhuman gods or transformative magic run amok. Wereants work together with a natural cohesion that's rare in other types of werecreatures. The wereants presented here are more powerful than most wereants, as they've been warped by the forces contained within the Vesicant Egg.</p>\n<p>When overwhelming force is inadvisable, a wereant hive sends a poison-dripping assassin for murderous work. These poisoners love to terrify those dying in agony from their toxins.</p>","abilities":[{"n":"Telepathy 120 feet","a":null,"c":"interaction","t":["aura","magical"],"f":"","d":"<p><p>A monster with telepathy can communicate mentally with any creatures within the listed radius, as long as they share a language. This doesn't give any special access to their thoughts, and communicates no more information than normal speech would.</p></p>"},{"n":"Insect Empathy","a":null,"c":"interaction","t":["primal"],"f":"","d":"<p>The wereant can communicate with insects.</p>"},{"n":"Gnawing Retort","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature adjacent to the wereant critically misses the wereant with a melee Strike</p><hr>\n<p><strong>Effect</strong> The wereant makes a mandibles Strike against the triggering creature.</p>"},{"n":"Hive Mind","a":null,"c":"defensive","t":["primal"],"f":"","d":"<p>Wereants operate with a shared hive intelligence. While within telepathic range of at least one other wereant, a wereant disciple gains a +2 circumstance bonus to initiative checks, Perception checks, and saving throws against mental effects. If one wereant is aware of a combatant, all members of the hive mind within telepathic range are aware of it.</p>"},{"n":"Change Shape","a":"1","c":"offensive","t":["concentrate","polymorph","primal"],"f":"","d":"<p>The wereant changes into their humanoid, hybrid, or animal shape. Each shape has a specific, persistent appearance. A true wereant's natural form is their hybrid shape. In humanoid shape, they use their original humanoid size, lose their jaws and claw Strikes, and gain a melee fist Strike that deals bludgeoning damage equal to the slashing damage dealt by their mandibles. In animal shape, they take the form of a Medium giant ant, gain a climb Speed of 20 feet, gain Grab on their mandibles Strike, and lose their weapon Strikes.</p>\n<hr>\n<p><p>The monster changes its shape indefinitely. It can use this action again to return to its natural shape or adopt a new shape. Unless otherwise noted, a monster cannot use Change Shape to appear as a specific individual. Using Change Shape counts as creating a disguise for the Impersonate use of Deception. The monster's transformation automatically defeats Perception DCs to determine whether the creature is a member of the ancestry or creature type into which it transformed, and it gains a +4 status bonus to its Deception DC to prevent others from seeing through its disguise. Change Shape abilities specify what shapes the monster can adopt. The monster doesn't gain any special abilities of the new shape, only its physical form. For example, in each shape, it replaces its normal Speeds and Strikes, and might potentially change its senses or size. Any changes are listed in its stat block.</p></p>"},{"n":"Curse of the Wereant","a":null,"c":"offensive","t":["curse","primal"],"f":"","d":"<p>This curse affects only humanoids</p>\n<p><strong>Saving Throw</strong> DC 34 Fortitude.</p>\n<p>On each full moon, the cursed creature must succeed at another Fortitude save or turn into a wereant until dawn.</p>\n<p>The creature is under the GM's control and goes on a rampage for half the night before falling Unconscious until dawn.</p>"},{"n":"Envenomed Weapons","a":null,"c":"offensive","t":[],"f":"","d":"<p>Weapons the wereant poisoner holds deal an additional 2d6 persistent poison as poison seeps from the wereant's hands onto the weapon. Weapons cease to deal this persistent poison damage once the wereant lets them go. The kukri Strikes above include this persistent poison damage.</p>"},{"n":"Moon Frenzy","a":null,"c":"offensive","t":["polymorph","primal"],"f":"","d":"<p>When a full moon appears in the night sky, the wereant must enter hybrid form, can't Change Shape thereafter, becomes one size larger, increases its reach by 5 feet, and increases the damage of their mandibles Strike by 2.</p>\n<p>When the moon sets or the sun rises, the werecreature returns to humanoid form and is Fatigued for 2d4 hours.</p>\n<p>Effect: Moon Frenzy</p>"},{"n":"Poisonous Flurry","a":"2","c":"offensive","t":[],"f":"","d":"<p>The wereant poisoner makes two kukri Strikes and a mandibles Strike in any order.</p>"},{"n":"Vitriolic Strikes","a":null,"c":"offensive","t":[],"f":"","d":"<p>If the wereant critically hits a creature with a melee Strike, that creature can't recover from persistent poison damage for 1 round.</p>"}]},"strength-of-thousands-bestiary/book-6-shadows-of-the-ancients/wereant-sentinel":{"lang":["Common","insect empathy, telepathy 120 feet"],"gear":["Khopesh","Sturdy Shield (Major)"],"notes":{"ac":"(45 with shield raised)"},"abilities":[{"n":"Insect Empathy","a":null,"c":"interaction","t":["primal"],"f":"","d":"<p>The wereant can communicate with insects.</p>"},{"n":"Gnawing Retort","a":null,"c":"defensive","t":[],"f":"","d":"<p>[reaction] As wereant disciple.</p>"},{"n":"Hive Mind","a":null,"c":"defensive","t":["primal"],"f":"","d":"<p>Wereants operate with a shared hive intelligence. While within telepathic range of at least one other wereant, a wereant disciple gains a +2 circumstance bonus to initiative checks, Perception checks, and saving throws against mental effects. If one wereant is aware of a combatant, all members of the hive mind within telepathic range are aware of it.</p>"},{"n":"Retributive Strike","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> An enemy damages the wereant sentinel's ally, and both are within 15 feet of the wereant sentinel</p><hr><p><strong>Effect</strong> The ally gains resistance 20 against the triggering damage. If the foe is within reach, the wereant sentinel makes a melee Strike against it.</p>"},{"n":"Change Shape","a":"1","c":"offensive","t":["concentrate","polymorph","primal"],"f":"","d":"<p>The wereant changes into their humanoid, hybrid, or animal shape. Each shape has a specific, persistent appearance. A true wereant's natural form is their hybrid shape. In humanoid shape, they use their original humanoid size, lose their jaws and claw Strikes, and gain a melee fist Strike that deals bludgeoning damage equal to the slashing damage dealt by their mandibles. In animal shape, they take the form of a Medium giant ant, gain a climb Speed of 20 feet, gain Grab on their mandibles Strike, and lose their weapon Strikes.</p>\n<hr>\n<p><p>The monster changes its shape indefinitely. It can use this action again to return to its natural shape or adopt a new shape. Unless otherwise noted, a monster cannot use Change Shape to appear as a specific individual. Using Change Shape counts as creating a disguise for the Impersonate use of Deception. The monster's transformation automatically defeats Perception DCs to determine whether the creature is a member of the ancestry or creature type into which it transformed, and it gains a +4 status bonus to its Deception DC to prevent others from seeing through its disguise. Change Shape abilities specify what shapes the monster can adopt. The monster doesn't gain any special abilities of the new shape, only its physical form. For example, in each shape, it replaces its normal Speeds and Strikes, and might potentially change its senses or size. Any changes are listed in its stat block.</p></p>"},{"n":"Curse of the Wereant","a":null,"c":"offensive","t":["curse","primal"],"f":"","d":"<p>This curse affects only humanoids</p>\n<p><strong>Saving Throw</strong> DC 34 Fortitude.</p>\n<p>On each full moon, the cursed creature must succeed at another Fortitude save or turn into a wereant until dawn.</p>\n<p>The creature is under the GM's control and goes on a rampage for half the night before falling Unconscious until dawn.</p>"},{"n":"Hasty Reposition","a":"1","c":"offensive","t":[],"f":"once per round","d":"<p><strong>Frequency</strong> once per round</p>\n<hr>\n<p><strong>Effect</strong> The wereant sentinel Steps, moving up to 15 feet.</p>"},{"n":"Moon Frenzy","a":null,"c":"offensive","t":["polymorph","primal"],"f":"","d":"<p>When a full moon appears in the night sky, the wereant must enter hybrid form, can't Change Shape thereafter, becomes one size larger, increases its reach by 5 feet, and increases the damage of their mandibles Strike by 2.</p>\n<p>When the moon sets or the sun rises, the werecreature returns to humanoid form and is Fatigued for 2d4 hours.</p>\n<p>Effect: Moon Frenzy</p>"},{"n":"Sentinel's Focus","a":"1","c":"offensive","t":[],"f":"","d":"<p>The wereant sentinel plants its feet in defiance of those who would move it. It gains a +2 circumstance bonus to defenses against being Shoved or Tripped, and its melee Strikes deal an additional 2d8 mental damage. These effects end when it moves from its square using anything other than Hasty Reposition.</p>"},{"n":"Knockdown","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Knockdown in its damage entry</p><hr><p><strong>Effect</strong> The monster attempts to Trip the creature. This attempt neither applies nor counts toward the monster's multiple attack penalty.</p></p>"}]},"strength-of-thousands-bestiary/book-4-secrets-of-the-temple-city/worknesh":{"lang":["Common","Mzunu"],"lore":[["Warfare Lore",30]],"gear":["Golden Blade of Mzali","Sturdy Shield (Moderate)","Splint Mail"],"abilities":[{"n":"Attack of Opportunity","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Master's Cry","a":"f","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> Worknesh rolls initiative</p>\n<p><strong>Requirements</strong> Worknesh can perceive at least one foe within 60 feet</p>\n<hr>\n<p><strong>Effect</strong> Worknesh yells a mighty rallying cry. Worknesh attempts an Intimidation check to Demoralize a single foe within 60 feet. If successful, any of her allies within 30 feet can Stride up to double their speed as their first action on their first turn of the combat.</p>"},{"n":"Shield Block","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> The monster has its shield raised and takes damage from a physical attack.</p>\n<hr>\n<p><strong>Effect</strong> The monster snaps its shield into place to deflect a blow. The shield prevents the monster from taking an amount of damage up to the shield's Hardness. The monster and the shield each take any remaining damage, possibly breaking or destroying the shield.</p></p>"},{"n":"Warmaster's Instinct","a":null,"c":"defensive","t":[],"f":"","d":"<p>Worknesh can recognize the skills of any combatants she faces. She can use Warfare Lore to Recall Knowledge about any creature, but only while in combat or observing the creature fight.</p>"},{"n":"Battle Cry","a":"1","c":"offensive","t":["auditory","concentrate","emotion","mental"],"f":"","d":"<p>Worknesh unleashes a war cry, granting herself and all allies within 60 feet a +1 status bonus to attack and damage rolls until the start of her next turn.</p>\n<p>Effect: Battle Cry</p>"},{"n":"Walkena's Fury","a":"1","c":"offensive","t":[],"f":"once per round","d":"<p><strong>Frequency</strong> once per round</p>\n<p><strong>Requirements</strong> Worknesh is within reach of an enemy designated by Walkena's Judgment</p><hr><p><strong>Effect</strong> Worknesh makes two melee Strikes against the enemy of Walkena. If both attacks hit, she combines their damage for the purpose of the creature's resistances and weaknesses.</p>"},{"n":"Walkena's Judgment","a":"1","c":"offensive","t":["concentrate","divine"],"f":"","d":"<p>Worknesh designates a single creature as an enemy of Walkena. She must be able to see or hear the creature, or she must be tracking the creature. Worknesh gains a +4 status bonus to damage against the designated creature, and she gains fast healing 5 while within 30 feet of the creature. In addition, she doesn't take the -2 circumstance penalty to attack rolls when attempting to deal nonlethal damage with an attack without the nonlethal trait and vice versa. Worknesh can have only one creature designated as an enemy of Walkena at a time. If she uses Walkena's Judgment against a creature when she already has a creature designated, the prior creature loses the designation and the new target gains the designation. This designation lasts for 24 hours.</p>"}]},"strength-of-thousands-bestiary/book-3-hurricanes-howl/yonsuu":{"lang":["Amurrun","Common","Cyclops","Thalassic"],"gear":["Dagger","Trident","Studded Leather Armor","Manacles (Good) (3)","Religious Symbol of Norgorber (Wooden)"],"abilities":[{"n":"Cat's Luck","a":"r","c":"defensive","t":["fortune"],"f":"once per day","d":"<p><strong>Frequency</strong> once per day</p>\n<p><strong>Trigger</strong> Yonsuu fails or critically fails a Reflex saving throw</p>\n<hr>\n<p><strong>Effect</strong> Yonsuu rerolls the saving throw and takes the better result.</p>"},{"n":"Hampering Strike","a":null,"c":"offensive","t":[],"f":"","d":"<p>A foe that takes damage from Yonsuu's melee Strike is Slowed 1 for 1 round (Slowed 3 if the Strike is a critical hit).</p>"},{"n":"Subduing Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>Yonsuu deals an additional 3d6 precision damage to creatures that are Frightened or within reach of at least one of their allies.</p>\n<p>Yonsuu can make an attack with this additional damage as a nonlethal attack, if they choose.</p>"}]},"strength-of-thousands-bestiary/book-2-spoken-on-the-song-wind/yorulu":{"lang":["Common","Tripkee"],"lore":[["Underworld Lore",7]],"gear":["Composite Shortbow","Sap","Shortsword","Leather Armor","Climbing Kit","Thieves' Tools","Darkvision Elixir (Lesser)","Arrows (10)"],"notes":{"saves":"+1 circumstance to all saves vs. traps","per":"+11 to find traps"},"abilities":[{"n":"+1 Circumstance to All Saves vs. Traps","a":null,"c":"defensive","t":[],"f":"","d":""},{"n":"Deny Advantage","a":null,"c":"defensive","t":[],"f":"","d":"<p>Yorulu isn't off-guard to creatures of 4th level or lower that are Hidden, Undetected, flanking, or using Surprise Attack.</p>"},{"n":"Nimble Dodge","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> Yorulu is targeted with a melee or ranged attack by an attacker it can see.</p>\n<hr>\n<p><strong>Effect</strong> The burglar gains a +2 circumstance bonus to AC against the triggering attack.</p>"},{"n":"Perception Bonus Against Traps","a":null,"c":"defensive","t":[],"f":"","d":"<p>Perception +10 (+11 to find traps)</p>"},{"n":"Mobility","a":null,"c":"offensive","t":[],"f":"","d":"<p>Yorulu Strides half their speed or less, that movement does not trigger reactions.</p>"},{"n":"Sneak Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>Yorulu deals 1d6 extra precision damage to Off-Guard creatures.</p>"},{"n":"Surprise Attack","a":null,"c":"offensive","t":[],"f":"","d":"<p>On the first round of combat, if Yorulu rolls Deception or Stealth for initiative, creatures that haven't acted are Off-Guard to them.</p>"}]}});
